function u32At(memory, byteOffset) {
  return new DataView(memory.buffer).getUint32(byteOffset, true);
}
function i32At(memory, byteOffset) {
  return new DataView(memory.buffer).getInt32(byteOffset, true);
}
function f32At(memory, byteOffset) {
  return new DataView(memory.buffer).getFloat32(byteOffset, true);
}
function setU32(memory, byteOffset, value) {
  new DataView(memory.buffer).setUint32(byteOffset, value >>> 0, true);
}
function setI32(memory, byteOffset, value) {
  new DataView(memory.buffer).setInt32(byteOffset, value | 0, true);
}
function setF32(memory, byteOffset, value) {
  new DataView(memory.buffer).setFloat32(byteOffset, value, true);
}
function bitsToF32(bits) {
  const buf = new ArrayBuffer(4);
  new DataView(buf).setUint32(0, bits >>> 0, true);
  return new DataView(buf).getFloat32(0, true);
}
function f32ToBits(value) {
  const buf = new ArrayBuffer(4);
  new DataView(buf).setFloat32(0, value, true);
  return new DataView(buf).getUint32(0, true) >>> 0;
}
/** Deterministic 32-bit LCG (xorshift) so failures are reproducible. */
function lcg32(state) {
  let x = state >>> 0;
  return () => {
    x ^= x << 13;
    x >>>= 0;
    x ^= x >>> 17;
    x ^= x << 5;
    x >>>= 0;
    return x;
  };
}
/** Random finite f32 bit pattern. */
function finiteF32Bits(rnd) {
  for (;;) {
    const b = rnd() >>> 0;
    const exp = (b >>> 23) & 0xff;
    if (exp !== 0 && exp !== 0xff) {
      return b;
    }
  }
}

/* v11 scratch: disjoint from every earlier family buffer (v2..v7 below
   0x109000, v8 at 0x110000, v9 at 0x120000). 0x130000+ is fresh. */
const V11_SCRATCH = {
  hashOut: 0x130000,      /* 2 dwords  */
  flagsOut: 0x130010,     /* 2 dwords  */
  headOut: 0x130020,      /* 2 dwords  */
  counterOut: 0x130030,   /* 2 dwords  */
  scaleOut: 0x130040,     /* 7 dwords  */
  accOut: 0x130060,       /* 2 dwords  */
  playerPlan: 0x130100,   /* 20 dwords */
  tailPlan: 0x130200,     /* 19 dwords */
};

function readPlayerPathPlan(memory, base) {
  return {
    playerPath: i32At(memory, base + 0),
    hostIsActiveEnemy: i32At(memory, base + 4),
    gate1_16c: i32At(memory, base + 8),
    effectFlagStore: i32At(memory, base + 12),
    effect168Out: u32At(memory, base + 16),
    effect16cOut: u32At(memory, base + 20),
    hostAddCharmed: i32At(memory, base + 24),
    host435c70: i32At(memory, base + 28),
    hostAf08b1: i32At(memory, base + 32),
    statusSkip: i32At(memory, base + 36),
    host417430b: i32At(memory, base + 40),
    hostBrimstone: i32At(memory, base + 44),
    hostShrink: i32At(memory, base + 48),
    bShieldStore: i32At(memory, base + 52),
    b168Out: u32At(memory, base + 56),
    b3b4Out: u32At(memory, base + 60),
    hostVirtual4c: i32At(memory, base + 64),
    hostListRelink2: i32At(memory, base + 68),
    pureCfOk: i32At(memory, base + 72),
    pureComplete: i32At(memory, base + 76),
  };
}

function readTailPlan(memory, base) {
  return {
    hash1Lo: u32At(memory, base + 0),
    hash1Hi: u32At(memory, base + 4),
    hash2Lo: u32At(memory, base + 8),
    hash2Hi: u32At(memory, base + 12),
    deltaLo: u32At(memory, base + 16),
    deltaHi: u32At(memory, base + 20),
    hostHash1: i32At(memory, base + 24),
    hostHash2: i32At(memory, base + 28),
    host7078f0: i32At(memory, base + 32),
    host7079c0: i32At(memory, base + 36),
    tailByte172: i32At(memory, base + 40),
    tailEq: i32At(memory, base + 44),
    tailWalkGate: i32At(memory, base + 48),
    host9e24a0: i32At(memory, base + 52),
    host9e24a0Second: i32At(memory, base + 56),
    walkEntered: i32At(memory, base + 60),
    hostAccAdd: i32At(memory, base + 64),
    pureCfOk: i32At(memory, base + 68),
    pureComplete: i32At(memory, base + 72),
  };
}

function readScaleOut(memory, base) {
  return {
    bC38: f32At(memory, base + 0),
    bE8: f32At(memory, base + 4),
    bE4: f32At(memory, base + 8),
    bF48: f32At(memory, base + 12),
    bF44: f32At(memory, base + 16),
    b384: f32At(memory, base + 20),
    b380: f32At(memory, base + 24),
  };
}

const W = loadExports();
const HDR = readFileSync(header, "utf8");
const SRC = readFileSync(source, "utf8");

