test("v21 header pins ABI 21 and matches the model's ABI constant", () => {
  assert.equal(W.abi(), 51);
  assert.equal(FRAME_EFFECT_PURE_ABI_VERSION, 51);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_PURE_HELPERS_ABI_VERSION = 51/);
});

test("v11 constants agree between header and model", () => {
  const pairs = [
    [FRAME_EFFECT_6FE410_HASH_K_LO, 0xd7b634db],
    [FRAME_EFFECT_6FE410_HASH_K_HI, 0x431bde82],
    [FRAME_EFFECT_6FE410_HASH_SHIFT, 0x12],
    [FRAME_EFFECT_6FE410_HASH_ACC_LO_VA, 0x00c7b630],
    [FRAME_EFFECT_6FE410_HASH_ACC_HI_VA, 0x00c7b634],
    [FRAME_EFFECT_6FE410_ROOM_COUNTER_OFF, 0x1214],
    [FRAME_EFFECT_6FE410_ROOM_LIST_OFF, 0x1218],
    [FRAME_EFFECT_6FE410_ROOM_PTR_OFF, 0x18300],
    [FRAME_EFFECT_6FE410_PLAYER_GATE_16C, 0x10000000],
    [FRAME_EFFECT_6FE410_FLAG_20, 0x20],
    [FRAME_EFFECT_6FE410_ARG1_SPECIAL_A, 9],
    [FRAME_EFFECT_6FE410_ARG1_SPECIAL_B, 7],
    [FRAME_EFFECT_6FE410_B_SHIELD_168, 0x1000000],
    [FRAME_EFFECT_6FE410_B_23C_OFF, 0x23c],
    [FRAME_EFFECT_6FE410_WALK_RECV_OFF, 0x1fc8],
    [FRAME_EFFECT_6FE410_WALK_ARG, 6],
    [FRAME_EFFECT_6FE410_STATUS_STRUCT_SIZE, 0x28],
    [FRAME_EFFECT_6FE410_SCALE_1F_VA, 0x00c3793c],
    [FRAME_EFFECT_6FE410_ZERO_F_A_VA, 0x00c7b640],
    [FRAME_EFFECT_6FE410_TAIL_BYTE_OFF, 0x172],
    [FRAME_EFFECT_6FE410_TAIL_LOG_STR_VA, 0x00b7e6bc],
    [FRAME_EFFECT_6FE410_TAIL_LOG_LEVEL, 0x10],
    [FRAME_EFFECT_6FE410_VTABLE_INIT_SLOT, 4],
    [FRAME_EFFECT_6FE410_VTABLE_4C_SLOT, 0x4c],
    [FRAME_EFFECT_6FE410_HOST_417430_VA, 0x00417430],
    [FRAME_EFFECT_6FE410_HOST_435C70_VA, 0x00435c70],
    [FRAME_EFFECT_6FE410_HOST_AF08B1_VA, 0x00af08b1],
    [FRAME_EFFECT_6FE410_HOST_7078F0_VA, 0x007078f0],
    [FRAME_EFFECT_6FE410_HOST_9E24A0_VA, 0x009e24a0],
    [FRAME_EFFECT_6FE410_HOST_9E0680_VA, 0x009e0680],
    [FRAME_EFFECT_6FE410_HOST_418500_VA, 0x00418500],
    [FRAME_EFFECT_81E9D0_VA, 0x0081e9d0],
    [FRAME_EFFECT_81E9D0_END_VA, 0x0081ecb7],
    [FRAME_EFFECT_81E9D0_NEXT_VA, 0x0081ecc0],
    [FRAME_EFFECT_81E9D0_RET_BYTES, 8],
    [FRAME_EFFECT_81E9D0_INSN_COUNT, 169],
    [FRAME_EFFECT_81E9D0_BYTE_LEN, 746],
    [FRAME_EFFECT_81E9D0_CALL_INSNS, 9],
    [FRAME_EFFECT_81E9D0_DIRECT_CALLERS, 68],
    [FRAME_EFFECT_81E9D0_RAW_DWORD_HITS, 2],
    [FRAME_EFFECT_81E9D0_CALLSITE_VA, 0x006fd958],
    [FRAME_EFFECT_81E9D0_TYPE_BIAS, 9],
    [FRAME_EFFECT_81E9D0_TYPE_SPAN, 3],
    [FRAME_EFFECT_81E9D0_UNIT_SCALE_VA, 0x00ba9ff4],
    [FRAME_EFFECT_81E9D0_UNIT_SCALE_BITS, 0x2f800000],
    [FRAME_EFFECT_81E9D0_BIAS_TABLE_VA, 0x00bacb00],
    [FRAME_EFFECT_81E9D0_ABS_MASK_VA, 0x00bacb40],
    [FRAME_EFFECT_81E9D0_ABS_MASK_BITS, 0x7fffffff],
    [FRAME_EFFECT_81E9D0_HOST_81F8B0_VA, 0x0081f8b0],
    [FRAME_EFFECT_81E9D0_HOST_812F50_VA, 0x00812f50],
    [FRAME_EFFECT_81E9D0_HOST_GENRAND_VA, 0x006eef60],
    [FRAME_EFFECT_81E9D0_ARM_A, 0],
    [FRAME_EFFECT_81E9D0_ARM_B, 1],
  ];
  const hdrCompact = HDR.replace(/\s+/g, "").toLowerCase();
  for (const [modelValue, expected] of pairs) {
    assert.equal(modelValue, expected);
    const hexForm = `=0x${expected.toString(16)}`;
    /* header pads VAs to 8 hex digits (0x00c7b630) and writes small
       constants in decimal (= 9, = 6, = 4) */
    const paddedForm = `=0x${expected.toString(16).padStart(8, "0")}`;
    assert.ok(
      hdrCompact.includes(`${hexForm}u`) || hdrCompact.includes(`${hexForm},`) ||
        hdrCompact.includes(`${paddedForm}u`) || hdrCompact.includes(`${paddedForm},`) ||
        hdrCompact.includes(`=${expected},`) ||
        hdrCompact.includes(`=${expected}u`) ||
        hdrCompact.includes(`=${expected}/*`),
      `header missing constant ${hexForm} (modelValue=${modelValue})`,
    );
  }
});

test("no uint8_t scalar parameters in the v11 declaration block", () => {
  const v11Block = HDR.slice(HDR.indexOf("ABI v11"));
  /* Only actual function declaration lines: start with 'void'/'uint32_t'
     and name an isaac_frame_effect_6fe410 export. */
  const declLines = v11Block
    .split("\n")
    .filter((ln) => /^(void|uint32_t)\s+isaac_frame_effect_6fe410_/.test(ln.trim()));
  assert.ok(declLines.length >= 8, `expected v11 declarations, got ${declLines.length}`);
  const paramTypes = declLines.flatMap((ln) => {
    const open = ln.indexOf("(");
    const close = ln.lastIndexOf(")");
    return ln
      .slice(open + 1, close)
      .split(",")
      .map((p) => p.trim().split(/\s+/)[0])
      .filter((t) => t && t !== "void");
  });
  const allowed = new Set([
    "uint32_t", "uint32_t*", "int32_t", "float", "IsaacFrameEffect6fe410ScaleOut*",
    "IsaacFrameEffect6fe410PlayerPathPlan*", "IsaacFrameEffect6fe410TailPlan*",
  ]);
  const bad = paramTypes.filter((t) => !allowed.has(t));
  assert.deepEqual(
    bad,
    [],
    `unexpected scalar parameter types in v11 declarations: ${bad.join(", ")}`,
  );
  assert.doesNotMatch(v11Block, /uint8_t/);
});

