/* ------------------------------------------------------------------ */
/* v10 regression pins (the v10 suite file was lost; these re-pin the   */
/* entry-dispatch laws that v11 builds on)                              */
/* ------------------------------------------------------------------ */

test("v10 regression: 6fe410 entry plan dispatch laws", () => {
  /* mode < 2 skips the 0x42b560 call (0x006fe4a2 jl); mode >= 2 calls
     (v10 law, machine cmp [ebp+0x14],2). */
  const lo = frameEffect6fe410EntryPlan(1, 0x3e8, 0x16, 1, 0x20000000, 3);
  assert.equal(lo.modeGe2, 0);
  assert.equal(lo.host42b560, 0);
  const hi = frameEffect6fe410EntryPlan(2, 0x3e8, 0x16, 1, 0x20000000, 3);
  assert.equal(hi.modeGe2, 1);
  assert.equal(hi.host42b560, 1);
  /* switch gate needs player + flag + arg1 == 0x3e8 (v10 law) */
  const noPlayer = frameEffect6fe410EntryPlan(3, 0x3e8, 0x16, 0, 0x20000000, 3);
  assert.equal(noPlayer.reachesSwitch, false);
  const player = frameEffect6fe410EntryPlan(3, 0x3e8, 0x16, 1, 0x20000000, 3);
  assert.equal(player.reachesSwitch, true);
  assert.equal(player.switchIndex, 0);
  assert.equal(player.slotValue, 0x2e); /* jump-table case value [0] */
  /* arg1 outside the special set never reaches the switch */
  assert.equal(
    frameEffect6fe410EntryPlan(3, 0x17, 0x16, 1, 0x20000000, 3).reachesSwitch,
    false,
  );
  /* call flag is the low bit of arg8, byte gate (v10 law) */
  assert.equal(frameEffect6fe410EntryPlan(3, 0x3e8, 0x16, 1, 0x20000000, 0x101).callFlag, 1);
  /* the continuation handoff: result==0 returns at 0x006fe50d; nonzero
     continues at 0x006fe510 (this unit's frontier) */
  assert.equal(lo.earlyReturnOnZero, true);
  assert.equal(lo.continueVa, 0x006fe510);
  assert.equal(lo.receiverOff, 0x26580);
  assert.equal(lo.call6f0090, true);
  assert.equal(lo.slotReachesReader, false); /* dead store, v10 */
});

/* ------------------------------------------------------------------ */
/* ABI v11: hash64                                                      */
/* ------------------------------------------------------------------ */

test("hash64: fixed vectors", () => {
  const m = W.memory;
  const run = (lo, hi) => {
    W.hash64(lo >>> 0, hi >>> 0, V11_SCRATCH.hashOut, V11_SCRATCH.hashOut + 4);
    return {
      lo: u32At(m, V11_SCRATCH.hashOut),
      hi: u32At(m, V11_SCRATCH.hashOut + 4),
    };
  };
  /* V = 0 -> 0 */
  assert.deepEqual(run(0, 0), { lo: 0, hi: 0 });
  /* V = 1 -> K >> 82 == 0 (K is only 64 bits) */
  assert.deepEqual(run(1, 0), { lo: 0, hi: 0 });
  /* V = 2^32 -> K >> 50 */
  const k50 = frameEffect6fe410Hash64(0, 1);
  assert.deepEqual(run(0, 1), k50);
  /* V = K -> (K*K) >> 82, nonzero */
  const kk = frameEffect6fe410Hash64(
    FRAME_EFFECT_6FE410_HASH_K_LO,
    FRAME_EFFECT_6FE410_HASH_K_HI,
  );
  assert.deepEqual(run(FRAME_EFFECT_6FE410_HASH_K_LO, FRAME_EFFECT_6FE410_HASH_K_HI), kk);
  assert.ok(kk.lo !== 0 || kk.hi !== 0);
  /* V = 2^64-1 */
  assert.deepEqual(run(0xffffffff, 0xffffffff), frameEffect6fe410Hash64(0xffffffff, 0xffffffff));
  /* null out pointers are tolerated */
  assert.doesNotThrow(() => W.hash64(1, 0, 0, 0));
});

test("hash64: randomized differential vs the BigInt oracle (unmasked)", () => {
  const m = W.memory;
  const rnd = lcg32(0x6fe510);
  for (let i = 0; i < 200; i += 1) {
    const lo = rnd();
    const hi = rnd();
    const want = frameEffect6fe410Hash64(lo, hi);
    W.hash64(lo, hi, V11_SCRATCH.hashOut, V11_SCRATCH.hashOut + 4);
    assert.equal(u32At(m, V11_SCRATCH.hashOut), want.lo, `case ${i} lo (${lo.toString(16)},${hi.toString(16)})`);
    assert.equal(u32At(m, V11_SCRATCH.hashOut + 4), want.hi, `case ${i} hi (${lo.toString(16)},${hi.toString(16)})`);
  }
});

test("hash64: both machine instances share the law (0x006fe510 and 0x006feb8d)", () => {
  /* The second instance's instruction stream is byte-identical; the tail
     plan must produce the same hash for the same V. */
  const m = W.memory;
  W.tailPlan(V11_SCRATCH.tailPlan,
             0x9abcdef0, 0x12345678, 0x9abcdef0, 0x12345678,
             0, 0, 0, 1, 1, 0);
  const p = readTailPlan(m, V11_SCRATCH.tailPlan);
  const want = frameEffect6fe410Hash64(0x9abcdef0, 0x12345678);
  assert.equal(p.hash1Lo, want.lo);
  assert.equal(p.hash1Hi, want.hi);
  assert.equal(p.hash2Lo, want.lo);
  assert.equal(p.hash2Hi, want.hi);
  assert.deepEqual(
    { lo: p.deltaLo, hi: p.deltaHi },
    { lo: 0, hi: 0 },
  );
});

/* ------------------------------------------------------------------ */
/* ABI v11: effect_flags, head stores, room counter                     */
/* ------------------------------------------------------------------ */

test("effect_flags: branch-A store law", () => {
  const m = W.memory;
  const run = (arg1, f168, f16c) => {
    W.effectFlags(arg1 >>> 0, f168 >>> 0, f16c >>> 0,
                  V11_SCRATCH.flagsOut, V11_SCRATCH.flagsOut + 4);
    return {
      out168: u32At(m, V11_SCRATCH.flagsOut),
      out16c: u32At(m, V11_SCRATCH.flagsOut + 4),
    };
  };
  const cases = [
    [3, 0x11111111, 0x22222200, 0x32222220],   /* +0x10000000 +0x20 */
    [9, 0x11111111, 0x22222200, 0x32222200],   /* arg1=9 -> no 0x20 */
    [7, 0x11111111, 0x22222200, 0x32222200],   /* arg1=7 -> no 0x20 */
    [10, 0, 0, 0x10000020],
    [0xffffffff, 0, 0, 0x10000020],             /* unmasked wide arg1 */
    [0, 0xdeadbeef, 0, 0x10000020],
  ];
  for (const [arg1, f168, f16c, want16c] of cases) {
    const r = run(arg1, f168, f16c);
    assert.equal(r.out168, f168 >>> 0, `arg1=${arg1} 168 passthrough`);
    assert.equal(r.out16c, want16c >>> 0, `arg1=${arg1} 16c law`);
  }
  /* 0x10000000 is OR'd even when already set */
  const already = run(3, 0, 0x10000000);
  assert.equal(already.out16c, 0x10000020);
  /* bit 0x20 already set in the input stays set (idempotent OR) */
  const idem = run(3, 0, 0x32222222);
  assert.equal(idem.out16c, 0x32222222);
});

test("effect_flags: wide arg1 values take the non-special path", () => {
  /* 9+0x100 = 0x109 must NOT match the arg1==9 equality test (the machine
     compares the full dword). */
  const m = W.memory;
  W.effectFlags(0x109, 0, 0, V11_SCRATCH.flagsOut, V11_SCRATCH.flagsOut + 4);
  assert.equal(u32At(m, V11_SCRATCH.flagsOut + 4), 0x10000020);
});

test("head_stores: full-word player test with zero fallback", () => {
  const m = W.memory;
  const run = (p, f28, f2c) => {
    W.headStores(p >>> 0, f28 >>> 0, f2c >>> 0,
                 V11_SCRATCH.headOut, V11_SCRATCH.headOut + 4);
    return {
      e34: u32At(m, V11_SCRATCH.headOut),
      e38: u32At(m, V11_SCRATCH.headOut + 4),
    };
  };
  assert.deepEqual(run(0, 0x12345678, 0x9abcdef0), { e34: 0, e38: 0 });
  assert.deepEqual(run(1, 0x12345678, 0x9abcdef0), { e34: 0x12345678, e38: 0x9abcdef0 });
  /* FULL word test: a nonzero high-only pointer is still "present" */
  assert.deepEqual(run(0x10000, 0x11111111, 0x22222222), { e34: 0x11111111, e38: 0x22222222 });
});

test("room_counter: old+1 with 32-bit wrap and effect field", () => {
  const m = W.memory;
  const run = (old) => {
    W.roomCounter(old >>> 0, V11_SCRATCH.counterOut, V11_SCRATCH.counterOut + 4);
    return {
      room: u32At(m, V11_SCRATCH.counterOut),
      effect: u32At(m, V11_SCRATCH.counterOut + 4),
    };
  };
  assert.deepEqual(run(0), { room: 1, effect: 0 });
  assert.deepEqual(run(0xffffffff), { room: 0, effect: 0xffffffff });
  assert.deepEqual(run(0x7fffffff), { room: 0x80000000, effect: 0x7fffffff });
});

