/* ------------------------------------------------------------------ */
/* ABI v12: FUN_0081e9d0 candidate                                     */
/* ------------------------------------------------------------------ */

/* v12 scratch sits above v11 (0x130000). 0x140000+ is fresh. */
const V12_SCRATCH = {
  geom: 0x140000,     /* 48 B */
  desc: 0x140080,     /* 8 floats */
  sampleX: 0x1400c0,
  sampleY: 0x1400c4,
  plan: 0x140100,     /* 60 B */
};

function readGeom(memory, base) {
  return {
    widthA: f32At(memory, base + 0),
    widthB: f32At(memory, base + 4),
    heightA: f32At(memory, base + 8),
    heightB: f32At(memory, base + 12),
    originAx: f32At(memory, base + 16),
    originAy: f32At(memory, base + 20),
    originBx: f32At(memory, base + 24),
    originBy: f32At(memory, base + 28),
    absAreaA: f32At(memory, base + 32),
    absAreaB: f32At(memory, base + 36),
    weight: f32At(memory, base + 40),
    bGtA: i32At(memory, base + 44),
  };
}

function readPlan81(memory, base) {
  return {
    derefDesc: i32At(memory, base + 0),
    derefCfg: i32At(memory, base + 4),
    derefType: i32At(memory, base + 8),
    lroomPath: i32At(memory, base + 12),
    aabbPath: i32At(memory, base + 16),
    host81f8b0: i32At(memory, base + 20),
    host812f50: i32At(memory, base + 24),
    hostGenrand: i32At(memory, base + 28),
    pickArmA: i32At(memory, base + 32),
    pickArmB: i32At(memory, base + 36),
    outXBits: u32At(memory, base + 40),
    outYBits: u32At(memory, base + 44),
    hostCalls: i32At(memory, base + 48),
    pureCfOk: i32At(memory, base + 52),
    pureComplete: i32At(memory, base + 56),
  };
}

function writeDesc8(memory, base, floats) {
  for (let i = 0; i < 8; i += 1) setF32(memory, base + i * 4, floats[i]);
}

test("no uint8_t scalar parameters in the v12 declaration block", () => {
  const v12Block = HDR.slice(HDR.indexOf("ABI v12"));
  const declLines = v12Block
    .split("\n")
    .filter((ln) =>
      /^(void|uint32_t|int32_t|float)\s+isaac_frame_effect_81e9d0_/.test(ln.trim()),
    );
  assert.ok(declLines.length >= 8, `expected v12 declarations, got ${declLines.length}`);
  assert.doesNotMatch(v12Block, /uint8_t/);
  assert.match(SRC, /bits & \(uint32_t\)ISAAC_FRAME_EFFECT_81E9D0_ABS_MASK_BITS/);
});

test("lroom_type: unsigned window [9,12]", () => {
  const edges = [
    [8, 0], [9, 1], [10, 1], [11, 1], [12, 1], [13, 0],
    [0, 0], [0xffffffff, 0], [0x80000000, 0], [9 + 0x100000000, 1],
  ];
  for (const [type, want] of edges) {
    const t = type >>> 0;
    assert.equal(frameEffect81e9d0LroomType(t), want, `js type ${t}`);
    assert.equal(W.lroomType81e9d0(t), want, `wasm type ${t}`);
  }
  /* signed mutant: (int32)(type-9) > 3 would accept 0x80000000+9 */
  assert.equal(W.lroomType81e9d0(0x80000009 >>> 0), 0);
  assert.equal(frameEffect81e9d0LroomType(0x80000009), 0);
});

test("unit_float: zero, one, sign-bit, all-ones", () => {
  const cases = [0, 1, 2, 0x7fffffff, 0x80000000, 0xffffffff, 0x10000];
  for (const g of cases) {
    const js = frameEffect81e9d0UnitFloat(g);
    const wasm = W.unitFloat81e9d0(g);
    assert.equal(f32ToBits(wasm), f32ToBits(js), `unit g=0x${(g >>> 0).toString(16)}`);
  }
  assert.equal(f32ToBits(frameEffect81e9d0UnitFloat(0)), 0);
  /* 0xffffffff → (float)2^32 * 2^-32 = 1.0f exactly (cvtpd2ps of 2^32). */
  assert.equal(f32ToBits(frameEffect81e9d0UnitFloat(0xffffffff)), 0x3f800000);
});

test("unit_float: randomized differential", () => {
  const rnd = lcg32(0x81e9d0);
  for (let i = 0; i < 256; i += 1) {
    const g = rnd();
    assert.equal(
      f32ToBits(W.unitFloat81e9d0(g)),
      f32ToBits(frameEffect81e9d0UnitFloat(g)),
      `unit trial ${i} g=0x${(g >>> 0).toString(16)}`,
    );
  }
});

test("fabs_bits: in-body 0x7fffffff mask, full dword", () => {
  assert.equal(W.fabsBits81e9d0(0x80000000), 0);
  assert.equal(W.fabsBits81e9d0(0xffffffff), 0x7fffffff);
  assert.equal(W.fabsBits81e9d0(0x3f800000), 0x3f800000);
  assert.equal(W.fabsBits81e9d0(0xbf800000), 0x3f800000);
  assert.equal(frameEffect81e9d0FabsBits(0xc0000001), 0x40000001);
  assert.equal(W.fabsBits81e9d0(0xc0000001), frameEffect81e9d0FabsBits(0xc0000001));
});

test("comiss_jb / comiss_jbe: NaN takes the branch", () => {
  const nan = bitsToF32(0x7fc00000);
  assert.equal(W.comissJb81e9d0(1, 2), 1);
  assert.equal(W.comissJb81e9d0(2, 1), 0);
  assert.equal(W.comissJb81e9d0(1, 1), 0);
  assert.equal(W.comissJb81e9d0(nan, 1), 1);
  assert.equal(W.comissJb81e9d0(1, nan), 1);
  assert.equal(W.comissJbe81e9d0(1, 1), 1);
  assert.equal(W.comissJbe81e9d0(1, 2), 1);
  assert.equal(W.comissJbe81e9d0(2, 1), 0);
  assert.equal(W.comissJbe81e9d0(nan, 0), 1);
  assert.equal(frameEffect81e9d0ComissJb(nan, nan), 1);
  assert.equal(frameEffect81e9d0ComissJbe(nan, nan), 1);
});

test("aabb_lerp: machine order (hi-lo)*unit + lo", () => {
  const js = frameEffect81e9d0AabbLerp(10, 30, 0.25);
  const wasm = W.aabbLerp81e9d0(10, 30, 0.25);
  assert.equal(f32ToBits(wasm), f32ToBits(js));
  assert.equal(f32ToBits(js), f32ToBits(15));
  const rnd = lcg32(0x812f50);
  for (let i = 0; i < 64; i += 1) {
    const lo = bitsToF32(finiteF32Bits(rnd));
    const hi = bitsToF32(finiteF32Bits(rnd));
    const u = bitsToF32(finiteF32Bits(rnd));
    assert.equal(
      f32ToBits(W.aabbLerp81e9d0(lo, hi, u)),
      f32ToBits(frameEffect81e9d0AabbLerp(lo, hi, u)),
      `lerp trial ${i}`,
    );
  }
});

test("lroom_geom + sample: fixed L plus arm pick", () => {
  const desc = [0, 0, 40, 20, 0, 40, 20, 80];
  const margin = 0;
  const jsGeom = frameEffect81e9d0LroomGeom(desc, margin);
  writeDesc8(W.memory, V12_SCRATCH.desc, desc);
  W.lroomGeom81e9d0(V12_SCRATCH.geom, V12_SCRATCH.desc, margin);
  const wg = readGeom(W.memory, V12_SCRATCH.geom);
  assert.equal(f32ToBits(wg.widthA), f32ToBits(jsGeom.widthA));
  assert.equal(f32ToBits(wg.widthB), f32ToBits(jsGeom.widthB));
  assert.equal(f32ToBits(wg.heightA), f32ToBits(jsGeom.heightA));
  assert.equal(f32ToBits(wg.heightB), f32ToBits(jsGeom.heightB));
  assert.equal(f32ToBits(wg.weight), f32ToBits(jsGeom.weight));
  assert.equal(wg.bGtA, jsGeom.bGtA);
  const armJs = frameEffect81e9d0LroomArm(jsGeom, 0);
  assert.equal(W.lroomArm81e9d0(V12_SCRATCH.geom, 0), armJs);
  const sample = frameEffect81e9d0LroomSample(jsGeom, armJs, 0.5, 0.25);
  W.lroomSample81e9d0(
    V12_SCRATCH.sampleX, V12_SCRATCH.sampleY,
    V12_SCRATCH.geom, armJs, 0.5, 0.25,
  );
  assert.equal(f32ToBits(f32At(W.memory, V12_SCRATCH.sampleX)), f32ToBits(sample.x));
  assert.equal(f32ToBits(f32At(W.memory, V12_SCRATCH.sampleY)), f32ToBits(sample.y));
});

test("entry_plan: AABB vs L-room host counts and pre-clamp bits", () => {
  const desc = [10, 20, 50, 40, 10, 60, 30, 100];
  writeDesc8(W.memory, V12_SCRATCH.desc, desc);
  const g0 = 1;
  const g1 = 2;
  const g2 = 3;
  /* type 5 → AABB */
  W.entryPlan81e9d0(
    V12_SCRATCH.plan, 5, 0, 0, 0, 100, 80, 0, g0, g1, g2,
  );
  const aabb = readPlan81(W.memory, V12_SCRATCH.plan);
  const aabbJs = frameEffect81e9d0EntryPlan(5, 0, 0, 0, 100, 80, null, g0, g1, g2);
  assert.equal(aabb.lroomPath, 0);
  assert.equal(aabb.aabbPath, 1);
  assert.equal(aabb.host81f8b0, 0);
  assert.equal(aabb.host812f50, 1);
  assert.equal(aabb.hostGenrand, 2);
  assert.equal(aabb.hostCalls, 3);
  assert.equal(aabb.pureComplete, 0);
  assert.equal(aabb.outXBits, aabbJs.outXBits);
  assert.equal(aabb.outYBits, aabbJs.outYBits);
  /* type 9 → L-room */
  W.entryPlan81e9d0(
    V12_SCRATCH.plan, 9, 0, 0, 0, 100, 80, V12_SCRATCH.desc, g0, g1, g2,
  );
  const lr = readPlan81(W.memory, V12_SCRATCH.plan);
  const lrJs = frameEffect81e9d0EntryPlan(9, 0, 0, 0, 100, 80, desc, g0, g1, g2);
  assert.equal(lr.lroomPath, 1);
  assert.equal(lr.aabbPath, 0);
  assert.equal(lr.host81f8b0, 1);
  assert.equal(lr.host812f50, 0);
  assert.equal(lr.hostGenrand, 3);
  assert.equal(lr.hostCalls, 4);
  assert.equal(lr.pickArmA, lrJs.pickArmA);
  assert.equal(lr.pickArmB, lrJs.pickArmB);
  assert.equal(lr.outXBits, lrJs.outXBits);
  assert.equal(lr.outYBits, lrJs.outYBits);
  assert.equal(lr.derefDesc, 1);
  assert.equal(lr.pureCfOk, 1);
});

test("entry_plan: family callsite margin 0 and type-window edges", () => {
  const desc = [0, 0, 80, 40, 40, 40, 80, 80];
  writeDesc8(W.memory, V12_SCRATCH.desc, desc);
  for (const type of [8, 9, 12, 13]) {
    W.entryPlan81e9d0(
      V12_SCRATCH.plan, type, 0, 4, 6, 90, 70, V12_SCRATCH.desc, 11, 22, 33,
    );
    const p = readPlan81(W.memory, V12_SCRATCH.plan);
    const js = frameEffect81e9d0EntryPlan(
      type, 0, 4, 6, 90, 70, desc, 11, 22, 33,
    );
    assert.equal(p.lroomPath, js.lroomPath, `type ${type} path`);
    assert.equal(p.hostGenrand, js.hostGenrand);
    assert.equal(p.outXBits, js.outXBits, `type ${type} x`);
    assert.equal(p.outYBits, js.outYBits, `type ${type} y`);
  }
});

test("v12 mutants: signed type gate, mask drop, NaN miss, ABI pin", () => {
  /* M1 signed type: 0x80000009 must stay AABB (unsigned ja). */
  assert.equal(W.lroomType81e9d0(0x80000009 >>> 0), 0);
  /* M2 mask drop: fabs of a negative finite must clear the sign bit only. */
  assert.equal(W.fabsBits81e9d0(0xbf800000), 0x3f800000);
  /* M3 NaN miss: comiss jb on NaN must be 1, not 0. */
  assert.equal(W.comissJb81e9d0(bitsToF32(0x7fc00000), 0), 1);
  /* M4 ABI pin. */
  assert.equal(W.abi(), 51);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_PURE_HELPERS_ABI_VERSION = 51/);
  /* M5 byte-len / insn census pins (header + model). */
  assert.equal(FRAME_EFFECT_81E9D0_INSN_COUNT, 169);
  assert.equal(FRAME_EFFECT_81E9D0_BYTE_LEN, 746);
  assert.equal(FRAME_EFFECT_81E9D0_DIRECT_CALLERS, 68);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_81E9D0_BYTE_LEN = 746/);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_81E9D0_INSN_COUNT = 169/);
});

/* ------------------------------------------------------------------ */
/* ABI v13: FUN_0081ecc0 random grid index                             */
/* ------------------------------------------------------------------ */

/* v13 scratch sits above v12 (0x140000). 0x150000+ is fresh. */
const V13_SCRATCH = {
  rowIn: 0x150000,   /* 8 dwords */
  rowOut: 0x150040,  /* 8 dwords */
  spanDx: 0x150080,
  spanDy: 0x150084,
  sampleX: 0x150088,
  sampleY: 0x15008c,
  plan: 0x150100,    /* 56 B */
};

function readPlan81ecc0(memory, base) {
  return {
    derefDesc: i32At(memory, base + 0),
    derefCfg: i32At(memory, base + 4),
    derefType: i32At(memory, base + 8),
    lroomPath: i32At(memory, base + 12),
    aabbPath: i32At(memory, base + 16),
    host81fb70: i32At(memory, base + 20),
    host7e9020: i32At(memory, base + 24),
    hostCalls: i32At(memory, base + 28),
    inBounds: i32At(memory, base + 32),
    result: i32At(memory, base + 36),
    outX: i32At(memory, base + 40),
    outY: i32At(memory, base + 44),
    pureCfOk: i32At(memory, base + 48),
    pureComplete: i32At(memory, base + 52),
  };
}

function writeRow8(memory, base, dwords) {
  for (let i = 0; i < 8; i += 1) setI32(memory, base + i * 4, dwords[i] | 0);
}

test("v13 constants agree between header and model", () => {
  const pairs = [
    [FRAME_EFFECT_81ECC0_VA, 0x0081ecc0],
    [FRAME_EFFECT_81ECC0_END_VA, 0x0081edca],
    [FRAME_EFFECT_81ECC0_NEXT_VA, 0x0081edd0],
    [FRAME_EFFECT_81ECC0_RET_BYTES, 4],
    [FRAME_EFFECT_81ECC0_INSN_COUNT, 103],
    [FRAME_EFFECT_81ECC0_BYTE_LEN, 269],
    [FRAME_EFFECT_81ECC0_CALL_INSNS, 3],
    [FRAME_EFFECT_81ECC0_DIRECT_CALLERS, 3],
    [FRAME_EFFECT_81ECC0_RAW_DWORD_HITS, 2],
    [FRAME_EFFECT_81ECC0_CALLSITE_A_VA, 0x0068e070],
    [FRAME_EFFECT_81ECC0_CALLSITE_B_VA, 0x007f39a3],
    [FRAME_EFFECT_81ECC0_CALLSITE_C_VA, 0x007f4391],
    [FRAME_EFFECT_81ECC0_ADDR_TAKEN_A_VA, 0x0086c8a1],
    [FRAME_EFFECT_81ECC0_ADDR_TAKEN_B_VA, 0x0089118a],
    [FRAME_EFFECT_81ECC0_WIDTH_OFF, 0x0c],
    [FRAME_EFFECT_81ECC0_HEIGHT_OFF, 0x10],
    [FRAME_EFFECT_81ECC0_TABLE_BASE, 0x00c35b80],
    [FRAME_EFFECT_81ECC0_ROW_STRIDE, 0x20],
    [FRAME_EFFECT_81ECC0_ROW_DWORDS, 8],
    [FRAME_EFFECT_81ECC0_RNG_SHIFTS_VA, 0x00b1f4ec],
    [FRAME_EFFECT_81ECC0_RNG_SHIFT3_VA, 0x00b1f4f4],
    [FRAME_EFFECT_81ECC0_RNG_SHIFT1, 1],
    [FRAME_EFFECT_81ECC0_RNG_SHIFT2, 9],
    [FRAME_EFFECT_81ECC0_RNG_SHIFT3, 29],
    [FRAME_EFFECT_81ECC0_HOST_81FB70_VA, 0x0081fb70],
    [FRAME_EFFECT_81ECC0_HOST_7E9020_VA, 0x007e9020],
  ];
  const hdrCompact = HDR.replace(/\s+/g, "").toLowerCase();
  for (const [modelValue, expected] of pairs) {
    assert.equal(modelValue, expected);
    const hexForm = `=0x${expected.toString(16)}`;
    const paddedForm = `=0x${expected.toString(16).padStart(8, "0")}`;
    assert.ok(
      hdrCompact.includes(`${hexForm}u`) || hdrCompact.includes(`${hexForm},`) ||
        hdrCompact.includes(`${paddedForm}u`) || hdrCompact.includes(`${paddedForm},`) ||
        hdrCompact.includes(`=${expected},`) ||
        hdrCompact.includes(`=${expected}u`) ||
        hdrCompact.includes(`=${expected}/*`),
      `header missing constant ${hexForm} (modelValue=${modelValue})`,
    );
  }
  assert.equal(FRAME_EFFECT_81ECC0_FAIL, -1);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_81ECC0_FAIL = \(int32_t\)0xffffffff/);
});

test("no uint8_t scalar parameters in the v13 declaration block", () => {
  const v13Block = HDR.slice(HDR.indexOf("ABI v13"));
  const declLines = v13Block
    .split("\n")
    .filter((ln) =>
      /^(void|uint32_t|int32_t)\s+isaac_frame_effect_81ecc0_/.test(ln.trim()),
    );
  assert.ok(declLines.length >= 8, `expected v13 declarations, got ${declLines.length}`);
  assert.doesNotMatch(v13Block, /uint8_t/);
});

test("lroom_type: v13 wrapper is the v12 unsigned window", () => {
  const edges = [
    [8, 0], [9, 1], [10, 1], [11, 1], [12, 1], [13, 0],
    [0, 0], [0xffffffff, 0], [0x80000000, 0], [0x80000009, 0],
  ];
  for (const [type, want] of edges) {
    const t = type >>> 0;
    assert.equal(frameEffect81ecc0LroomType(t), want, `js type ${t}`);
    assert.equal(W.lroomType81ecc0(t), want, `wasm type ${t}`);
    assert.equal(W.lroomType81ecc0(t), W.lroomType81e9d0(t));
    assert.equal(frameEffect81ecc0LroomType(t), frameEffect81e9d0LroomType(t));
  }
});

test("table_row_va: type<<5 + DAT_00c35b80, 32-bit wrap", () => {
  assert.equal(W.tableRowVa81ecc0(0) >>> 0, 0x00c35b80);
  assert.equal(W.tableRowVa81ecc0(9) >>> 0, 0x00c35b80 + 9 * 0x20);
  assert.equal(W.tableRowVa81ecc0(12) >>> 0, 0x00c35b80 + 12 * 0x20);
  /* 0x08000000 << 5 overflows the dword. */
  assert.equal(W.tableRowVa81ecc0(0x08000000) >>> 0, 0x00c35b80);
  assert.equal(
    W.tableRowVa81ecc0(0x80000000) >>> 0,
    frameEffect81ecc0TableRowVa(0x80000000),
  );
  const rnd = lcg32(0x81ecc0);
  for (let i = 0; i < 64; i += 1) {
    const t = rnd();
    assert.equal(
      W.tableRowVa81ecc0(t) >>> 0,
      frameEffect81ecc0TableRowVa(t),
      `row va trial ${i}`,
    );
  }
});

test("copy_row: eight dwords, null skip", () => {
  const row = [14, 1, 26, 7, 1, 8, 26, 14];
  writeRow8(W.memory, V13_SCRATCH.rowIn, row);
  writeRow8(W.memory, V13_SCRATCH.rowOut, [9, 9, 9, 9, 9, 9, 9, 9]);
  W.copyRow81ecc0(V13_SCRATCH.rowOut, V13_SCRATCH.rowIn);
  const js = frameEffect81ecc0CopyRow(row);
  for (let i = 0; i < 8; i += 1) {
    assert.equal(i32At(W.memory, V13_SCRATCH.rowOut + i * 4), js[i]);
  }
  writeRow8(W.memory, V13_SCRATCH.rowOut, [3, 3, 3, 3, 3, 3, 3, 3]);
  W.copyRow81ecc0(0, V13_SCRATCH.rowIn);
  W.copyRow81ecc0(V13_SCRATCH.rowOut, 0);
  for (let i = 0; i < 8; i += 1) {
    assert.equal(i32At(W.memory, V13_SCRATCH.rowOut + i * 4), 3);
  }
});

test("grid_in_bounds: signed test/js + cmp/jge", () => {
  assert.equal(W.gridInBounds81ecc0(0, 0, 13, 7), 1);
  assert.equal(W.gridInBounds81ecc0(12, 6, 13, 7), 1);
  assert.equal(W.gridInBounds81ecc0(13, 0, 13, 7), 0);
  assert.equal(W.gridInBounds81ecc0(0, 7, 13, 7), 0);
  assert.equal(W.gridInBounds81ecc0(-1, 0, 13, 7), 0);
  assert.equal(W.gridInBounds81ecc0(0, -1, 13, 7), 0);
  /* unsigned mutant: 5 <u -1 is true; signed 5 >= -1 is fail. */
  assert.equal(W.gridInBounds81ecc0(5, 5, -1, -1), 0);
  assert.equal(frameEffect81ecc0GridInBounds(5, 5, -1, -1), 0);
  /* 0x7fffffff >= 0x80000000 signed; unsigned would accept. */
  assert.equal(W.gridInBounds81ecc0(0x7fffffff, 0, 0x80000000, 1), 0);
  assert.equal(frameEffect81ecc0GridInBounds(0x7fffffff, 0, 0x80000000, 1), 0);
});

test("grid_index + result: imul wrap and fail=-1", () => {
  assert.equal(W.gridIndex81ecc0(3, 2, 13), 29);
  assert.equal(W.result81ecc0(3, 2, 13, 7), 29);
  assert.equal(W.result81ecc0(-1, 0, 13, 7), -1);
  assert.equal(W.result81ecc0(0, 7, 13, 7), -1);
  /* 0x40000000 * 4 wraps. */
  assert.equal(W.gridIndex81ecc0(5, 4, 0x40000000), 5);
  assert.equal(frameEffect81ecc0GridIndex(5, 4, 0x40000000), 5);
  const rnd = lcg32(0x81ed48);
  for (let i = 0; i < 128; i += 1) {
    const x = rnd() | 0;
    const y = rnd() | 0;
    const w = (rnd() & 0x3f) + 1;
    const h = (rnd() & 0x3f) + 1;
    assert.equal(
      W.result81ecc0(x, y, w, h),
      frameEffect81ecc0Result(x, y, w, h),
      `result trial ${i}`,
    );
  }
});

test("aabb_span + aabb_sample: 32-bit sub/add", () => {
  W.aabbSpan81ecc0(V13_SCRATCH.spanDx, V13_SCRATCH.spanDy, 1, 1, 13, 7);
  const span = frameEffect81ecc0AabbSpan(1, 1, 13, 7);
  assert.equal(i32At(W.memory, V13_SCRATCH.spanDx), span.dx);
  assert.equal(i32At(W.memory, V13_SCRATCH.spanDy), span.dy);
  assert.equal(span.dx, 12);
  assert.equal(span.dy, 6);
  W.aabbSample81ecc0(V13_SCRATCH.sampleX, V13_SCRATCH.sampleY, 1, 1, 4, 2);
  const sample = frameEffect81ecc0AabbSample(1, 1, 4, 2);
  assert.equal(i32At(W.memory, V13_SCRATCH.sampleX), sample.x);
  assert.equal(i32At(W.memory, V13_SCRATCH.sampleY), sample.y);
  assert.equal(sample.x, 5);
  assert.equal(sample.y, 3);
  /* wrap */
  const wrap = frameEffect81ecc0AabbSample(0x7fffffff, 0, 1, 0);
  assert.equal(wrap.x, (0x7fffffff + 1) | 0);
  W.aabbSample81ecc0(V13_SCRATCH.sampleX, V13_SCRATCH.sampleY, 0x7fffffff, 0, 1, 0);
  assert.equal(i32At(W.memory, V13_SCRATCH.sampleX), wrap.x);
  W.aabbSpan81ecc0(0, V13_SCRATCH.spanDy, 2, 3, 5, 9);
  assert.equal(i32At(W.memory, V13_SCRATCH.spanDy), 6);
});

test("entry_plan: L-room vs AABB host counts and grid result", () => {
  /* type 5 → AABB, table row like type 1: x0=1,y0=1,x1=13,y1=7 */
  W.entryPlan81ecc0(V13_SCRATCH.plan, 5, 15, 9, 1, 1, 13, 7, 4, 2);
  const aabb = readPlan81ecc0(W.memory, V13_SCRATCH.plan);
  const aabbJs = frameEffect81ecc0EntryPlan(5, 15, 9, 1, 1, 13, 7, 4, 2);
  assert.equal(aabb.lroomPath, 0);
  assert.equal(aabb.aabbPath, 1);
  assert.equal(aabb.host81fb70, 0);
  assert.equal(aabb.host7e9020, 2);
  assert.equal(aabb.hostCalls, 2);
  assert.equal(aabb.outX, 5);
  assert.equal(aabb.outY, 3);
  assert.equal(aabb.inBounds, 1);
  assert.equal(aabb.result, 5 + 3 * 15);
  assert.equal(aabb.result, aabbJs.result);
  assert.equal(aabb.pureComplete, 0);
  /* type 9 → L-room, host XY used raw */
  W.entryPlan81ecc0(V13_SCRATCH.plan, 9, 15, 9, 14, 1, 26, 7, 4, 2);
  const lr = readPlan81ecc0(W.memory, V13_SCRATCH.plan);
  const lrJs = frameEffect81ecc0EntryPlan(9, 15, 9, 14, 1, 26, 7, 4, 2);
  assert.equal(lr.lroomPath, 1);
  assert.equal(lr.aabbPath, 0);
  assert.equal(lr.host81fb70, 1);
  assert.equal(lr.host7e9020, 0);
  assert.equal(lr.hostCalls, 1);
  assert.equal(lr.outX, 4);
  assert.equal(lr.outY, 2);
  assert.equal(lr.result, lrJs.result);
  assert.equal(lr.derefDesc, 1);
  assert.equal(lr.pureCfOk, 1);
  /* fail path */
  W.entryPlan81ecc0(V13_SCRATCH.plan, 9, 15, 9, 0, 0, 0, 0, -1, 0);
  const fail = readPlan81ecc0(W.memory, V13_SCRATCH.plan);
  assert.equal(fail.inBounds, 0);
  assert.equal(fail.result, -1);
});

test("v13 mutants: signed type, signed bounds, imul, AABB add, ABI pin", () => {
  /* M1 signed type: 0x80000009 must stay AABB (unsigned ja). */
  assert.equal(W.lroomType81ecc0(0x80000009 >>> 0), 0);
  /* M2 unsigned bounds: x=5 width=-1 must fail. */
  assert.equal(W.gridInBounds81ecc0(5, 5, -1, -1), 0);
  /* M3 imul drop: index is width*y+x, not x+y. */
  assert.equal(W.gridIndex81ecc0(3, 2, 13), 29);
  /* M4 AABB add drop: sample is origin + draw. */
  W.aabbSample81ecc0(V13_SCRATCH.sampleX, V13_SCRATCH.sampleY, 10, 20, 3, 4);
  assert.equal(i32At(W.memory, V13_SCRATCH.sampleX), 13);
  assert.equal(i32At(W.memory, V13_SCRATCH.sampleY), 24);
  /* M5 ABI pin + census. */
  assert.equal(W.abi(), 51);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_PURE_HELPERS_ABI_VERSION = 51/);
  assert.equal(FRAME_EFFECT_81ECC0_INSN_COUNT, 103);
  assert.equal(FRAME_EFFECT_81ECC0_BYTE_LEN, 269);
  assert.equal(FRAME_EFFECT_81ECC0_DIRECT_CALLERS, 3);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_81ECC0_BYTE_LEN = 269/);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_81ECC0_INSN_COUNT = 103/);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_81ECC0_NEXT_VA = 0x0081edd0u/);
});

