test("0x0081ee20 stays irreducible; v16 peels callee 0x0081fb20", () => {
  assert.equal(W.abi(), 51);
  assert.equal(FRAME_EFFECT_PURE_ABI_VERSION, 51);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_PURE_HELPERS_ABI_VERSION = 51/);
  assert.match(HDR, /FUN_0081ee20 IRREDUCIBLE/);
  assert.match(HDR, /first_ret 0x0081eebf/);
  assert.match(HDR, /NOT a Get\/SetBrokenWatchState wrapper/);
  assert.match(SRC, /FUN_0081ee20 IRREDUCIBLE/);
  assert.equal(FRAME_EFFECT_81EDF0_NEXT_VA, 0x0081ee20);
  const notes = HDR.slice(HDR.indexOf("FUN_0081ee20 IRREDUCIBLE"));
  assert.match(notes, /Does not call 0x0081edd0 or/);
  assert.doesNotMatch(notes, /E8[^\n]*0x0081edd0/);
  assert.doesNotMatch(notes, /E8[^\n]*0x0081edf0/);
  assert.match(notes, /24/);
  assert.match(notes, /0x0081fb20/);
  assert.match(notes, /v16 peels/);
  assert.equal(FRAME_EFFECT_81FB20_VA, 0x0081fb20);
  assert.equal(FRAME_EFFECT_81FB20_NEXT_VA, 0x0081fb70);
});

