/* ABI v16: FUN_0081fb20 Room::GetLRoomTileDesc                        */
/* ------------------------------------------------------------------ */

/* v16 scratch sits above v15 (0x170000). 0x180000+ is fresh. */
const V16_SCRATCH = {
  rowIn: 0x180000, /* 8 dwords */
  rowOut: 0x180040, /* 8 dwords */
  plan: 0x180100, /* 32 B */
};

function readPlan81fb20(memory, base) {
  return {
    derefDesc: i32At(memory, base + 0),
    derefCfg: i32At(memory, base + 4),
    derefType: i32At(memory, base + 8),
    tableRowVa: u32At(memory, base + 12),
    copyRow: i32At(memory, base + 16),
    returnOut: u32At(memory, base + 20),
    hostCalls: i32At(memory, base + 24),
    pureComplete: i32At(memory, base + 28),
  };
}

