test("table_row_va: v16 wrapper is the v13 shl-5 + DAT_00c35b80 law", () => {
  assert.equal(W.tableRowVa81fb20(0) >>> 0, 0x00c35b80);
  assert.equal(W.tableRowVa81fb20(1) >>> 0, 0x00c35b80 + 0x20);
  assert.equal(W.tableRowVa81fb20(5) >>> 0, 0x00c35b80 + 5 * 0x20);
  assert.equal(W.tableRowVa81fb20(9) >>> 0, 0x00c35b80 + 9 * 0x20);
  /* 0x08000000 << 5 overflows the dword. */
  assert.equal(W.tableRowVa81fb20(0x08000000) >>> 0, 0x00c35b80);
  assert.equal(
    W.tableRowVa81fb20(0x80000000) >>> 0,
    frameEffect81fb20TableRowVa(0x80000000),
  );
  const rnd = lcg32(0x81fb20);
  for (let i = 0; i < 128; i += 1) {
    const t = rnd();
    assert.equal(
      W.tableRowVa81fb20(t) >>> 0,
      frameEffect81fb20TableRowVa(t),
      `row va trial ${i}`,
    );
    assert.equal(
      frameEffect81fb20TableRowVa(t),
      frameEffect81ecc0TableRowVa(t),
      `v13 ref trial ${i}`,
    );
  }
});

test("copy_row: eight dwords, null skip, last dword included", () => {
  const row = [14, 1, 26, 7, 1, 8, 26, 14];
  writeRow8(W.memory, V16_SCRATCH.rowIn, row);
  writeRow8(W.memory, V16_SCRATCH.rowOut, [9, 9, 9, 9, 9, 9, 9, 9]);
  W.copyRow81fb20(V16_SCRATCH.rowOut, V16_SCRATCH.rowIn);
  const js = frameEffect81fb20CopyRow(row);
  for (let i = 0; i < 8; i += 1) {
    assert.equal(i32At(W.memory, V16_SCRATCH.rowOut + i * 4), js[i], `dword ${i}`);
  }
  writeRow8(W.memory, V16_SCRATCH.rowOut, [3, 3, 3, 3, 3, 3, 3, 3]);
  W.copyRow81fb20(0, V16_SCRATCH.rowIn);
  W.copyRow81fb20(V16_SCRATCH.rowOut, 0);
  for (let i = 0; i < 8; i += 1) {
    assert.equal(i32At(W.memory, V16_SCRATCH.rowOut + i * 4), 3);
  }
});

test("return_out: identity of [ebp+8], full dword", () => {
  const edges = [0, 1, 0x100, 0x180040, 0x80000000, 0xffffffff];
  for (const p of edges) {
    assert.equal(W.returnOut81fb20(p) >>> 0, p >>> 0, `out ${p}`);
    assert.equal(frameEffect81fb20ReturnOut(p), p >>> 0);
  }
});

test("entry_plan: always copy, no type gate, pure_complete, null skip", () => {
  W.entryPlan81fb20(V16_SCRATCH.plan, 5, 0x2000);
  const plan = readPlan81fb20(W.memory, V16_SCRATCH.plan);
  const js = frameEffect81fb20EntryPlan(5, 0x2000);
  assert.equal(plan.derefDesc, 1);
  assert.equal(plan.derefCfg, 1);
  assert.equal(plan.derefType, 1);
  assert.equal(plan.copyRow, 1);
  assert.equal(plan.hostCalls, 0);
  assert.equal(plan.pureComplete, 1);
  assert.equal(plan.tableRowVa >>> 0, js.tableRowVa);
  assert.equal(plan.returnOut >>> 0, 0x2000);
  /* type 5 is outside the v13 L-room window [9,12]; copy still runs. */
  assert.equal(frameEffect81ecc0LroomType(5), 0);
  assert.equal(plan.copyRow, 1);
  /* type 9 (L-room) also copies — no gate either way. */
  W.entryPlan81fb20(V16_SCRATCH.plan, 9, 0x3000);
  const lroom = readPlan81fb20(W.memory, V16_SCRATCH.plan);
  assert.equal(lroom.copyRow, 1);
  assert.equal(lroom.tableRowVa >>> 0, frameEffect81fb20TableRowVa(9));
  W.entryPlan81fb20(0, 1, 2);
  const afterNull = readPlan81fb20(W.memory, V16_SCRATCH.plan);
  assert.equal(afterNull.returnOut >>> 0, 0x3000);
});

test("v16 mutants: shl-4, wrap drop, 7-dword copy, L-room gate, ABI pin", () => {
  /* M1 shl-4: stride is 0x20, not 0x10. */
  assert.equal(W.tableRowVa81fb20(1) >>> 0, 0x00c35b80 + 0x20);
  assert.notEqual(W.tableRowVa81fb20(1) >>> 0, 0x00c35b80 + 0x10);
  /* M2 wrap drop: 0x08000000<<5 + base wraps to base, not 0x10c35b80. */
  assert.equal(W.tableRowVa81fb20(0x08000000) >>> 0, 0x00c35b80);
  assert.notEqual(W.tableRowVa81fb20(0xffffffff) >>> 0, 0x00c35b80);
  /* M3 7-dword copy: last dword (index 7) must land. */
  const row = [1, 2, 3, 4, 5, 6, 7, 0x12345678];
  writeRow8(W.memory, V16_SCRATCH.rowIn, row);
  writeRow8(W.memory, V16_SCRATCH.rowOut, [0, 0, 0, 0, 0, 0, 0, 0]);
  W.copyRow81fb20(V16_SCRATCH.rowOut, V16_SCRATCH.rowIn);
  assert.equal(i32At(W.memory, V16_SCRATCH.rowOut + 28), 0x12345678);
  /* M4 L-room type gate: type 2/5 (caller types) still copy. */
  W.entryPlan81fb20(V16_SCRATCH.plan, 2, 0x10);
  assert.equal(readPlan81fb20(W.memory, V16_SCRATCH.plan).copyRow, 1);
  W.entryPlan81fb20(V16_SCRATCH.plan, 0xffffffff, 0x10);
  assert.equal(readPlan81fb20(W.memory, V16_SCRATCH.plan).copyRow, 1);
  /* M5 return_out is the buffer, not 0 and not a field. */
  assert.equal(W.returnOut81fb20(0x180040) >>> 0, 0x180040);
  /* M6 pure_complete / host_calls. */
  W.entryPlan81fb20(V16_SCRATCH.plan, 0, 1);
  const p = readPlan81fb20(W.memory, V16_SCRATCH.plan);
  assert.equal(p.hostCalls, 0);
  assert.equal(p.pureComplete, 1);
  /* M7 ABI pin + census. */
  assert.equal(W.abi(), 51);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_PURE_HELPERS_ABI_VERSION = 51/);
  assert.equal(FRAME_EFFECT_81FB20_INSN_COUNT, 29);
  assert.equal(FRAME_EFFECT_81FB20_BYTE_LEN, 78);
  assert.equal(FRAME_EFFECT_81FB20_DIRECT_CALLERS, 2);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_81FB20_BYTE_LEN = 78/);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_81FB20_INSN_COUNT = 29/);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_81FB20_NEXT_VA = 0x0081fb70u/);
  assert.match(HDR, /GetLRoomTileDesc/);
});

/* ------------------------------------------------------------------ */
/* ABI v17: FUN_0081fb70 LRoomTileDesc::GetRandomTile                  */
/* ------------------------------------------------------------------ */

/* v17 scratch sits above v16 (0x180000). 0x190000+ is fresh. */
const V17_SCRATCH = {
  desc: 0x190000, /* 8 dwords */
  xy: 0x190040, /* 2 dwords */
  dx1: 0x190060,
  dy1: 0x190064,
  dx2: 0x190068,
  dy2: 0x19006c,
  plan: 0x190100, /* 36 B */
};

function readPlan81fb70(memory, base) {
  return {
    seedZero: i32At(memory, base + 0),
    fatal: i32At(memory, base + 4),
    mixed0: u32At(memory, base + 8),
    pickA: i32At(memory, base + 12),
    outX: i32At(memory, base + 16),
    outY: i32At(memory, base + 20),
    applyXy: i32At(memory, base + 24),
    hostCalls: i32At(memory, base + 28),
    pureComplete: i32At(memory, base + 32),
  };
}

test("v17 constants agree between header and model", () => {
  const pairs = [
    [FRAME_EFFECT_81FB70_VA, 0x0081fb70],
    [FRAME_EFFECT_81FB70_END_VA, 0x0081fd51],
    [FRAME_EFFECT_81FB70_NEXT_VA, 0x0081fd60],
    [FRAME_EFFECT_81FB70_RET_BYTES, 8],
    [FRAME_EFFECT_81FB70_INSN_COUNT, 203],
    [FRAME_EFFECT_81FB70_BYTE_LEN, 484],
    [FRAME_EFFECT_81FB70_CALL_INSNS, 5],
    [FRAME_EFFECT_81FB70_DIRECT_CALLERS, 1],
    [FRAME_EFFECT_81FB70_RAW_DWORD_HITS, 0],
    [FRAME_EFFECT_81FB70_INT3_PAD, 12],
    [FRAME_EFFECT_81FB70_CALLSITE_VA, 0x0081ed21],
    [FRAME_EFFECT_81FB70_RET_A_VA, 0x0081fc9b],
    [FRAME_EFFECT_81FB70_RET_B_VA, 0x0081fcbe],
    [FRAME_EFFECT_81FB70_RET_C_VA, 0x0081fd51],
    [FRAME_EFFECT_81FB70_HIGH_OFF, 0],
    [FRAME_EFFECT_81FB70_LOW_OFF, 0x10],
    [FRAME_EFFECT_81FB70_DESC_DWORDS, 8],
    [FRAME_EFFECT_81FB70_XY_DWORDS, 2],
    [FRAME_EFFECT_81FB70_HOST_LOG_VA, 0x00a112c0],
    [FRAME_EFFECT_81FB70_FATAL_STR_VA, 0x00b6bf54],
    [FRAME_EFFECT_81FB70_FATAL_LEVEL, 0x10],
    [FRAME_EFFECT_81FB70_RNG_SHIFTS_VA, 0x00b1f4ec],
    [FRAME_EFFECT_81FB70_RNG_SHIFT3_VA, 0x00b1f4f4],
    [FRAME_EFFECT_81FB70_RNG_SHIFT1, 1],
    [FRAME_EFFECT_81FB70_RNG_SHIFT2, 9],
    [FRAME_EFFECT_81FB70_RNG_SHIFT3, 29],
  ];
  const hdrCompact = HDR.replace(/\s+/g, "").toLowerCase();
  for (const [modelValue, expected] of pairs) {
    assert.equal(modelValue, expected);
    const hexForm = `=0x${expected.toString(16)}`;
    const paddedForm = `=0x${expected.toString(16).padStart(8, "0")}`;
    assert.ok(
      hdrCompact.includes(`${hexForm}u`) || hdrCompact.includes(`${hexForm},`) ||
        hdrCompact.includes(`${paddedForm}u`) || hdrCompact.includes(`${paddedForm},`) ||
        hdrCompact.includes(`=${expected},`) ||
        hdrCompact.includes(`=${expected}u`) ||
        hdrCompact.includes(`=${expected}/*`),
      `header missing constant ${hexForm} (modelValue=${modelValue})`,
    );
  }
  assert.equal(FRAME_EFFECT_81FB70_RNG_SHIFT1, FRAME_EFFECT_81ECC0_RNG_SHIFT1);
  assert.equal(FRAME_EFFECT_81FB70_RNG_SHIFT2, FRAME_EFFECT_81ECC0_RNG_SHIFT2);
  assert.equal(FRAME_EFFECT_81FB70_RNG_SHIFT3, FRAME_EFFECT_81ECC0_RNG_SHIFT3);
  assert.equal(FRAME_EFFECT_81FB20_NEXT_VA, FRAME_EFFECT_81FB70_VA);
  assert.equal(FRAME_EFFECT_81FB70_HOST_LOG_VA, 0x00a112c0);
});

test("no uint8_t scalar parameters in the v17 declaration block", () => {
  const v17Block = HDR.slice(HDR.indexOf("ABI v17"));
  const declLines = v17Block
    .split("\n")
    .filter((ln) =>
      /^(void|uint32_t|int32_t)\s+isaac_frame_effect_81fb70_/.test(ln.trim()),
    );
  assert.ok(declLines.length >= 9, `expected v17 declarations, got ${declLines.length}`);
  assert.doesNotMatch(v17Block, /uint8_t/);
});

test("v17 exports: seed_mix / iabs / area_abs / umod / pick_a / index / bounds / apply_xy / entry_plan", () => {
  assert.equal(typeof W.seedMix81fb70, "function");
  assert.equal(typeof W.iabs81fb70, "function");
  assert.equal(typeof W.areaAbs81fb70, "function");
  assert.equal(typeof W.umod81fb70, "function");
  assert.equal(typeof W.pickA81fb70, "function");
  assert.equal(typeof W.index81fb70, "function");
  assert.equal(typeof W.bounds81fb70, "function");
  assert.equal(typeof W.applyXy81fb70, "function");
  assert.equal(typeof W.entryPlan81fb70, "function");
});

test("seed_mix: v13 xorshift 1/9/29, mix(0)=0, 32-bit wrap", () => {
  assert.equal(W.seedMix81fb70(0) >>> 0, 0);
  assert.equal(frameEffect81fb70SeedMix(0), 0);
  const cases = [1, 2, 0x100, 0x1ff, 0x7fffffff, 0x80000000, 0xffffffff];
  for (const s of cases) {
    assert.equal(W.seedMix81fb70(s) >>> 0, frameEffect81fb70SeedMix(s), `mix 0x${(s >>> 0).toString(16)}`);
  }
  const rnd = lcg32(0x81fb70);
  for (let i = 0; i < 128; i += 1) {
    const s = rnd();
    assert.equal(W.seedMix81fb70(s) >>> 0, frameEffect81fb70SeedMix(s), `mix trial ${i}`);
  }
});

test("iabs: cdq/xor/sub; INT_MIN stays INT_MIN", () => {
  assert.equal(W.iabs81fb70(0), 0);
  assert.equal(W.iabs81fb70(1), 1);
  assert.equal(W.iabs81fb70(-1), 1);
  assert.equal(W.iabs81fb70(0x7fffffff), 0x7fffffff);
  assert.equal(W.iabs81fb70(-0x7fffffff), 0x7fffffff);
  assert.equal(W.iabs81fb70(0x80000000 | 0), 0x80000000 | 0);
  assert.equal(frameEffect81fb70Iabs(0x80000000), 0x80000000 | 0);
  const rnd = lcg32(0x81ab5);
  for (let i = 0; i < 64; i += 1) {
    const x = rnd() | 0;
    assert.equal(W.iabs81fb70(x), frameEffect81fb70Iabs(x), `iabs trial ${i}`);
  }
});

test("area_abs: imul low-32 then iabs", () => {
  assert.equal(W.areaAbs81fb70(3, 4), 12);
  assert.equal(W.areaAbs81fb70(-3, 4), 12);
  assert.equal(W.areaAbs81fb70(-3, -4), 12);
  assert.equal(W.areaAbs81fb70(0, 9), 0);
  /* 0x40000000 * 4 wraps to 0 then abs 0 */
  assert.equal(W.areaAbs81fb70(0x40000000, 4), 0);
  assert.equal(W.areaAbs81fb70(0x80000000 | 0, 1), 0x80000000 | 0);
  const rnd = lcg32(0x81aea);
  for (let i = 0; i < 64; i += 1) {
    const dx = rnd() | 0;
    const dy = rnd() | 0;
    assert.equal(W.areaAbs81fb70(dx, dy), frameEffect81fb70AreaAbs(dx, dy), `area trial ${i}`);
  }
});

test("umod: unsigned rem; denom 0 yields 0; negative delta is huge divisor", () => {
  assert.equal(W.umod81fb70(10, 3) >>> 0, 1);
  assert.equal(W.umod81fb70(10, 0) >>> 0, 0);
  assert.equal(frameEffect81fb70Umod(10, 0), 0);
  assert.equal(W.umod81fb70(0, 7) >>> 0, 0);
  /* negative delta as uint32: -2 = 0xfffffffe */
  assert.equal(W.umod81fb70(5, -2) >>> 0, 5 % 0xfffffffe);
  const rnd = lcg32(0x81d0d);
  for (let i = 0; i < 64; i += 1) {
    const n = rnd();
    const d = rnd();
    assert.equal(W.umod81fb70(n, d) >>> 0, frameEffect81fb70Umod(n, d), `umod trial ${i}`);
  }
});

test("pick_a: UNSIGNED rem < area1; total==0 => rem=0 => B", () => {
  assert.equal(W.pickA81fb70(0, 1), 1);
  assert.equal(W.pickA81fb70(1, 1), 0);
  assert.equal(W.pickA81fb70(0, 0), 0);
  assert.equal(frameEffect81fb70PickA(0, 0), 0);
  /* signed mutant: -1 < 1 signed true; unsigned 0xffffffff < 1 is false */
  assert.equal(W.pickA81fb70(0xffffffff, 1), 0);
  assert.equal(frameEffect81fb70PickA(0xffffffff, 1), 0);
});

test("index: origin + rem, 32-bit wrap", () => {
  assert.equal(W.index81fb70(10, 3), 13);
  assert.equal(W.index81fb70(-1, 1), 0);
  assert.equal(W.index81fb70(0x7fffffff, 1), 0x80000000 | 0);
  assert.equal(frameEffect81fb70Index(0x7fffffff, 1), 0x80000000 | 0);
  const rnd = lcg32(0x81ed1);
  for (let i = 0; i < 64; i += 1) {
    const o = rnd() | 0;
    const r = rnd();
    assert.equal(W.index81fb70(o, r), frameEffect81fb70Index(o, r), `index trial ${i}`);
  }
});

test("bounds: four SIGNED deltas via v13 aabb_span; null skip", () => {
  const row = [1, 2, 13, 8, 10, 20, 14, 26];
  writeRow8(W.memory, V17_SCRATCH.desc, row);
  W.bounds81fb70(V17_SCRATCH.dx1, V17_SCRATCH.dy1, V17_SCRATCH.dx2, V17_SCRATCH.dy2, V17_SCRATCH.desc);
  const js = frameEffect81fb70Bounds(row);
  assert.equal(i32At(W.memory, V17_SCRATCH.dx1), js.dx1);
  assert.equal(i32At(W.memory, V17_SCRATCH.dy1), js.dy1);
  assert.equal(i32At(W.memory, V17_SCRATCH.dx2), js.dx2);
  assert.equal(i32At(W.memory, V17_SCRATCH.dy2), js.dy2);
  assert.equal(js.dx1, 12);
  assert.equal(js.dy1, 6);
  assert.equal(js.dx2, 4);
  assert.equal(js.dy2, 6);
  setI32(W.memory, V17_SCRATCH.dx1, 9);
  W.bounds81fb70(V17_SCRATCH.dx1, V17_SCRATCH.dy1, V17_SCRATCH.dx2, V17_SCRATCH.dy2, 0);
  assert.equal(i32At(W.memory, V17_SCRATCH.dx1), 9);
});

test("apply_xy: [out]=x, [out+4]=y; null skip", () => {
  setI32(W.memory, V17_SCRATCH.xy, 0);
  setI32(W.memory, V17_SCRATCH.xy + 4, 0);
  W.applyXy81fb70(V17_SCRATCH.xy, 5, 7);
  const js = frameEffect81fb70ApplyXy(5, 7);
  assert.equal(i32At(W.memory, V17_SCRATCH.xy), js[0]);
  assert.equal(i32At(W.memory, V17_SCRATCH.xy + 4), js[1]);
  assert.equal(js[0], 5);
  assert.equal(js[1], 7);
  W.applyXy81fb70(0, 1, 2);
  assert.equal(i32At(W.memory, V17_SCRATCH.xy), 5);
});

test("entry_plan: seed==0 is fatal host log, mix/XY never run", () => {
  const row = [1, 1, 13, 7, 1, 8, 26, 14];
  writeRow8(W.memory, V17_SCRATCH.desc, row);
  W.entryPlan81fb70(V17_SCRATCH.plan, 0, V17_SCRATCH.desc);
  const p = readPlan81fb70(W.memory, V17_SCRATCH.plan);
  const js = frameEffect81fb70EntryPlan(0, row);
  assert.equal(p.seedZero, 1);
  assert.equal(p.fatal, 1);
  assert.equal(p.mixed0, 0);
  assert.equal(p.pickA, 0);
  assert.equal(p.applyXy, 0);
  assert.equal(p.hostCalls, 1);
  assert.equal(p.pureComplete, 0);
  assert.equal(p.seedZero, js.seedZero);
  assert.equal(p.fatal, js.fatal);
});

test("entry_plan: rect A vs B, dy==0 skip, happy path writes XY", () => {
  /* high rect 12x6=72, low 4x6=24, total 96. */
  const row = [1, 2, 13, 8, 10, 20, 14, 26];
  writeRow8(W.memory, V17_SCRATCH.desc, row);
  const seed = 1;
  W.entryPlan81fb70(V17_SCRATCH.plan, seed, V17_SCRATCH.desc);
  const p = readPlan81fb70(W.memory, V17_SCRATCH.plan);
  const js = frameEffect81fb70EntryPlan(seed, row);
  assert.equal(p.seedZero, 0);
  assert.equal(p.mixed0 >>> 0, js.mixed0);
  assert.equal(p.pickA, js.pickA);
  assert.equal(p.outX, js.outX);
  assert.equal(p.outY, js.outY);
  assert.equal(p.applyXy, js.applyXy);
  assert.equal(p.fatal, js.fatal);
  assert.equal(p.hostCalls, js.hostCalls);
  assert.equal(p.pureComplete, 0);
  /* dy==0 on both rects: y stays origin, no third mix. */
  const flat = [5, 9, 15, 9, 20, 3, 24, 3];
  writeRow8(W.memory, V17_SCRATCH.desc, flat);
  W.entryPlan81fb70(V17_SCRATCH.plan, 7, V17_SCRATCH.desc);
  const f = readPlan81fb70(W.memory, V17_SCRATCH.plan);
  const fjs = frameEffect81fb70EntryPlan(7, flat);
  assert.equal(f.outY, fjs.outY);
  assert.equal(f.applyXy, fjs.applyXy);
  W.entryPlan81fb70(0, 7, V17_SCRATCH.desc);
  const afterNull = readPlan81fb70(W.memory, V17_SCRATCH.plan);
  assert.equal(afterNull.outX, f.outX);
});

test("entry_plan: randomized differential vs the JS oracle", () => {
  const rnd = lcg32(0x81f17);
  for (let i = 0; i < 80; i += 1) {
    const row = [];
    for (let k = 0; k < 8; k += 1) row.push((rnd() & 0x3f) | 0);
    writeRow8(W.memory, V17_SCRATCH.desc, row);
    const seed = rnd();
    W.entryPlan81fb70(V17_SCRATCH.plan, seed, V17_SCRATCH.desc);
    const p = readPlan81fb70(W.memory, V17_SCRATCH.plan);
    const js = frameEffect81fb70EntryPlan(seed, row);
    assert.equal(p.seedZero, js.seedZero, `seedZero ${i}`);
    assert.equal(p.fatal, js.fatal, `fatal ${i}`);
    assert.equal(p.mixed0 >>> 0, js.mixed0, `mixed0 ${i}`);
    assert.equal(p.pickA, js.pickA, `pickA ${i}`);
    assert.equal(p.outX, js.outX, `outX ${i}`);
    assert.equal(p.outY, js.outY, `outY ${i}`);
    assert.equal(p.applyXy, js.applyXy, `applyXy ${i}`);
    assert.equal(p.hostCalls, js.hostCalls, `hostCalls ${i}`);
    assert.equal(p.pureComplete, 0);
  }
});

test("v17 mutants: signed pick, umod-zero, INT_MIN abs, ABI pin, parked next", () => {
  /* M1 signed pick: 0xffffffff must stay rect B against area1=1. */
  assert.equal(W.pickA81fb70(0xffffffff, 1), 0);
  assert.notEqual(W.pickA81fb70(0xffffffff, 1), 1);
  /* M2 umod denom 0 must yield 0, not throw / not n. */
  assert.equal(W.umod81fb70(9, 0) >>> 0, 0);
  assert.notEqual(W.umod81fb70(9, 0) >>> 0, 9);
  /* M3 INT_MIN abs stays INT_MIN (cdq/xor/sub), not 0 / not overflow-to-positive. */
  assert.equal(W.iabs81fb70(0x80000000 | 0), 0x80000000 | 0);
  /* M4 seed==0 never mixes. */
  W.entryPlan81fb70(V17_SCRATCH.plan, 0, 0);
  const z = readPlan81fb70(W.memory, V17_SCRATCH.plan);
  assert.equal(z.mixed0, 0);
  assert.equal(z.applyXy, 0);
  assert.equal(z.hostCalls, 1);
  /* M5 ABI pin + census + parked next. */
  assert.equal(W.abi(), 51);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_PURE_HELPERS_ABI_VERSION = 51/);
  assert.equal(FRAME_EFFECT_PURE_ABI_VERSION, 51);
  assert.equal(FRAME_EFFECT_81FB70_INSN_COUNT, 203);
  assert.equal(FRAME_EFFECT_81FB70_BYTE_LEN, 484);
  assert.equal(FRAME_EFFECT_81FB70_DIRECT_CALLERS, 1);
  assert.equal(FRAME_EFFECT_81FB70_NEXT_VA, 0x0081fd60);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_81FB70_NEXT_VA = 0x0081fd60u/);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_81FB70_HOST_LOG_VA = 0x00a112c0u/);
  assert.match(HDR, /GetRandomTile/);
  assert.doesNotMatch(HDR, /peels 0x0081fd60/);
});

/* ------------------------------------------------------------------ */
/* v18: FrameEffect_6fd7c0 mode-4 SFX early arm (0x006fd81c..0x006fd877)
 *
 * The H1 arm: `cmp dword [Game+0x26614],4` gates the SFX-only early return.
 * 0x006fd825 seeds the player stack slot with 0xbb (mode-4) or 0xd7
 * (anim-0xc special path, 0x006fd8e4), 0x006fd82c loads the SFX base global
 * 0x00c7169c, and 0x006fd858 builds the SFXManager receiver `lea ecx,
 * [esi+0x2a324]`. The 0x00956780 remap and 0x0092dc30 Play calls stay host;
 * every arithmetic/compare law in the arm is asserted here. The loop slot of
 * the Play pack is machine `push 0` at 0x006fd84c — the model previously
 * claimed 1 (latent drift, now pinned at 0).                */

const V18_SCRATCH = {
  args: 0x1a0000, /* 6 dwords — 0x1a0000+ is fresh, disjoint from V17 at 0x190000 */
};

test("mode4_sfx_early: FULL dword compare against 4, wide values", () => {
  assert.equal(W.mode4SfxEarly(4), 1);
  assert.equal(W.mode4SfxEarly(3), 0);
  assert.equal(W.mode4SfxEarly(5), 0);
  assert.equal(W.mode4SfxEarly(0x100), 0);
  assert.equal(W.mode4SfxEarly(0x1ff), 0);
  assert.equal(W.mode4SfxEarly(-1), 0);
  assert.equal(W.mode4SfxEarly(0xffffffff >>> 0), 0);
  assert.equal(W.mode4SfxEarly(0x80000000 >>> 0), 0);
  assert.equal(W.mode4SfxEarly(4), frameEffect6fd7c0Mode4SfxEarly(4));
  assert.equal(W.mode4SfxEarly(0xffffffff >>> 0),
               frameEffect6fd7c0Mode4SfxEarly(0xffffffff >>> 0));
});

test("sfx seeds: mode-4 seed 0xbb, special seed 0xd7 (constants)", () => {
  assert.equal(W.mode4SfxSeed(), 0xbb);
  assert.equal(W.specialSfxSeed(), 0xd7);
  assert.equal(W.mode4SfxSeed(), frameEffect6fd7c0Mode4SfxSeed());
  assert.equal(W.specialSfxSeed(), frameEffect6fd7c0SpecialSfxSeed());
});

test("sfx_rare_hit: unsigned % 20 == 0, wide values", () => {
  assert.equal(W.sfxRareHit(0), 1);
  assert.equal(W.sfxRareHit(20), 1);
  assert.equal(W.sfxRareHit(40), 1);
  assert.equal(W.sfxRareHit(19), 0);
  assert.equal(W.sfxRareHit(21), 0);
  assert.equal(W.sfxRareHit(0x100), 0); /* 256 % 20 = 16 */
  assert.equal(W.sfxRareHit(0x1ff), 0); /* 511 % 20 = 11 */
  assert.equal(W.sfxRareHit(0xffffffff >>> 0), 0); /* % 20 = 15 */
  assert.equal(W.sfxRareHit(20), frameEffect6fd7c0SfxRareHit(20));
  assert.equal(W.sfxRareHit(0xffffffff >>> 0),
               frameEffect6fd7c0SfxRareHit(0xffffffff >>> 0));
});

test("sfx_play_id: closed remap gate keeps the seed; open maps 0x25 / rare 0x12d", () => {
  assert.equal(W.sfxPlayId(0xbb, 0, 0), 0xbb);
  assert.equal(W.sfxPlayId(0xd7, 0, 0), 0xd7);
  assert.equal(W.sfxPlayId(0xbb, 1, 0), 0x25);
  assert.equal(W.sfxPlayId(0xbb, 1, 1), 0x12d);
  assert.equal(W.sfxPlayId(0xbb, 0, 1), 0xbb); /* gate closed wins over rare */
  assert.equal(W.sfxPlayId(0xffffffff, 1, 0) >>> 0, 0x25);
  assert.equal(W.sfxPlayId(0xbb, 1, 1), frameEffect6fd7c0SfxPlayId(0xbb, 1, 1));
  assert.equal(W.sfxPlayId(0xd7, 0, 0), frameEffect6fd7c0SfxPlayId(0xd7, 0, 0));
});

test("sfx_play_args: the six raw pack slots, loop is machine push 0", () => {
  const js = frameEffect6fd7c0SfxPlayArgs(0xbb);
  assert.equal(js.loop, 0);
  assert.equal(js.frameDelay, 2);
  assert.equal(js.volume, 1);
  assert.equal(js.pitch, 1);
  assert.equal(js.pan, 0);
  assert.equal(W.sfxPlayArgs(V18_SCRATCH.args, 6, 0xbb), 6);
  assert.equal(u32At(W.memory, V18_SCRATCH.args + 0), 0xbb);
  assert.equal(u32At(W.memory, V18_SCRATCH.args + 4), 0x3f800000); /* volume */
  assert.equal(u32At(W.memory, V18_SCRATCH.args + 8), 2); /* frame delay */
  assert.equal(u32At(W.memory, V18_SCRATCH.args + 12), 0); /* loop = push 0 */
  assert.equal(u32At(W.memory, V18_SCRATCH.args + 16), 0x3f800000); /* pitch */
  assert.equal(u32At(W.memory, V18_SCRATCH.args + 20), 0); /* pan */
  /* wide id travels unmasked into slot 0 */
  assert.equal(W.sfxPlayArgs(V18_SCRATCH.args, 6, 0xffffffff), 6);
  assert.equal(u32At(W.memory, V18_SCRATCH.args + 0), 0xffffffff);
  assert.equal(W.sfxPlayArgs(V18_SCRATCH.args, 6, 0x100), 6);
  assert.equal(u32At(W.memory, V18_SCRATCH.args + 0), 0x100);
  /* clamp: len 2 writes only two slots; null out returns the count */
  setU32(W.memory, V18_SCRATCH.args + 8, 0xdeadbeef);
  assert.equal(W.sfxPlayArgs(V18_SCRATCH.args, 2, 7), 6);
  assert.equal(u32At(W.memory, V18_SCRATCH.args + 0), 7);
  assert.equal(u32At(W.memory, V18_SCRATCH.args + 4), 0x3f800000);
  assert.equal(u32At(W.memory, V18_SCRATCH.args + 8), 0xdeadbeef);
  assert.equal(W.sfxPlayArgs(0, 6, 7), 6);
});

test("sfx_base_global_va + sfx_manager_off: the two SFX-arm constants", () => {
  assert.equal(W.sfxBaseGlobalVa(), 0x00c7169c);
  assert.equal(W.sfxManagerOff(), 0x2a324);
  assert.equal(W.sfxBaseGlobalVa(), frameEffect6fd7c0SfxBaseGlobalVa());
  assert.equal(W.sfxManagerOff(), frameEffect6fd7c0SfxManagerOff());
  assert.equal(W.sfxManagerOff(), FRAME_EFFECT_SFX_MANAGER_OFF >>> 0);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_SFX_MANAGER_OFF = 0x2a324/);
  assert.match(HDR, /isaac_frame_effect_6fd7c0_sfx_manager_receiver/);
});

test("sfx_manager_receiver: base + 0x2a324 with 32-bit wrap", () => {
  assert.equal(W.sfxManagerReceiver(0), 0x2a324);
  assert.equal(W.sfxManagerReceiver(0x100), 0x2a424);
  assert.equal(W.sfxManagerReceiver(0x00c7169c), 0x00c9b9c0);
  assert.equal(W.sfxManagerReceiver(0xffffffff), 0x2a323);
  assert.equal(W.sfxManagerReceiver(0x80000000) >>> 0, 0x8002a324);
  assert.equal(W.sfxManagerReceiver(0x100), frameEffect6fd7c0SfxManagerReceiver(0x100));
  assert.equal(W.sfxManagerReceiver(0xffffffff),
               frameEffect6fd7c0SfxManagerReceiver(0xffffffff));
  const rnd = lcg32(0x6fd858);
  for (let i = 0; i < 64; i += 1) {
    const b = rnd();
    assert.equal(W.sfxManagerReceiver(b), frameEffect6fd7c0SfxManagerReceiver(b),
                 `receiver base 0x${(b >>> 0).toString(16)}`);
  }
});

test("v18 mutants: receiver offset, loop slot, seeds, rare modulus, ABI pin", () => {
  /* M1 receiver offset: 0x2a324 is machine `lea ecx,[esi+0x2a324]`; a
     0x2a320 mutant changes base-0 and 0xffffffff answers. */
  assert.equal(W.sfxManagerReceiver(0), 0x2a324);
  assert.notEqual(W.sfxManagerReceiver(0), 0x2a320);
  assert.equal(W.sfxManagerReceiver(0xffffffff), 0x2a323);
  /* M2 loop slot: machine pushes 0 at 0x006fd84c; a loop=1 pack mutant
     writes 1 at slot 3. */
  W.sfxPlayArgs(V18_SCRATCH.args, 6, 1);
  assert.equal(u32At(W.memory, V18_SCRATCH.args + 12), 0);
  assert.notEqual(u32At(W.memory, V18_SCRATCH.args + 12), 1);
  /* M3 seeds: 0xbb / 0xd7 pinned, not 0xbc / 0xd6. */
  assert.equal(W.mode4SfxSeed(), 0xbb);
  assert.equal(W.specialSfxSeed(), 0xd7);
  /* M4 rare modulus 20: 40 hits, 0x1ff misses (511 % 20 = 11). */
  assert.equal(W.sfxRareHit(40), 1);
  assert.equal(W.sfxRareHit(0x1ff), 0);
  /* M5 gate: mode 4 only — 0x100 wide value must miss. */
  assert.equal(W.mode4SfxEarly(0x100), 0);
  /* M6 ABI pin. */
  assert.equal(W.abi(), 51);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_PURE_HELPERS_ABI_VERSION = 51/);
  assert.equal(FRAME_EFFECT_PURE_ABI_VERSION, 51);
  assert.match(SRC, /0x006fd858 lea ecx, \[esi \+ 0x2a324\]/);
});

test("wave-21: 6fd7c0_alt_path_probe_needed — FULL-WORD anim==0xc && game_field0==1 gate", () => {
  /* update-v96-audit-assertions listed the export as list-only. PE truth:
     0x006fd87a cmp edi,0xc / jne skip; 0x006fd87f cmp [edx],1 / jne skip —
     FULL 32-bit compares on BOTH sides, so a wide anim whose low byte is
     0xc must NOT probe and a wide game_field0 must NOT match 1. */
  assert.equal(W.altPathProbeNeeded(0xc, 1), 1, "anim 0xc + field0 1 -> probe");
  assert.equal(W.altPathProbeNeeded(0xc, 0), 0, "field0 != 1 -> skip");
  assert.equal(W.altPathProbeNeeded(0xc, -1), 0, "field0 -1 -> skip");
  assert.equal(W.altPathProbeNeeded(0xc, 0x101), 0, "field0 0x101 -> skip (full-word)");
  assert.equal(W.altPathProbeNeeded(0xd, 1), 0, "anim 0xd -> skip");
  assert.equal(W.altPathProbeNeeded(0, 1), 0, "anim 0 -> skip");
  assert.equal(W.altPathProbeNeeded(0x10c, 1), 0, "wide 0x10c (low byte 0xc) does NOT match");
  assert.equal(W.altPathProbeNeeded(0xffffffff, 1), 0, "0xffffffff -> skip");
  for (const [a, f] of [[0xc, 1], [0xc, 0], [0xc, 0x101], [0xd, 1], [0, 1],
                        [0x10c, 1], [0xffffffff, 1], [0xc, -1]]) {
    assert.equal(W.altPathProbeNeeded(a >>> 0, f),
      frameEffect6fd7c0AltPathProbeNeeded(a >>> 0, f) ? 1 : 0,
      `oracle agreement (0x${(a >>> 0).toString(16)}, ${f})`);
  }
});

/* ------------------------------------------------------------------ */
/* v19: FUN_006fdc10 nested stage host recensus — ABI 18 -> 19
 *
 * Pins every ABI v3 6fdc10 export behaviourally for the first time
 * (previously EXPORTS-list entries only), repairs five model-oracle
 * drifts (mask_bit complement, stage_bump add-vs-bump, slot_addr_clamped
 * negative-count guard, entry_plan host705ee0, partner_blocks id check),
 * and lands the new islands: kind_needs_705ee0, stage_record_field_off,
 * stage_record_needs_key, registry_slot_addr, prize_entry_bump_gate,
 * string_data_ptr. PE ground truth: cpu-dump/006fdc10.txt (480 insns
 * incl. 13 int3 padding; first_ret 0x006fe2de).
 */

/* v19 scratch sits above V18 (0x1a0000). 0x1b0000+ is fresh. */
const V19_SCRATCH = {
  plan: 0x1b0000, /* 9 dwords (36 B) */
  size: 0x1b0100, /* 4 B */
  cap: 0x1b0104,  /* 4 B */
  buf: 0x1b0108,  /* 4 B */
};

function readPlan6fdc10(memory, base) {
  return {
    kindValid: i32At(memory, base + 0),
    hostFatal: i32At(memory, base + 4),
    fatalStringVa: u32At(memory, base + 8),
    stageBlock: i32At(memory, base + 12),
    stageMode: i32At(memory, base + 16),
    host705ee0: i32At(memory, base + 20),
    hostLog: i32At(memory, base + 24),
    pureCfOk: i32At(memory, base + 28),
    pureComplete: i32At(memory, base + 32),
  };
}

