test("string_reset: size 0, capacity 0xf, first byte cleared, null skips", () => {
  const m = W.memory;
  const { size, cap, buf } = V19_SCRATCH;
  setU32(m, size, 0xdeadbeef);
  setU32(m, cap, 0xdeadbeef);
  setU32(m, buf, 0xdeadbeef);
  W.stringReset6fdc10(size, cap, buf);
  assert.equal(u32At(m, size), 0);
  assert.equal(u32At(m, cap), 0xf);
  assert.equal(u32At(m, buf) & 0xff, 0);
  const js = frameEffect6fdc10StringReset();
  assert.equal(js.size, 0);
  assert.equal(js.capacity, FRAME_EFFECT_6FDC10_SSO_CAPACITY);
  assert.equal(js.firstByte, 0);
  /* null pointers skip their store (PE 0x006fdd2f..0x006fdd3d). */
  setU32(m, cap, 0x12345678);
  W.stringReset6fdc10(0, cap, 0);
  assert.equal(u32At(m, cap), 0xf);
  setU32(m, cap, 0x12345678);
  W.stringReset6fdc10(0, 0, 0);
  assert.equal(u32At(m, cap), 0x12345678);
});

