test("mask_bit: (probe_a|0x26550|0xc) & ~probe_b, bit 1 of AL — v19 repair", () => {
  /* PE 0x006fddbd or / 0x6fddc3 or / 0x6fddcd or / 0x6fddd4 not /
     0x6fddd6 and / 0x6fddd8 test al,2. */
  const cases = [
    [[2, 0, 0, 0], 1],
    [[2, 0, 0, 2], 0],      /* probeB complements the mask bit away */
    [[0, 4, 0, 0], 0],      /* field0c 4 sets bit 2, not bit 1 */
    [[0, 2, 0, 0], 1],
    [[0, 0, 0x100, 0], 0],  /* probeA bit 8 only */
    [[0, 0, 2, 2], 0],
    [[0, 0, 0x102, 2], 0],  /* (0x102 & ~2) = 0x100 -> bit 1 clear */
    [[0x80000002, 0, 0, 0xffffffff], 0], /* ~0xffffffff = 0 */
    [[0x100, 0, 0, 0], 0],
  ];
  for (const [args, exp] of cases) {
    assert.equal(W.maskBit6fdc10(...args), exp, `mask ${args}`);
    assert.equal(W.maskBit6fdc10(...args), frameEffect6fdc10MaskBit(...args),
                 `wasm==js ${args}`);
  }
  /* D1 discriminator: the OLD oracle returned 1 for [[2,0,0,2]] and
     [[0,4,0,0]] (probes OR-ed, probeB never complemented). */
  assert.equal(frameEffect6fdc10MaskBit(2, 0, 0, 2), 0);
  assert.equal(frameEffect6fdc10MaskBit(0, 4, 0, 0), 0);
});

