test("partner_blocks: id -1 check is SIGNED, not id==0 — v19 repair", () => {
  const cases = [
    [[0x20, 0, 5, 0x10], 1],    /* id 0 IS a real partner: 0<5, not self */
    [[0x20, -1, 5, 0x10], 0],   /* id -1 -> body continues */
    [[0x20, 5, 5, 0x10], 0],    /* id >= own -> body */
    [[0x20, 4, 5, 0x10], 1],
    [[0x10, 0, 5, 0x10], 0],    /* partner == self -> body */
    [[0, 3, 5, 0x10], 0],       /* null partner */
    [[0x20, -2, -3, 0x10], 0],  /* -2 >= -3 signed */
    [[0x20, -4, -3, 0x10], 1],
    [[0xffffffff, 7, 5, 0x10], 0], /* 7 >= 5 */
  ];
  for (const [args, exp] of cases) {
    assert.equal(W.partnerBlocks6fdc10(...args), exp, `partner ${args}`);
    assert.equal(W.partnerBlocks6fdc10(...args),
                 frameEffect6fdc10PartnerBlocks(...args) ? 1 : 0, `js ${args}`);
  }
  /* D5 discriminator: old oracle returned 0 for [0x20,0,5,0x10]. */
  assert.equal(frameEffect6fdc10PartnerBlocks(0x20, 0, 5, 0x10), true);
});

