test("slot_addr_clamped: unsigned jae on the sar'd count — v19 repair", () => {
  const cases = [
    [0x1000, 4, 3, 0x100c],
    [0x1000, 4, 4, 0x1000],   /* clamp to element 0 (original defect) */
    [0x1000, 4, 5, 0x1000],
    [0x1000, 0, 0, 0x1000],
    [0x1000, 0xfffffffc, 1, 0x1004], /* count -4: u32 huge -> NO clamp */
    [0x1000, 0xfffffffc, 0, 0x1000],
    [0xfffffff0, 4, 1, 0xfffffff4],
    [0xfffffff0, 4, 4, 0xfffffff0],
    [0x1000, 0xffffffff, 5, 0x1014], /* count -1: never clamps */
  ];
  for (const [b, c, i, exp] of cases) {
    assert.equal(W.slotAddrClamped6fdc10(b, c, i) >>> 0, exp >>> 0,
                 `slot ${b},${c},${i}`);
    assert.equal(W.slotAddrClamped6fdc10(b, c, i),
                 frameEffect6fdc10SlotAddrClamped(b, c, i),
                 `wasm==js ${b},${c},${i}`);
  }
  /* D3 discriminator: old oracle's `n<=0 -> begin` returned 0x1000 for
     [0x1000, 0xfffffffc, 1]. */
  assert.equal(frameEffect6fdc10SlotAddrClamped(0x1000, 0xfffffffc, 1), 0x1004);
});

