test("prize_entry_bump_gate: byte+0xd, SIGNED dword+0x10 <= 0x10, obj != base", () => {
  /* PE 0x006fe1ff cmp byte [eax+0xd],0; jne; 0x006fe209 cmp dword
     [eax+0x10],0x10; jg; 0x006fe213 cmp eax,[ebx+0x1bbd8]; je. */
  const cases = [
    [0, 0x10, 0x2000, 0x1000, 1],
    [0, 0x11, 0x2000, 0x1000, 0],      /* 17 > 16 */
    [0, 0x100, 0x2000, 0x1000, 0],     /* 256 > 16 */
    [0, 0x10, 0x1000, 0x1000, 0],      /* obj == base */
    [0xff, 0x10, 0x2000, 0x1000, 0],   /* byte nonzero */
    [0x100, 0x10, 0x2000, 0x1000, 1],  /* LOW byte 0 */
    [0, 0xffffffff, 0x2000, 0x1000, 1], /* signed -1 <= 16 -> passes */
    [0, 0x80000000, 0x2000, 0x1000, 1], /* signed negative -> passes */
  ];
  for (const [d, f, o, base, exp] of cases) {
    assert.equal(W.prizeEntryBumpGate(d, f, o, base), exp,
                 `prize ${d},${f},${o},${base}`);
    assert.equal(W.prizeEntryBumpGate(d, f, o, base),
                 frameEffect6fdc10PrizeEntryBumpGate(d, f, o, base),
                 `wasm==js ${d},${f},${o},${base}`);
  }
  assert.equal(FRAME_EFFECT_6FDC10_PRIZE_MAX_SIZE, 0x10);
});

test("string_data_ptr: SSO select — cap >= 0x10 takes the heap pointer", () => {
  /* PE 0x006fdcdc cmp dword [eax+0x14],0x10; jb. */
  const cases = [
    [0x1000, 0x9000, 0xf, 0x1000],
    [0x1000, 0x9000, 0x10, 0x9000],
    [0x1000, 0x9000, 0x100, 0x9000],
    [0x1000, 0x9000, 0xffffffff, 0x9000],
    [0x1000, 0, 0x10, 0],        /* heap_ptr 0 travels unmasked */
    [0x1000, 0x9000, 0, 0x1000],
  ];
  for (const [o, h, c, exp] of cases) {
    assert.equal(W.stringDataPtr(o, h, c) >>> 0, exp >>> 0, `data ${o},${h},${c}`);
    assert.equal(W.stringDataPtr(o, h, c), frameEffect6fdc10StringDataPtr(o, h, c),
                 `wasm==js ${o},${h},${c}`);
  }
  assert.equal(FRAME_EFFECT_6FDC10_SSO_BYTES, 0x10);
});

test("entry_plan: machine-truth plan for the nested stage host", () => {
  const m = W.memory;
  const call = (kind, tc, gc, flag, mb, me) => {
    W.entryPlan6fdc10(V19_SCRATCH.plan, kind, tc, gc, flag, mb, me);
    return readPlan6fdc10(m, V19_SCRATCH.plan);
  };
  const js = (kind, tc, gc, flag, mb, me) =>
    frameEffect6fdc10EntryPlan(kind, tc, gc, flag, mb, me);

  /* kind 6, block open, non-empty range -> everything live. */
  let p = call(6, 1, 1, 0, 0, 1);
  let q = js(6, 1, 1, 0, 0, 1);
  assert.equal(p.kindValid, 1);
  assert.equal(p.hostFatal, 0);
  assert.equal(p.stageBlock, 1);
  assert.equal(p.stageMode, 2);
  assert.equal(p.host705ee0, 1);   /* 6 != 5 */
  assert.equal(p.hostLog, 1);
  assert.equal(p.pureCfOk, 1);
  assert.equal(p.pureComplete, 0);
  assert.deepEqual(p, {
    kindValid: q.kindValid, hostFatal: q.hostFatal, fatalStringVa: q.fatalStringVa,
    stageBlock: q.stageBlock, stageMode: q.stageMode, host705ee0: q.host705ee0,
    hostLog: q.hostLog, pureCfOk: q.pureCfOk, pureComplete: q.pureComplete,
  });

  /* D4 discriminator: kind 5 with an open block -> NO 0x705ee0 call. */
  p = call(5, 1, 1, 0, 1, 1);
  assert.equal(p.host705ee0, 0);
  assert.equal(p.stageBlock, 1);
  assert.equal(p.hostLog, 1);
  assert.equal(p.stageMode, 0);

  /* kind 5 with a FAILED block still skips 0x705ee0. */
  p = call(5, 0, 1, 0, 1, 1);
  assert.equal(p.stageBlock, 0);
  assert.equal(p.host705ee0, 0);

  /* fatal: kind > 6. */
  p = call(7, 1, 1, 0, 1, 1);
  assert.equal(p.kindValid, 0);
  assert.equal(p.hostFatal, 1);
  assert.equal(p.fatalStringVa, 0x00b68544);
  assert.equal(p.stageBlock, 0);
  assert.equal(p.stageMode, 0);
  assert.equal(p.host705ee0, 0);
  assert.equal(p.hostLog, 0);
  /* pure_complete stays 0: the fatal path itself logs via host 0x00a112c0
     (family convention: 1 only for zero-call bodies). */
  assert.equal(p.pureComplete, 0);
  p = call(0xffffffff, 1, 1, 0, 1, 1);
  assert.equal(p.hostFatal, 1);
  assert.equal(p.fatalStringVa, 0x00b68544);

  /* flag low byte: 0x100 keeps the block open. */
  p = call(2, 1, 1, 0x100, 0, 1);
  assert.equal(p.stageBlock, 1);
  assert.equal(p.stageMode, 2);
  p = call(2, 1, 1, 0xff, 0, 1);
  assert.equal(p.stageBlock, 0);
  assert.equal(p.stageMode, 0);

  /* D6: hostLog = kindValid, not always 0. */
  assert.equal(call(3, 1, 1, 0, 0, 1).hostLog, 1);
  assert.equal(call(9, 1, 1, 0, 0, 1).hostLog, 0);

  /* randomized differential vs the JS oracle. */
  const rnd = lcg32(0x6fdc10);
  for (let i = 0; i < 64; i += 1) {
    const kind = rnd() % 8;
    const tc = rnd() & 1;
    const gc = rnd() & 1;
    const flag = [0, 1, 0x100, 0xff][rnd() % 4];
    const mb = rnd();
    const me = (rnd() & 0xff) === 0 ? mb : rnd();
    const got = call(kind, tc, gc, flag, mb, me);
    const want = js(kind, tc, gc, flag, mb, me);
    assert.equal(got.kindValid, want.kindValid, `kindValid ${i}`);
    assert.equal(got.hostFatal, want.hostFatal, `hostFatal ${i}`);
    assert.equal(got.fatalStringVa >>> 0, want.fatalStringVa >>> 0, `fatalVa ${i}`);
    assert.equal(got.stageBlock, want.stageBlock, `stageBlock ${i}`);
    assert.equal(got.stageMode, want.stageMode, `stageMode ${i}`);
    assert.equal(got.host705ee0, want.host705ee0, `host705ee0 ${i}`);
    assert.equal(got.hostLog, want.hostLog, `hostLog ${i}`);
    assert.equal(got.pureCfOk, want.pureCfOk, `pureCfOk ${i}`);
    assert.equal(got.pureComplete, want.pureComplete, `pureComplete ${i}`);
  }
});

test("v19 mutants: mask complement, bump, clamp, 705ee0, partner, slot, prize, ABI", () => {
  /* M1 mask complement: (2 | 0 | 0) & ~2 == 0 — a mutant that ORs probeB
     (old oracle) returns 1. */
  assert.equal(W.maskBit6fdc10(2, 0, 0, 2), 0);
  assert.notEqual(W.maskBit6fdc10(2, 0, 0, 2), 1);
  /* M2 stage bump: 3 with field4 0x100 stays 3, not 0x103; 3 with 4 is 4. */
  assert.equal(W.stageBump6fdc10(3, 0x100), 3);
  assert.equal(W.stageBump6fdc10(3, 4), 4);
  assert.notEqual(W.stageBump6fdc10(3, 4), 7);
  /* M3 slot clamp: negative sar count never clamps (unsigned jae). */
  assert.equal(W.slotAddrClamped6fdc10(0x1000, 0xfffffffc, 1), 0x1004);
  assert.notEqual(W.slotAddrClamped6fdc10(0x1000, 0xfffffffc, 1), 0x1000);
  /* M4 entry_plan host_705ee0: kind 5 with open block must be 0. */
  W.entryPlan6fdc10(V19_SCRATCH.plan, 5, 1, 1, 0, 1, 1);
  assert.equal(readPlan6fdc10(W.memory, V19_SCRATCH.plan).host705ee0, 0);
  assert.notEqual(readPlan6fdc10(W.memory, V19_SCRATCH.plan).host705ee0, 1);
  /* M5 partner id 0 is a REAL partner (id == -1 is the skip). */
  assert.equal(W.partnerBlocks6fdc10(0x20, 0, 5, 0x10), 1);
  assert.notEqual(W.partnerBlocks6fdc10(0x20, 0, 5, 0x10), 0);
  /* M6 registry slot: strict > and 32-bit wrap. */
  assert.equal(W.registrySlotAddr(0x1000, 0x1d4), 0);
  assert.equal(W.registrySlotAddr(0xfffffff0, 0x200) >>> 0, 0x1c4);
  assert.notEqual(W.registrySlotAddr(0xfffffff0, 0x200) >>> 0, 0x100001c4);
  /* M7 prize gate: SIGNED field_10 — 0x80000000 passes (<= 0x10). */
  assert.equal(W.prizeEntryBumpGate(0, 0x80000000, 0x2000, 0x1000), 1);
  assert.equal(W.prizeEntryBumpGate(0, 0x100, 0x2000, 0x1000), 0);
  /* M8 ABI pin + v19 source pins. */
  assert.equal(W.abi(), 51);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_PURE_HELPERS_ABI_VERSION = 51/);
  assert.equal(FRAME_EFFECT_PURE_ABI_VERSION, 51);
  assert.match(HDR, /isaac_frame_effect_6fdc10_kind_needs_705ee0/);
  assert.match(SRC, /kind_needs_705ee0\(kind\)/); /* entry_plan BY REFERENCE */
  assert.match(SRC, /0x006fdd5c: cmp esi,5; je skip/);
});

/* ------------------------------------------------------------------ */
/* v20: FUN_006fdc10 decision seams around the host leaves — ABI 19 -> 20
 *
 * Eleven freestanding gates extracted from the still-host regions of the
 * nested stage host body (per-player body, entry-record store, camera
 * walk, registry scan). Each is pinned against the linear census rows and
 * the raw PE bytes (second-anchor check in NOTES section 10).
 */

test("player_body_mode_gate: companion mode below 2, SIGNED — both instances", () => {
  /* PE 0x006fde8e cmp dword [g+0x26614],2; jge skip (repeated 0x006fdeb3). */
  const cases = [[-1, 1], [0, 1], [1, 1], [2, 0], [3, 0], [0x100, 0],
                 [-2, 1], [0x80000000, 1], [0x7fffffff, 0], [-0x80000000, 1]];
  for (const [m, exp] of cases) {
    assert.equal(W.playerBodyModeGate(m | 0), exp, `mode ${m}`);
    assert.equal(W.playerBodyModeGate(m | 0),
                 frameEffect6fdc10PlayerBodyModeGate(m | 0), `js mode ${m}`);
  }
  /* SIGNED discriminator: 0x80000000 = -2^31 PASSES (an unsigned compare
     would reject it — 0x80000000 >= 2). */
  assert.equal(W.playerBodyModeGate(0x80000000 | 0), 1);
});

test("player_body_ret_gate: (0x4264c0 ret & partner_id) != -1", () => {
  /* PE 0x006fdea6 and ecx,eax; 0x006fdea8 cmp ecx,-1; je skip. */
  const cases = [
    [0, 0, 1],           /* 0 & 0 = 0 */
    [-1, 0, 1],          /* & with a zero bit keeps it alive */
    [0, -1, 1],
    [-1, -1, 0],         /* all-ones pair skips */
    [0xffffffff, 0xffffffff, 0],
    [0x100, 0xffffffff, 1],
    [0xfffffeff, 0x100, 1],
    [0x80000000, 0x80000000, 1],  /* & is -2^31, not -1 */
    [0x80000000, 0x7fffffff, 1],
    [0x12345678, 0x12345678, 1],
  ];
  for (const [r, p, exp] of cases) {
    assert.equal(W.playerBodyRetGate(r | 0, p | 0), exp, `ret ${r} pid ${p}`);
    assert.equal(W.playerBodyRetGate(r | 0, p | 0),
                 frameEffect6fdc10PlayerBodyRetGate(r | 0, p | 0), `js ${r},${p}`);
  }
});

