test("door_open_gate: byte clear + UNSIGNED slot >= field_10 + rec != node", () => {
  /* PE 0x0082001f..0x0082002d: jne proceed (byte); jb proceed (UNSIGNED);
     jne skip (rec vs list-1 node). */
  const cases = [
    [0, 5, 10, 0x1000, 0x2000, 0],   /* slot <u field10 -> proceed */
    [0, 10, 10, 0x1000, 0x2000, 1],  /* slot >=u, rec != node -> skip */
    [0, 10, 10, 0x1000, 0x1000, 0],  /* rec == node -> proceed */
    [1, 10, 10, 0x1000, 0x2000, 0],  /* byte set -> proceed */
    [0x100, 10, 10, 0x1000, 0x2000, 1], /* low byte clear */
    [0, 0x80000000, 0, 0x1000, 0x2000, 1], /* UNSIGNED: 2^31 >=u 0 */
    [0, 0, 0, 0x1000, 0x2000, 1],
    [0, 0, 0, 0x1000, 0x1000, 0],
    [0xff, 10, 10, 0x1000, 0x2000, 0],
  ];
  for (const [b, s, f, r, n, exp] of cases) {
    assert.equal(W.doorOpenGate81fd60(b >>> 0, s >>> 0, f | 0, r >>> 0, n >>> 0),
                 exp, `door ${b},${s},${f},${r},${n}`);
    assert.equal(W.doorOpenGate81fd60(b >>> 0, s >>> 0, f | 0, r >>> 0, n >>> 0),
                 frameEffect81fd60DoorOpenGate(b >>> 0, s >>> 0, f | 0, r >>> 0, n >>> 0),
                 `js door ${b},${s},${f},${r},${n}`);
  }
  /* UNSIGNED discriminator: 0x80000000 is >=u 0 (signed compare mutant
     would proceed to the pointer check and not skip). */
  assert.equal(W.doorOpenGate81fd60(0, 0x80000000 >>> 0, 0, 0x1000, 0x2000), 1);
});

test("vtbl28_gate: byte clear + SIGNED seed >= field_10 + rec != node", () => {
  /* PE 0x0082004b..0x0082005f: jne skip (byte); jl skip (SIGNED); je skip
     (rec == node). */
  const cases = [
    [0, 5, 10, 0x1000, 0x2000, 0],  /* seed < field10 (signed) -> no call */
    [0, 10, 10, 0x1000, 0x2000, 1], /* all three -> call */
    [0, 10, 10, 0x1000, 0x1000, 0], /* rec == node -> no call */
    [1, 10, 10, 0x1000, 0x2000, 0], /* byte set -> no call */
    [0x100, 10, 10, 0x1000, 0x2000, 1], /* low byte clear */
    [0, -1, 0, 0x1000, 0x2000, 0],  /* SIGNED: -1 < 0 -> no call */
    [0, 0x80000000, 0, 0x1000, 0x2000, 0], /* SIGNED: -2^31 < 0 */
    [0, -1, -5, 0x1000, 0x2000, 1], /* -1 >= -5 -> check ptr */
    [0, 0x80000000, 0x80000000, 0x1000, 0x2000, 1], /* equal -> check ptr */
    [0, 0, 0, 0x1000, 0x2000, 1],
    [0, 0, 0, 0x1000, 0x1000, 0],
  ];
  for (const [b, sd, f, r, n, exp] of cases) {
    assert.equal(W.vtbl28Gate81fd60(b >>> 0, sd | 0, f | 0, r >>> 0, n >>> 0),
                 exp, `vtbl ${b},${sd},${f},${r},${n}`);
    assert.equal(W.vtbl28Gate81fd60(b >>> 0, sd | 0, f | 0, r >>> 0, n >>> 0),
                 frameEffect81fd60Vtbl28Gate(b >>> 0, sd | 0, f | 0, r >>> 0, n >>> 0),
                 `js vtbl ${b},${sd},${f},${r},${n}`);
  }
  /* SIGNED discriminator: 0x80000000 (< 0) never calls (unsigned mutant
     would). */
  assert.equal(W.vtbl28Gate81fd60(0, 0x80000000 | 0, 0, 0x1000, 0x2000), 0);
});

