test("free_invalid_param: (size&~3) >=u 0x1000 && delta >u 0x1f", () => {
  /* PE 0x008200f8 cmp edx,0x1000; jb skip; 0x0082010b cmp eax,0x1f; jbe
     skip — both UNSIGNED. */
  const cases = [
    [0xfff, 0x20, 0], [0x1000, 0x1f, 0], [0x1000, 0x20, 1],
    [0x1000, 0x21, 1], [0x1000, 0, 0], [0xffffffff, 0xffffffff, 1],
    [0x7fffffff, 0x20, 1], [0x1000, 0x80000000, 1], [0xffffffff, 0x20, 1],
  ];
  for (const [s, d, exp] of cases) {
    assert.equal(W.freeInvalidParam81fd60(s >>> 0, d >>> 0), exp,
                 `free ${s},${d}`);
    assert.equal(W.freeInvalidParam81fd60(s >>> 0, d >>> 0),
                 frameEffect81fd60FreeInvalidParam(s >>> 0, d >>> 0),
                 `js free ${s},${d}`);
  }
  /* boundary: exactly 0x1000 / 0x20 trips; 0xfff / 0x1f does not. */
  assert.equal(W.freeInvalidParam81fd60(0x1000 >>> 0, 0x20 >>> 0), 1);
  assert.equal(W.freeInvalidParam81fd60(0x1000 >>> 0, 0x1f >>> 0), 0);
});

test("v21 laws: randomized differential wasm === JS oracle (unmasked)", () => {
  const rnd = lcg32(0x81fd60);
  for (let i = 0; i < 200; i += 1) {
    const a = rnd(), b = rnd(), c = rnd(), d = rnd(), e = rnd();
    assert.equal(W.spawnLoopRuns81fd60(a >>> 0), frameEffect81fd60SpawnLoopRuns(a >>> 0));
    assert.equal(W.seedValid81fd60(a >>> 0), frameEffect81fd60SeedValid(a >>> 0));
    assert.equal(W.slotOpenGate81fd60(a >>> 0), frameEffect81fd60SlotOpenGate(a >>> 0));
    assert.equal(W.respawnSkipGate81fd60(a >>> 0, b | 0, c | 0, d >>> 0, e >>> 0),
                 frameEffect81fd60RespawnSkipGate(a >>> 0, b | 0, c | 0, d >>> 0, e >>> 0));
    assert.equal(W.respawnReturnGate81fd60(a >>> 0), frameEffect81fd60RespawnReturnGate(a >>> 0));
    assert.equal(W.respawnOutGate81fd60(a >>> 0), frameEffect81fd60RespawnOutGate(a >>> 0));
    assert.equal(W.walk1Enter81fd60(a | 0), frameEffect81fd60Walk1Enter(a | 0));
    assert.equal(W.walk1FlagGate81fd60(a >>> 0), frameEffect81fd60Walk1FlagGate(a >>> 0));
    assert.equal(W.list2Enter81fd60(a >>> 0), frameEffect81fd60List2Enter(a >>> 0));
    assert.equal(W.loop2Enter81fd60(a >>> 0), frameEffect81fd60Loop2Enter(a >>> 0));
    assert.equal(W.doorOpenGate81fd60(a >>> 0, b >>> 0, c | 0, d >>> 0, e >>> 0),
                 frameEffect81fd60DoorOpenGate(a >>> 0, b >>> 0, c | 0, d >>> 0, e >>> 0));
    assert.equal(W.vtbl28Gate81fd60(a >>> 0, b | 0, c | 0, d >>> 0, e >>> 0),
                 frameEffect81fd60Vtbl28Gate(a >>> 0, b | 0, c | 0, d >>> 0, e >>> 0));
    assert.equal(W.slotNeedsReset81fd60(a | 0), frameEffect81fd60SlotNeedsReset(a | 0));
    assert.equal(W.slotTypeOpen81fd60(a | 0, b | 0), frameEffect81fd60SlotTypeOpen(a | 0, b | 0));
    assert.equal(W.freeInvalidParam81fd60(a >>> 0, b >>> 0),
                 frameEffect81fd60FreeInvalidParam(a >>> 0, b >>> 0));
  }
});

test("no uint8_t scalar parameters in the v21 declaration block", () => {
  const v21Block = HDR.slice(HDR.indexOf("/* ABI v21. Pure decision seams"));
  const v21End = v21Block.indexOf("/* Combined entry plan");
  const block = v21Block.slice(0, v21End);
  const declLines = block
    .split("\n")
    .filter((ln) =>
      /^(void|uint32_t|int32_t)\s+isaac_frame_effect_81fd60_/.test(ln.trim()),
    );
  assert.ok(declLines.length >= 15, `expected 15 v21 declarations, got ${declLines.length}`);
  assert.doesNotMatch(block, /uint8_t/);
  /* every declared export is wired into EXPORTS and the W object */
  for (const ln of declLines) {
    const shortName = ln.match(/isaac_frame_effect_81fd60_([a-z0-9_]+)/)[1];
    const name = `isaac_frame_effect_81fd60_${shortName}`;
    assert.ok(EXPORTS.includes(name), `EXPORTS missing ${name}`);
    const wKey = shortName.replace(/_([a-z0-9])/g, (_, c) => c.toUpperCase());
    const key = `${wKey}81fd60`;
    assert.equal(typeof W[key], "function", `W missing ${name}`);
  }
});

test("v21 mutants: word/low-byte leaks, signedness pair, pointer flip, ABI", () => {
  /* M1 WORD gate: 0x10000 has a zero low word — a full-dword mutant would
     run the loop. */
  assert.equal(W.spawnLoopRuns81fd60(0x10000 >>> 0), 0);
  assert.notEqual(W.spawnLoopRuns81fd60(0x10000 >>> 0), 1);
  /* M2 LOW-BYTE leak: 0x100 is CLEAR for slot_open / 0x7ed310 AL / vtbl
     AL — a full-dword mutant would see them as nonzero and run. */
  assert.equal(W.slotOpenGate81fd60(0 >>> 0), 0);
  assert.equal(W.slotOpenGate81fd60(0x100 >>> 0), 0);
  assert.equal(W.respawnReturnGate81fd60(0 >>> 0), 0);
  assert.equal(W.respawnReturnGate81fd60(0x100 >>> 0), 0);
  assert.equal(W.walk1FlagGate81fd60(0 >>> 0), 0);
  assert.equal(W.walk1FlagGate81fd60(0x100 >>> 0), 0);
  /* ... and the set side must survive: 0xff / 0x1ff run. */
  assert.equal(W.slotOpenGate81fd60(0xff >>> 0), 1);
  assert.equal(W.respawnReturnGate81fd60(0x1ff >>> 0), 1);
  assert.equal(W.walk1FlagGate81fd60(0x1ff >>> 0), 1);
  /* M3 respawn_skip SIGNED: 0x80000000 (< 0) proceeds past the field_10
     test; an unsigned mutant would reach the pointer check and skip. */
  assert.equal(W.respawnSkipGate81fd60(0, 0x80000000 | 0, 0, 0x1000, 0x1000), 0);
  assert.notEqual(W.respawnSkipGate81fd60(0, 0x80000000 | 0, 0, 0x1000, 0x1000), 1);
  /* M4 door_open UNSIGNED: 0x80000000 is >=u 0, so the pointer check is
     reached; a signed mutant would proceed at the jb and never skip. */
  assert.equal(W.doorOpenGate81fd60(0, 0x80000000 >>> 0, 0, 0x1000, 0x2000), 1);
  assert.notEqual(W.doorOpenGate81fd60(0, 0x80000000 >>> 0, 0, 0x1000, 0x2000), 0);
  /* M5 vtbl28 SIGNED: 0x80000000 (< 0) never calls; an unsigned mutant
     would call with matching pointers. */
  assert.equal(W.vtbl28Gate81fd60(0, 0x80000000 | 0, 0, 0x1000, 0x2000), 0);
  assert.notEqual(W.vtbl28Gate81fd60(0, 0x80000000 | 0, 0, 0x1000, 0x2000), 1);
  /* M6 pointer flip: respawn_skip's rec==out arm is equality (a != mutant
     would never skip); door_open/vtbl28 arms are inequality. */
  assert.equal(W.respawnSkipGate81fd60(0, 10, 10, 0x1000, 0x1000), 1);
  assert.equal(W.doorOpenGate81fd60(0, 10, 10, 0x1000, 0x2000), 1);
  assert.equal(W.doorOpenGate81fd60(0, 10, 10, 0x1000, 0x1000), 0);
  assert.equal(W.vtbl28Gate81fd60(0, 10, 10, 0x1000, 0x2000), 1);
  assert.equal(W.vtbl28Gate81fd60(0, 10, 10, 0x1000, 0x1000), 0);
  /* M7 slot_type_open set: 0x1d arm must be live (dropping the pair kills
     the (3,0x1d) case); slot_needs_reset != 1 vs == 1. */
  assert.equal(W.slotTypeOpen81fd60(3 | 0, 0x1d | 0), 1);
  assert.equal(W.slotTypeOpen81fd60(0x1d | 0, 3 | 0), 1);
  assert.equal(W.slotTypeOpen81fd60(6 | 0, 6 | 0), 0);
  assert.equal(W.slotNeedsReset81fd60(1), 0);
  assert.equal(W.slotNeedsReset81fd60(2), 1);
  /* M8 free_invalid_param boundaries: 0x1000/0x20 trip, 0xfff/0x1f do
     not; an unsigned mutant on either compare is killed at 0x80000000. */
  assert.equal(W.freeInvalidParam81fd60(0x1000 >>> 0, 0x20 >>> 0), 1);
  assert.equal(W.freeInvalidParam81fd60(0x1000 >>> 0, 0x1f >>> 0), 0);
  assert.equal(W.freeInvalidParam81fd60(0xfff >>> 0, 0x20 >>> 0), 0);
  assert.equal(W.freeInvalidParam81fd60(0x80000000 >>> 0, 0x20 >>> 0), 1);
  /* M9 ABI pin + v21 census + source pins. */
  assert.equal(W.abi(), 51);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_PURE_HELPERS_ABI_VERSION = 51/);
  assert.equal(FRAME_EFFECT_PURE_ABI_VERSION, 51);
  assert.equal(FRAME_EFFECT_81FD60_INSN_COUNT, 341);
  assert.equal(FRAME_EFFECT_81FD60_BYTE_LEN, 1038);
  assert.equal(FRAME_EFFECT_81FD60_CALL_INSNS, 23);
  assert.equal(FRAME_EFFECT_81FD60_END_VA, 0x0082016d);
  assert.equal(FRAME_EFFECT_81FD60_NEXT_VA, 0x00820170);
  assert.deepEqual(FRAME_EFFECT_81FD60_DIRECT_CALLERS, [0x005bd864]);
  assert.deepEqual(FRAME_EFFECT_81FD60_RAW_DWORD_HITS, [0x0086c8b2]);
  assert.equal(FRAME_EFFECT_81FD60_LUA_BIND_VA, 0x0086c8b1);
  assert.equal(FRAME_EFFECT_81FD60_RNG_SHIFT1, 2);
  assert.equal(FRAME_EFFECT_81FD60_RNG_SHIFT2, 7);
  assert.equal(FRAME_EFFECT_81FD60_RNG_SHIFT3, 7);
  assert.equal(FRAME_EFFECT_81FD60_FATAL_LEVEL, 0x10);
  assert.match(SRC, /0x0081fe53: cmp dx,word \[eax\+0x44\]/);
  assert.match(SRC, /0x0081fe60: test esi,esi/);
  assert.match(SRC, /0x0081fea7: cmp byte \[edx\+8\],0/);
  assert.match(SRC, /0x0081ff04: cmp byte \[ecx\+0xd\],0/);
  assert.match(SRC, /0x0081ff2f: test al,al/);
  assert.match(SRC, /0x0081ff33: cmp dword \[ebp-0x10\],0/);
  assert.match(SRC, /0x0081ffab: test edi,edi/);
  assert.match(SRC, /0x0081ffc3: test al,al/);
  assert.match(SRC, /0x0081ffe6: cmp dword \[ebp-0x30\],0/);
  assert.match(SRC, /0x0081fff2: cmp dword \[ebx\+0x1264\],edi/);
  assert.match(SRC, /0x0082001f: cmp byte \[eax\+0xd\],0/);
  assert.match(SRC, /0x0082004b: cmp byte \[eax\+0xd\],0/);
  assert.match(SRC, /0x00820086: cmp dword \[esi\+0xc\],1/);
  assert.match(SRC, /0x0082009a..0x008200c2: six cmp\/je pairs/);
  assert.match(SRC, /0x008200f8: cmp edx,0x1000/);
});

/* ------------------------------------------------------------------ */
/* v22: FUN_0081fb70 LRoomTileDesc::GetRandomTile — remaining decision
 * seams — ABI 21 -> 22
 *
 * Four freestanding FULL-dword zero-tests from the still-host body
 * (202 insns / 482 bytes, exact ZHL GetRandomTile; 5 host log calls
 * 0xa112c0; 1 direct caller 0x0081ed21). The body has NO byte-width
 * tests — these are all `test reg,reg` full-dword gates selecting a host
 * fatal log+int3 or an unsigned div. The arithmetic islands (seed_mix,
 * umod, pick_a, …) stay covered by ABI v17. Evidence:
 * section-notes/frame-effect-v22-next/ (census-81fb70-body.json). */

test("seed_valid (81fb70): FULL-dword seed nonzero (fatal RNG log gate)", () => {
  /* PE 0x0081fbd2 test esi,esi; jne continue. */
  const cases = [[0, 0], [1, 1], [0x100, 1], [0x10000, 1],
                 [0x80000000, 1], [0xffffffff, 1], [-0x80000000, 1]];
  for (const [s, exp] of cases) {
    assert.equal(W.seedValid81fb70(s >>> 0), exp, `seed ${s}`);
    assert.equal(W.seedValid81fb70(s >>> 0),
                 frameEffect81fb70SeedValid(s >>> 0), `js seed ${s}`);
  }
  /* FULL-dword discriminators: 0x100 and 0x10000 are nonzero — a
     low-byte / word-leak mutant would return 0. */
  assert.equal(W.seedValid81fb70(0x100 >>> 0), 1);
  assert.equal(W.seedValid81fb70(0x10000 >>> 0), 1);
  assert.equal(W.seedValid81fb70(0), 0);
});

test("mixed_valid (81fb70): FULL-dword chain draw nonzero (same fatal)", () => {
  /* PE 0x0081fc19/0x0081fcc1 (draw 1) and 0x0081fc59/0x0081fd00
     (draw 2): test esi,esi; jne continue. */
  const cases = [[0, 0], [1, 1], [0x100, 1], [0x10000, 1],
                 [0x80000000, 1], [0xffffffff, 1], [0x7fffffff, 1]];
  for (const [m, exp] of cases) {
    assert.equal(W.mixedValid81fb70(m >>> 0), exp, `mixed ${m}`);
    assert.equal(W.mixedValid81fb70(m >>> 0),
                 frameEffect81fb70MixedValid(m >>> 0), `js mixed ${m}`);
  }
  assert.equal(W.mixedValid81fb70(0x100 >>> 0), 1);
  assert.equal(W.mixedValid81fb70(0x10000 >>> 0), 1);
  assert.equal(W.mixedValid81fb70(0), 0);
});

test("total_gate (81fb70): FULL-dword abs1+abs2 nonzero runs the pick div", () => {
  /* PE 0x0081fc08 test ecx,ecx; je skip-div — total==0 → rem 0 → the
     UNSIGNED pick falls to rect B. */
  const cases = [[0, 0], [1, 1], [0x100, 1], [0x10000, 1],
                 [0x80000000, 1], [0xffffffff, 1], [0x7fffffff, 1]];
  for (const [t, exp] of cases) {
    assert.equal(W.totalGate81fb70(t >>> 0), exp, `total ${t}`);
    assert.equal(W.totalGate81fb70(t >>> 0),
                 frameEffect81fb70TotalGate(t >>> 0), `js total ${t}`);
  }
  assert.equal(W.totalGate81fb70(0x10000 >>> 0), 1);
  assert.equal(W.totalGate81fb70(0), 0);
});

test("delta_gate (81fb70): FULL-dword RAW delta nonzero runs the index div", () => {
  /* PE 0x0081fc4c (dx2) / 0x0081fcf4 (dx1) / 0x0081fc82 (dy2) /
     0x0081fd29 (dy1): test reg,reg; je skip-div — a negative delta is a
     huge unsigned divisor (original defect) and TRIPS the gate. */
  const cases = [[0, 0], [1, 1], [0x100, 1], [0x10000, 1],
                 [0x80000000, 1], [0xffffffff, 1], [-1, 1], [0x7fffffff, 1]];
  for (const [d, exp] of cases) {
    assert.equal(W.deltaGate81fb70(d >>> 0), exp, `delta ${d}`);
    assert.equal(W.deltaGate81fb70(d >>> 0),
                 frameEffect81fb70DeltaGate(d >>> 0), `js delta ${d}`);
  }
  /* discriminators: 0x80000000 (negative delta) and 0x10000 both trip. */
  assert.equal(W.deltaGate81fb70(0x80000000 >>> 0), 1);
  assert.equal(W.deltaGate81fb70(0x10000 >>> 0), 1);
  assert.equal(W.deltaGate81fb70(0), 0);
});

test("v22 laws: randomized differential wasm === JS oracle (unmasked)", () => {
  const rnd = lcg32(0x81fb70);
  for (let i = 0; i < 200; i += 1) {
    const a = rnd(), c = rnd();
    assert.equal(W.seedValid81fb70(a >>> 0), frameEffect81fb70SeedValid(a >>> 0));
    assert.equal(W.mixedValid81fb70(a >>> 0), frameEffect81fb70MixedValid(a >>> 0));
    assert.equal(W.totalGate81fb70(c >>> 0), frameEffect81fb70TotalGate(c >>> 0));
    assert.equal(W.deltaGate81fb70(c >>> 0), frameEffect81fb70DeltaGate(c >>> 0));
  }
});

test("no uint8_t scalar parameters in the v22 declaration block", () => {
  const v22Block = HDR.slice(HDR.indexOf("/* ABI v22. Remaining pure decision seams"));
  const v22End = v22Block.indexOf("/* Combined entry plan");
  const block = v22Block.slice(0, v22End);
  const declLines = block
    .split("\n")
    .filter((ln) =>
      /^(void|uint32_t|int32_t)\s+isaac_frame_effect_81fb70_/.test(ln.trim()),
    );
  assert.ok(declLines.length >= 4, `expected 4 v22 declarations, got ${declLines.length}`);
  assert.doesNotMatch(block, /uint8_t/);
  /* every declared export is wired into EXPORTS and the W object */
  for (const ln of declLines) {
    const shortName = ln.match(/isaac_frame_effect_81fb70_([a-z0-9_]+)/)[1];
    const name = `isaac_frame_effect_81fb70_${shortName}`;
    assert.ok(EXPORTS.includes(name), `EXPORTS missing ${name}`);
    const wKey = shortName.replace(/_([a-z0-9])/g, (_, c) => c.toUpperCase());
    const key = `${wKey}81fb70`;
    assert.equal(typeof W[key], "function", `W missing ${name}`);
  }
});

test("v22 mutants: full-dword zero-test discriminators + ABI", () => {
  /* M1..M4 FULL-dword zero-tests: 0x100 / 0x10000 must trip each gate —
     a low-byte leak (0x100 & 0xff == 0) or word leak (0x10000 & 0xffff
     == 0) mutant returns 0. */
  assert.equal(W.seedValid81fb70(0x100 >>> 0), 1);
  assert.equal(W.seedValid81fb70(0x10000 >>> 0), 1);
  assert.equal(W.seedValid81fb70(0), 0);
  assert.equal(W.mixedValid81fb70(0x100 >>> 0), 1);
  assert.equal(W.mixedValid81fb70(0x10000 >>> 0), 1);
  assert.equal(W.mixedValid81fb70(0), 0);
  assert.equal(W.totalGate81fb70(0x10000 >>> 0), 1);
  assert.equal(W.totalGate81fb70(0), 0);
  assert.equal(W.deltaGate81fb70(0x10000 >>> 0), 1);
  assert.equal(W.deltaGate81fb70(0x80000000 >>> 0), 1);
  assert.equal(W.deltaGate81fb70(0), 0);
  /* M5 ABI pin + v22 census + source pins. */
  assert.equal(W.abi(), 51);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_PURE_HELPERS_ABI_VERSION = 51/);
  assert.equal(FRAME_EFFECT_PURE_ABI_VERSION, 51);
  assert.equal(FRAME_EFFECT_81FB70_V22_INSN_COUNT, 202);
  assert.equal(FRAME_EFFECT_81FB70_V22_BYTE_LEN, 482);
  assert.equal(FRAME_EFFECT_81FB70_V22_CALL_INSNS, 5);
  assert.equal(FRAME_EFFECT_81FB70_V22_END_VA, 0x0081fd51);
  assert.equal(FRAME_EFFECT_81FB70_V22_NEXT_VA, 0x0081fd60);
  assert.deepEqual(FRAME_EFFECT_81FB70_V22_DIRECT_CALLERS, [0x0081ed21]);
  assert.equal(FRAME_EFFECT_81FB70_V22_FATAL_STR_VA, 0x00b6bf54);
  assert.equal(FRAME_EFFECT_81FB70_V22_FATAL_LEVEL, 0x10);
  assert.equal(FRAME_EFFECT_81FB70_V22_RNG_SHIFT1_VA, 0x00b1f4ec);
  assert.equal(FRAME_EFFECT_81FB70_V22_RNG_SHIFT2_VA, 0x00b1f4f0);
  assert.equal(FRAME_EFFECT_81FB70_V22_RNG_SHIFT3_VA, 0x00b1f4f4);
  assert.match(SRC, /0x0081fbd2: test esi,esi/);
  assert.match(SRC, /0x0081fc19 \/ 0x0081fcc1 \(draw 1\)/);
  assert.match(SRC, /0x0081fc08: test ecx,ecx/);
  assert.match(SRC, /0x0081fc4c \(dx2\) \/ 0x0081fcf4 \(dx1\)/);
});

/* ------------------------------------------------------------------ */
/* v23: FUN_00820170 Lua Room:TrySpawnBlueWombDoor — pure decision
 * seams — ABI 22 -> 23
 *
 * The body (0x00820170..0x00820445 `ret 0xc`; region incl. the CS
 * re-check tail 0x008204ae) is a C++ EH + GS host (handler stub
 * 0xb01801, FuncInfo 0xbc2460, unwind handler 0xb017f0 = the 0xc8108c
 * critical-section wrapper). The 22 laws below are the SEH-free
 * captured-value decision surface. Evidence:
 * section-notes/frame-effect-v23-820170/ (census-820170-body.json). */

test("arg3_gate / stage_gate / level_flag_gate / level_type_gate / queue_gate / game_flag_gate (820170): entry cluster", () => {
  /* LOW BYTE gates: 0x100 must NOT trip — a byte-leak mutant returns 1. */
  for (const v of [0xff, 0x1ff, 1]) {
    assert.equal(W.arg3Gate820170(v >>> 0), 1, `arg3 ${v}`);
    assert.equal(W.levelFlagGate820170(v >>> 0), 1, `levelFlag ${v}`);
    assert.equal(W.gameFlagGate820170(v >>> 0), 1, `gameFlag ${v}`);
  }
  for (const v of [0, 0x100, 0x80000000]) {
    assert.equal(W.arg3Gate820170(v >>> 0), 0, `arg3 ${v}`);
    assert.equal(W.levelFlagGate820170(v >>> 0), 0, `levelFlag ${v}`);
    assert.equal(W.gameFlagGate820170(v >>> 0), 0, `gameFlag ${v}`);
  }
  /* FULL dword equilibria: 0x2c / 2 are the reject values. */
  assert.equal(W.stageGate820170(0x2c), 0);
  assert.equal(W.stageGate820170(0), 1);
  assert.equal(W.stageGate820170(0x2d), 1);
  assert.equal(W.levelTypeGate820170(2), 0);
  assert.equal(W.levelTypeGate820170(0), 1);
  assert.equal(W.levelTypeGate820170(0x80000000), 1);
  /* UNSIGNED queue: 0x80000000 > 0 proceeds; a signed mutant returns 0. */
  assert.equal(W.queueGate820170(0), 0);
  assert.equal(W.queueGate820170(1), 1);
  assert.equal(W.queueGate820170(0x80000000 >>> 0), 1);
});

test("arg2_norm / room_sync_gate / probe_bit2_gate (820170): selects + equality", () => {
  /* arg2_norm: (f != 0) ? 1 : (arg2 & 0xff). */
  assert.equal(W.arg2Norm820170(0x1234 >>> 0, 0), 0x34);
  assert.equal(W.arg2Norm820170(0x100 >>> 0, 0), 0); /* low byte only */
  assert.equal(W.arg2Norm820170(0, 1), 1);
  assert.equal(W.arg2Norm820170(0xffffffff >>> 0, 0x100), 1);
  /* room_sync: FULL dword equality. */
  assert.equal(W.roomSyncGate820170(5, 5), 1);
  assert.equal(W.roomSyncGate820170(5, 6), 0);
  assert.equal(W.roomSyncGate820170(0xffffffff >>> 0, 0xffffffff >>> 0), 1);
  /* probe_bit2: LOW BYTE bit 2 of (~mask_b & mask_a). */
  assert.equal(W.probeBit2Gate820170(2, 0), 1);
  assert.equal(W.probeBit2Gate820170(0, 0), 0);
  assert.equal(W.probeBit2Gate820170(2, 2), 0); /* b consumed the bit */
  assert.equal(W.probeBit2Gate820170(6, 2), 0); /* a&2 mutant → 1 */
  assert.equal(W.probeBit2Gate820170(0x102 >>> 0, 0), 1);
  assert.equal(W.probeBit2Gate820170(0x100 >>> 0, 0), 0); /* bit 1 only */
  assert.equal(W.probeBit2Gate820170(0xffffffff >>> 0, 0xffffffff >>> 0), 0);
});

test("room_byte_gate / room_bound_gate / slot8_gate / room_kind_gate (820170): shape cluster", () => {
  assert.equal(W.roomByteGate820170(0), 0);
  assert.equal(W.roomByteGate820170(0xff), 1);
  assert.equal(W.roomByteGate820170(0x100), 0); /* byte-leak mutant */
  assert.equal(W.roomByteGate820170(0x1ff), 1);
  /* SIGNED bound: (1, 0x80000000) does NOT pass (1 < -2^31 false); an
     unsigned mutant accepts it. (0x80000000, 1) passes signed and fails
     unsigned — the discriminator. */
  assert.equal(W.roomBoundGate820170(7, 8), 1);
  assert.equal(W.roomBoundGate820170(8, 8), 0);
  assert.equal(W.roomBoundGate820170(0xffffffff >>> 0, 0), 1); /* -1 < 0 */
  assert.equal(W.roomBoundGate820170(1, 0x80000000 >>> 0), 0);
  assert.equal(W.roomBoundGate820170(0x80000000 >>> 0, 1), 1);
  assert.equal(W.roomBoundGate820170(0x80000000 >>> 0, 0xffffffff >>> 0), 1); /* -2^31 < -1 */
  /* slot base must be exactly 8. */
  assert.equal(W.slot8Gate820170(8), 1);
  for (const v of [0, 7, 9]) assert.equal(W.slot8Gate820170(v), 0);
  /* kind not in {4,5}. */
  for (const v of [4, 5]) assert.equal(W.roomKindGate820170(v), 0);
  for (const v of [0, 3, 6, 0x80000000]) assert.equal(W.roomKindGate820170(v >>> 0), 1);
});

test("slot_free_gate / overflow_gate / arg2_gate / tick_state_gate / tick_idx_gate (820170): state cluster", () => {
  /* slot_free proceeds iff slot==0 OR state != busy mark. */
  assert.equal(W.slotFreeGate820170(0, 0xfffffff8 >>> 0), 1);
  assert.equal(W.slotFreeGate820170(1, 0xfffffff8 >>> 0), 0);
  assert.equal(W.slotFreeGate820170(1, 0), 1);
  assert.equal(W.slotFreeGate820170(0xffffffff >>> 0, 0xfffffff8 >>> 0), 0);
  assert.equal(W.slotFreeGate820170(0xffffffff >>> 0, 0xfffffff7 >>> 0), 1);
  /* SIGNED overflow: (0x80000000, 0) does NOT exceed; (1, 0x80000000) does. */
  assert.equal(W.overflowGate820170(1, 0), 1);
  assert.equal(W.overflowGate820170(0, 0), 0);
  assert.equal(W.overflowGate820170(0, 1), 0);
  assert.equal(W.overflowGate820170(0x80000000 >>> 0, 0), 0);
  assert.equal(W.overflowGate820170(1, 0x80000000 >>> 0), 1);
  /* arg2 LOW BYTE of the normalized value. */
  assert.equal(W.arg2Gate820170(0), 0);
  assert.equal(W.arg2Gate820170(1), 1);
  assert.equal(W.arg2Gate820170(0x100), 0);
  assert.equal(W.arg2Gate820170(0x1ff), 1);
  /* tick_state: only the busy mark takes the fast path. */
  assert.equal(W.tickStateGate820170(0xfffffff8 >>> 0), 1);
  for (const v of [0, 8, 0xfffffff7]) assert.equal(W.tickStateGate820170(v >>> 0), 0);
  /* tick_idx SIGNED nonnegative. */
  for (const v of [0, 1, 7]) assert.equal(W.tickIdxGate820170(v), 1);
  for (const v of [0x80000000, 0xffffffff]) assert.equal(W.tickIdxGate820170(v >>> 0), 0);
});

test("slot_null_gate / rng_valid_gate / bit_probe_gate / arg1_gate (820170): ptr + fatal + probes", () => {
  assert.equal(W.slotNullGate820170(0), 1);
  for (const v of [1, 0xffffffff]) assert.equal(W.slotNullGate820170(v >>> 0), 0);
  /* FULL dword RNG state nonzero (fatal seed analog): 0x100/0x10000 trip. */
  assert.equal(W.rngValidGate820170(0), 0);
  for (const v of [1, 0x100, 0x10000, 0x80000000]) {
    assert.equal(W.rngValidGate820170(v >>> 0), 1);
  }
  /* bit probe: (word & mask) != 0. */
  assert.equal(W.bitProbeGate820170(0, 1), 0);
  assert.equal(W.bitProbeGate820170(1, 1), 1);
  assert.equal(W.bitProbeGate820170(0x100 >>> 0, 0x100 >>> 0), 1);
  assert.equal(W.bitProbeGate820170(0x100 >>> 0, 0x200 >>> 0), 0);
  assert.equal(W.bitProbeGate820170(0xffffffff >>> 0, 0x80000000 >>> 0), 1);
  /* arg1 LOW BYTE. */
  assert.equal(W.arg1Gate820170(0), 0);
  assert.equal(W.arg1Gate820170(1), 1);
  assert.equal(W.arg1Gate820170(0x100), 0); /* byte-leak mutant */
  assert.equal(W.arg1Gate820170(0x1ff), 1);
});

test("v23 laws: randomized differential wasm === JS oracle (unmasked)", () => {
  const rnd = lcg32(0x820170);
  for (let i = 0; i < 200; i += 1) {
    const a = rnd(), b = rnd(), c = rnd();
    assert.equal(W.arg3Gate820170(a >>> 0), frameEffect820170Arg3Gate(a >>> 0));
    assert.equal(W.stageGate820170(a >>> 0), frameEffect820170StageGate(a >>> 0));
    assert.equal(W.levelFlagGate820170(a >>> 0), frameEffect820170LevelFlagGate(a >>> 0));
    assert.equal(W.levelTypeGate820170(a >>> 0), frameEffect820170LevelTypeGate(a >>> 0));
    assert.equal(W.queueGate820170(a >>> 0), frameEffect820170QueueGate(a >>> 0));
    assert.equal(W.gameFlagGate820170(a >>> 0), frameEffect820170GameFlagGate(a >>> 0));
    assert.equal(W.arg2Norm820170(a >>> 0, b >>> 0), frameEffect820170Arg2Norm(a >>> 0, b >>> 0));
    assert.equal(W.roomSyncGate820170(a >>> 0, b >>> 0), frameEffect820170RoomSyncGate(a >>> 0, b >>> 0));
    assert.equal(W.probeBit2Gate820170(a >>> 0, b >>> 0), frameEffect820170ProbeBit2Gate(a >>> 0, b >>> 0));
    assert.equal(W.roomByteGate820170(a >>> 0), frameEffect820170RoomByteGate(a >>> 0));
    assert.equal(W.roomBoundGate820170(a >>> 0, b >>> 0), frameEffect820170RoomBoundGate(a >>> 0, b >>> 0));
    assert.equal(W.slot8Gate820170(a >>> 0), frameEffect820170Slot8Gate(a >>> 0));
    assert.equal(W.roomKindGate820170(a >>> 0), frameEffect820170RoomKindGate(a >>> 0));
    assert.equal(W.slotFreeGate820170(a >>> 0, b >>> 0), frameEffect820170SlotFreeGate(a >>> 0, b >>> 0));
    assert.equal(W.overflowGate820170(a >>> 0, b >>> 0), frameEffect820170OverflowGate(a >>> 0, b >>> 0));
    assert.equal(W.arg2Gate820170(a >>> 0), frameEffect820170Arg2Gate(a >>> 0));
    assert.equal(W.tickStateGate820170(a >>> 0), frameEffect820170TickStateGate(a >>> 0));
    assert.equal(W.tickIdxGate820170(c >>> 0), frameEffect820170TickIdxGate(c >>> 0));
    assert.equal(W.slotNullGate820170(a >>> 0), frameEffect820170SlotNullGate(a >>> 0));
    assert.equal(W.rngValidGate820170(a >>> 0), frameEffect820170RngValidGate(a >>> 0));
    assert.equal(W.bitProbeGate820170(a >>> 0, b >>> 0), frameEffect820170BitProbeGate(a >>> 0, b >>> 0));
    assert.equal(W.arg1Gate820170(a >>> 0), frameEffect820170Arg1Gate(a >>> 0));
  }
});

test("no uint8_t scalar parameters in the v23 declaration block", () => {
  const v23Block = HDR.slice(HDR.indexOf("/* ABI v23. Pure decision seams"));
  const v23End = v23Block.indexOf("/* Combined entry plan");
  const block = v23Block.slice(0, v23End);
  const declLines = block
    .split("\n")
    .filter((ln) =>
      /^(void|uint32_t|int32_t)\s+isaac_frame_effect_820170_/.test(ln.trim()),
    );
  assert.ok(declLines.length >= 22, `expected 22 v23 declarations, got ${declLines.length}`);
  assert.doesNotMatch(block, /uint8_t/);
  /* every declared export is wired into EXPORTS and the W object */
  for (const ln of declLines) {
    const shortName = ln.match(/isaac_frame_effect_820170_([a-z0-9_]+)/)[1];
    const name = `isaac_frame_effect_820170_${shortName}`;
    assert.ok(EXPORTS.includes(name), `EXPORTS missing ${name}`);
    const wKey = shortName.replace(/_([a-z0-9])/g, (_, c) => c.toUpperCase());
    const key = `${wKey}820170`;
    assert.equal(typeof W[key], "function", `W missing ${name}`);
  }
});

test("v23 mutants: discriminators + ABI + census + source pins", () => {
  /* M1..M6 LOW-BYTE leaks: 0x100 must NOT trip a low-byte gate — a
     &0xff mutant returns 1. */
  for (const gate of [W.arg3Gate820170, W.levelFlagGate820170, W.gameFlagGate820170,
                      W.roomByteGate820170, W.arg2Gate820170, W.arg1Gate820170]) {
    assert.equal(gate(0x100 >>> 0), 0);
    assert.equal(gate(0xff), 1);
    assert.equal(gate(0), 0);
  }
  /* M7 probe_bit2 must consume ~mask_b: (2,2) and (6,2) are 0; an
     `a & 2` mutant returns 1 on both. */
  assert.equal(W.probeBit2Gate820170(2, 2), 0);
  assert.equal(W.probeBit2Gate820170(6, 2), 0);
  assert.equal(W.probeBit2Gate820170(2, 0), 1);
  /* M8/M9 SIGNED leaks: unsigned mutants flip these edges. */
  assert.equal(W.roomBoundGate820170(1, 0x80000000 >>> 0), 0); /* 1 < -2^31 false */
  assert.equal(W.roomBoundGate820170(0x80000000 >>> 0, 1), 1); /* -2^31 < 1 true */
  assert.equal(W.roomBoundGate820170(0x80000000 >>> 0, 0xffffffff >>> 0), 1); /* -2^31 < -1 */
  assert.equal(W.overflowGate820170(0x80000000 >>> 0, 0), 0);
  assert.equal(W.overflowGate820170(1, 0x80000000 >>> 0), 1);
  assert.equal(W.tickIdxGate820170(0x80000000 >>> 0), 0);
  assert.equal(W.queueGate820170(0x80000000 >>> 0), 1); /* M10 unsigned */
  /* M11 arg2_norm select + low byte. */
  assert.equal(W.arg2Norm820170(0x100 >>> 0, 0), 0);
  assert.equal(W.arg2Norm820170(0, 1), 1);
  /* M12 busy-mark equality fences. */
  assert.equal(W.tickStateGate820170(0xfffffff8 >>> 0), 1);
  assert.equal(W.tickStateGate820170(0xfffffff7 >>> 0), 0);
  assert.equal(W.slotFreeGate820170(0xffffffff >>> 0, 0xfffffff8 >>> 0), 0);
  assert.equal(W.slotFreeGate820170(0xffffffff >>> 0, 0xfffffff7 >>> 0), 1);
  /* M13 full-dword rng_valid: 0x100 / 0x10000 trip (byte/word leaks
     would clear). */
  assert.equal(W.rngValidGate820170(0x100 >>> 0), 1);
  assert.equal(W.rngValidGate820170(0x10000 >>> 0), 1);
  assert.equal(W.rngValidGate820170(0), 0);
  /* M-ABI pin + v23 census + source pins. */
  assert.equal(W.abi(), 51);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_PURE_HELPERS_ABI_VERSION = 51/);
  assert.equal(FRAME_EFFECT_PURE_ABI_VERSION, 51);
  assert.equal(FRAME_EFFECT_820170_V23_VA, 0x00820170);
  assert.equal(FRAME_EFFECT_820170_V23_END_VA, 0x00820445);
  assert.equal(FRAME_EFFECT_820170_V23_NEXT_VA, 0x008204b0);
  assert.equal(FRAME_EFFECT_820170_V23_RET_BYTES, 0xc);
  assert.equal(FRAME_EFFECT_820170_V23_INSN_COUNT, 224);
  assert.equal(FRAME_EFFECT_820170_V23_BYTE_LEN, 831);
  assert.equal(FRAME_EFFECT_820170_V23_CALL_INSNS, 14);
  assert.equal(FRAME_EFFECT_820170_V23_MAIN_CALLS.length, 10);
  assert.equal(FRAME_EFFECT_820170_V23_TAIL_CALLS.length, 4);
  assert.deepEqual(FRAME_EFFECT_820170_V23_DIRECT_CALLERS, [
    { site: 0x005fbdda, args: [0, 1, 1] },
    { site: 0x0073ed73, args: [0, 0, 0] },
    { site: 0x00806a57, args: [0, 0, 1] },
  ]);
  assert.deepEqual(FRAME_EFFECT_820170_V23_DWORD_HITS, [0x0086c719, 0x00890fa8]);
  assert.equal(FRAME_EFFECT_820170_V23_LUA_NAME_VA, 0x00b73b78); /* TrySpawnBlueWombDoor */
  assert.equal(FRAME_EFFECT_820170_V23_LUA_BINDER_VA, 0x0086c719);
  assert.equal(FRAME_EFFECT_820170_V23_SEH_STUB_VA, 0x00b01801);
  assert.equal(FRAME_EFFECT_820170_V23_FUNCINFO_VA, 0x00bc2460);
  assert.equal(FRAME_EFFECT_820170_V23_UNWIND_HANDLER_VA, 0x00b017f0);
  assert.equal(FRAME_EFFECT_820170_V23_CS_LOCK_VA, 0x00c8108c);
  assert.equal(FRAME_EFFECT_820170_V23_FATAL_STR_VA, 0x00b6bf54);
  assert.equal(FRAME_EFFECT_820170_V23_FATAL_LEVEL, 0x10);
  assert.equal(FRAME_EFFECT_820170_V23_RNG_SHIFT1_VA, 0x00b1f504); /* qword (1, 11) */
  assert.equal(FRAME_EFFECT_820170_V23_RNG_SHIFT3_VA, 0x00b1f50c); /* dword 16 */
  assert.equal(FRAME_EFFECT_820170_V23_SLOT_ARRAY_OFF, 0x724);
  assert.equal(FRAME_EFFECT_820170_V23_SLOT_STATE_OFF, 0x394);
  assert.equal(FRAME_EFFECT_820170_V23_SLOT_BUSY_MARK, 0xfffffff8);
  assert.equal(FRAME_EFFECT_820170_V23_MASK_A_VA, 0x006f9400);
  assert.equal(FRAME_EFFECT_820170_V23_MASK_B_VA, 0x006f95a0);
  assert.equal(FRAME_EFFECT_820170_V23_TRINKET_ID, 0xaf);
  assert.match(SRC, /0x008201a4 test bl,bl/);
  assert.match(SRC, /0x00820256 test al,2/);
  assert.match(SRC, /0x00820316 test edi,edi \(edi = \[\[this\+4\]\+0x58\]/);
  assert.match(SRC, /0x008202bc mov eax,\[edi\+0x264fc\]/);
  assert.match(SRC, /0x008202a2 test edx,edx/);
  assert.match(SRC, /0x00820404 cmp byte \[ebp\+8\],0/);
});

test("arg1_gate / stage_gate / probe_candidate (8204b0): entry cluster", () => {
  /* arg1 is the ONLY stack arg (`ret 4`); LOW BYTE. */
  assert.equal(W.arg1Gate8204b0(0), 0);
  assert.equal(W.arg1Gate8204b0(1), 1);
  assert.equal(W.arg1Gate8204b0(0x100), 0); /* byte-leak mutant */
  assert.equal(W.arg1Gate8204b0(0x1ff), 1);
  /* stage FULL dword equality with 0x2c (je -> return 0). */
  assert.equal(W.stageGate8204b0(0x2c), 0);
  for (const v of [0, 0x2b, 0x2d, 0x80000000]) assert.equal(W.stageGate8204b0(v >>> 0), 1);
  /* probe_candidate: base + (bit2 of ~m2 & merged ? 1 : 0); merged =
     m1 | g_a | g_b (all captured). */
  assert.equal(W.probeCandidate8204b0(3, 0, 0, 2, 0), 4); /* bit2 set -> +1 */
  assert.equal(W.probeCandidate8204b0(0, 0, 0, 2, 0), 1);
  assert.equal(W.probeCandidate8204b0(3, 0, 0, 2, 2), 3); /* ~m2 consumed the bit */
  assert.equal(W.probeCandidate8204b0(3, 0, 0, 6, 2), 3); /* (~2)&6 = 4, bit2 clear; drop-~b mutant -> 4 */
  assert.equal(W.probeCandidate8204b0(3, 0, 0, 0x102 >>> 0, 0), 4); /* bit 1 only is NOT bit 2 */
  assert.equal(W.probeCandidate8204b0(3, 0, 0, 0x100 >>> 0, 0), 3);
  assert.equal(W.probeCandidate8204b0(0xffffffff >>> 0, 0, 0, 2, 0), 0); /* base+1 wraps */
  /* gmask arms of the merge: g_a / g_b can supply the bit. */
  assert.equal(W.probeCandidate8204b0(3, 2, 0, 0, 0), 4);
  assert.equal(W.probeCandidate8204b0(3, 0, 2, 0, 0), 4);
  assert.equal(W.probeCandidate8204b0(3, 2, 0, 0, 2), 3);
});

test("slot9_gate / descriptor_kind_gate / dim_gate / kind23_gate (8204b0): slot cluster", () => {
  /* probe candidate must be exactly 9 (slot8_gate analog, fence 9). */
  assert.equal(W.slot9Gate8204b0(9), 1);
  for (const v of [0, 8, 10, 0x80000000]) assert.equal(W.slot9Gate8204b0(v >>> 0), 0);
  /* [[this+4]+0x10]+8 must be exactly 5. */
  assert.equal(W.descriptorKindGate8204b0(5), 1);
  for (const v of [0, 4, 6, 0x80000000]) assert.equal(W.descriptorKindGate8204b0(v >>> 0), 0);
  /* dim SIGNED nonnegative. */
  for (const v of [0, 1]) assert.equal(W.dimGate8204b0(v), 1);
  for (const v of [0x80000000, 0xffffffff]) assert.equal(W.dimGate8204b0(v >>> 0), 0);
  /* kind in {2,3} takes the flag tail. */
  for (const v of [2, 3]) assert.equal(W.kind23Gate8204b0(v), 1);
  for (const v of [0, 1, 4, 0x80000000]) assert.equal(W.kind23Gate8204b0(v >>> 0), 0);
});

test("bound_select / room_byte_gate / bound_recalc (8204b0): bound chain", () => {
  /* bound_select ORDER-SENSITIVE chain — every arm pinned. */
  /* (a) slot_40 == 0xc keeps 0xc regardless of the rest. */
  assert.equal(W.boundSelect8204b0(0xc, 5, 9, 0, 0, 0), 0xc);
  assert.equal(W.boundSelect8204b0(0xc, 0, 0, 0xff, 0, 0), 0xc);
  /* (b) stage != 0 -> 0xb. */
  assert.equal(W.boundSelect8204b0(0xb, 1, 0, 0, 0, 0), 0xb);
  /* (c) queue > 0 UNSIGNED -> 0xb; 0x80000000 trips unsigned only. */
  assert.equal(W.boundSelect8204b0(0xb, 0, 1, 0, 0, 0), 0xb);
  assert.equal(W.boundSelect8204b0(0xb, 0, 0x80000000 >>> 0, 0, 0, 0), 0xb); /* signed mutant -> 0xb via tail, caught below */
  assert.equal(W.boundSelect8204b0(0xb, 0, 0x80000000 >>> 0, 0xff, 2, 0), 0xb); /* UNSIGNED queue precedes lv_flag: signed mutant -> 0xc */
  /* (d) lv_flag LOW BYTE != 0 keeps 0xc. */
  assert.equal(W.boundSelect8204b0(0xb, 0, 0, 0xff, 0, 0), 0xc);
  assert.equal(W.boundSelect8204b0(0xb, 0, 0, 0x100 >>> 0, 0, 0), 0xb); /* byte 0 -> falls through to 0xb; full-dword mutant -> 0xc */
  /* (e) lv_type != 2 -> 0xb. */
  assert.equal(W.boundSelect8204b0(0xb, 0, 0, 0, 3, 0), 0xb);
  /* (f) game_flag LOW BYTE != 0 keeps 0xc. */
  assert.equal(W.boundSelect8204b0(0xb, 0, 0, 0, 2, 0xff), 0xc);
  assert.equal(W.boundSelect8204b0(0xb, 0, 0, 0, 2, 0x100 >>> 0), 0xb); /* byte 0 -> falls through to 0xb; full-dword mutant -> 0xc */
  /* (g) else 0xb — the only 0xc survivors are (a),(d),(f). */
  assert.equal(W.boundSelect8204b0(0xb, 0, 0, 0, 2, 0), 0xb);
  assert.equal(W.boundSelect8204b0(0xb, 0, 0, 0, 2, 0x80000000 >>> 0), 0xb); /* game_flag byte 0 */
  /* room_byte_gate LOW BYTE (the +0x7f check). */
  assert.equal(W.roomByteGate8204b0(0), 0);
  assert.equal(W.roomByteGate8204b0(0xff), 1);
  assert.equal(W.roomByteGate8204b0(0x100), 0); /* byte-leak mutant */
  assert.equal(W.roomByteGate8204b0(0x1ff), 1);
  /* bound_recalc cmove select: (slot_40 != 0) ? slot_40 : bound. */
  assert.equal(W.boundRecalc8204b0(5, 0xc), 0xc);
  assert.equal(W.boundRecalc8204b0(5, 0), 5);
  assert.equal(W.boundRecalc8204b0(0xc, 0xc), 0xc);
  assert.equal(W.boundRecalc8204b0(0, 0), 0);
  assert.equal(W.boundRecalc8204b0(0xb, 0x80000000 >>> 0) >>> 0, 0x80000000);
});

test("room_type3_gate / bound_min_gate / flag_bit_gate (8204b0): flag tail cluster", () => {
  /* room_type3: [0x706940ret]+0x80 == 3. */
  assert.equal(W.roomType3Gate8204b0(3), 1);
  for (const v of [0, 2, 4, 0x80000000]) assert.equal(W.roomType3Gate8204b0(v >>> 0), 0);
  /* bound_min SIGNED: bound < 0xc. */
  assert.equal(W.boundMinGate8204b0(0xb), 1);
  assert.equal(W.boundMinGate8204b0(0xc), 0);
  assert.equal(W.boundMinGate8204b0(0x80000000 >>> 0), 1); /* -2^31 < 0xc; unsigned mutant -> 0 */
  assert.equal(W.boundMinGate8204b0(0xffffffff >>> 0), 1); /* -1 < 0xc */
  /* flag_bit: (flag & 0x200000) != 0. */
  assert.equal(W.flagBitGate8204b0(0x200000 >>> 0), 1);
  assert.equal(W.flagBitGate8204b0(0x200001 >>> 0), 1);
  assert.equal(W.flagBitGate8204b0(0x100000 >>> 0), 0);
  assert.equal(W.flagBitGate8204b0(0), 0);
});

test("room_byte0_gate / bound_spawn_gate (8204b0): spawn gates", () => {
  /* room_byte0: LOW BYTE ZERO takes the spawn tail — the byte-0 twin of
     room_byte_gate; a full-dword mutant clears on 0x100. */
  assert.equal(W.roomByte0Gate8204b0(0), 1);
  assert.equal(W.roomByte0Gate8204b0(0x100 >>> 0), 1); /* byte 0 despite dword nonzero */
  assert.equal(W.roomByte0Gate8204b0(0xff), 0);
  assert.equal(W.roomByte0Gate8204b0(0x1ff), 0);
  /* bound_spawn SIGNED: candidate < [0x706940ret]+0x40. */
  assert.equal(W.boundSpawnGate8204b0(7, 8), 1);
  assert.equal(W.boundSpawnGate8204b0(8, 8), 0);
  assert.equal(W.boundSpawnGate8204b0(0xffffffff >>> 0, 0), 1); /* -1 < 0 */
  assert.equal(W.boundSpawnGate8204b0(1, 0x80000000 >>> 0), 0); /* 1 < -2^31 false */
  assert.equal(W.boundSpawnGate8204b0(0x80000000 >>> 0, 1), 1); /* -2^31 < 1; unsigned mutant -> 0 */
});

test("v24 laws: randomized differential wasm === JS oracle (unmasked)", () => {
  const rnd = lcg32(0x8204b0);
  for (let i = 0; i < 200; i += 1) {
    const a = rnd(), b = rnd(), c = rnd(), d = rnd(), e = rnd();
    assert.equal(W.arg1Gate8204b0(a >>> 0), frameEffect8204b0Arg1Gate(a >>> 0));
    assert.equal(W.stageGate8204b0(a >>> 0), frameEffect8204b0StageGate(a >>> 0));
    assert.equal(W.probeCandidate8204b0(a >>> 0, b >>> 0, c >>> 0, d >>> 0, e >>> 0) >>> 0,
                 frameEffect8204b0ProbeCandidate(a >>> 0, b >>> 0, c >>> 0, d >>> 0, e >>> 0));
    assert.equal(W.slot9Gate8204b0(a >>> 0), frameEffect8204b0Slot9Gate(a >>> 0));
    assert.equal(W.descriptorKindGate8204b0(a >>> 0), frameEffect8204b0DescriptorKindGate(a >>> 0));
    assert.equal(W.dimGate8204b0(a >>> 0), frameEffect8204b0DimGate(a >>> 0));
    assert.equal(W.kind23Gate8204b0(a >>> 0), frameEffect8204b0Kind23Gate(a >>> 0));
    assert.equal(W.boundSelect8204b0(a >>> 0, b >>> 0, c >>> 0, d >>> 0, e >>> 0, a >>> 0) >>> 0,
                 frameEffect8204b0BoundSelect(a >>> 0, b >>> 0, c >>> 0, d >>> 0, e >>> 0, a >>> 0));
    assert.equal(W.roomByteGate8204b0(a >>> 0), frameEffect8204b0RoomByteGate(a >>> 0));
    assert.equal(W.boundRecalc8204b0(a >>> 0, b >>> 0) >>> 0, frameEffect8204b0BoundRecalc(a >>> 0, b >>> 0));
    assert.equal(W.roomType3Gate8204b0(a >>> 0), frameEffect8204b0RoomType3Gate(a >>> 0));
    assert.equal(W.boundMinGate8204b0(a >>> 0), frameEffect8204b0BoundMinGate(a >>> 0));
    assert.equal(W.flagBitGate8204b0(a >>> 0), frameEffect8204b0FlagBitGate(a >>> 0));
    assert.equal(W.roomByte0Gate8204b0(a >>> 0), frameEffect8204b0RoomByte0Gate(a >>> 0));
    assert.equal(W.boundSpawnGate8204b0(a >>> 0, b >>> 0), frameEffect8204b0BoundSpawnGate(a >>> 0, b >>> 0));
  }
});

test("no uint8_t scalar parameters in the v24 declaration block", () => {
  const v24Block = HDR.slice(HDR.indexOf("/* ABI v24. Pure decision seams"));
  const v24End = v24Block.indexOf("/* Combined entry plan");
  const block = v24Block.slice(0, v24End);
  const declLines = block
    .split("\n")
    .filter((ln) =>
      /^(void|uint32_t|int32_t)\s+isaac_frame_effect_8204b0_/.test(ln.trim()),
    );
  assert.ok(declLines.length >= 15, `expected 15 v24 declarations, got ${declLines.length}`);
  assert.doesNotMatch(block, /uint8_t/);
  /* every declared export is wired into EXPORTS and the W object */
  for (const ln of declLines) {
    const shortName = ln.match(/isaac_frame_effect_8204b0_([a-z0-9_]+)/)[1];
    const name = `isaac_frame_effect_8204b0_${shortName}`;
    assert.ok(EXPORTS.includes(name), `EXPORTS missing ${name}`);
    const wKey = shortName.replace(/_([a-z0-9])/g, (_, c) => c.toUpperCase());
    const key = `${wKey}8204b0`;
    assert.equal(typeof W[key], "function", `W missing ${name}`);
  }
});

test("v24 mutants: discriminators + ABI + census + source pins", () => {
  /* M1 LOW-BYTE leaks: 0x100 must NOT trip a low-byte gate — an &0xff
     mutant returns 1. room_byte0 is inverted: 0x100 must TRIP (byte
     zero), a full-dword mutant returns 0. */
  for (const gate of [W.arg1Gate8204b0, W.roomByteGate8204b0]) {
    assert.equal(gate(0x100 >>> 0), 0);
    assert.equal(gate(0xff), 1);
    assert.equal(gate(0), 0);
  }
  assert.equal(W.roomByte0Gate8204b0(0x100 >>> 0), 1); /* byte 0 */
  assert.equal(W.roomByte0Gate8204b0(0), 1);
  assert.equal(W.roomByte0Gate8204b0(0xff), 0);
  /* M2 probe_candidate must consume ~mask_b: (m1=2, m2=2) and (6,2) stay
     base; a drop-~b mutant returns base+1 on both. */
  assert.equal(W.probeCandidate8204b0(3, 0, 0, 2, 2), 3);
  assert.equal(W.probeCandidate8204b0(3, 0, 0, 6, 2), 3);
  assert.equal(W.probeCandidate8204b0(3, 0, 0, 2, 0), 4);
  /* M3/M4/M5 SIGNED leaks: unsigned mutants flip these edges. */
  assert.equal(W.dimGate8204b0(0x80000000 >>> 0), 0);
  assert.equal(W.boundMinGate8204b0(0x80000000 >>> 0), 1);
  assert.equal(W.boundSpawnGate8204b0(1, 0x80000000 >>> 0), 0);
  assert.equal(W.boundSpawnGate8204b0(0x80000000 >>> 0, 1), 1);
  /* M6 bound_select queue UNSIGNED: 0x80000000 with lv_flag set and
     lv_type==2 must still take the 0xb queue arm EARLY — a signed
     mutant falls through to the lv_flag 0xc arm. */
  assert.equal(W.boundSelect8204b0(0xb, 0, 0x80000000 >>> 0, 0xff, 2, 0), 0xb);
  /* M7 bound_select arm order: (d) lv_flag byte != 0 keeps 0xc even when
     lv_type != 2 would 0xb later — swapped-arm mutant flips. */
  assert.equal(W.boundSelect8204b0(0xb, 0, 0, 0xff, 3, 0), 0xc);
  assert.equal(W.boundSelect8204b0(0xb, 1, 0, 0, 2, 0xff), 0xb); /* (b) precedes (f) */
  assert.equal(W.boundSelect8204b0(0xb, 0, 0, 0, 2, 0), 0xb); /* else arm */
  /* M8 ABI pin + v24 census + source pins. */
  assert.equal(W.abi(), 51);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_PURE_HELPERS_ABI_VERSION = 51/);
  assert.equal(FRAME_EFFECT_PURE_ABI_VERSION, 51);
  assert.equal(FRAME_EFFECT_8204B0_V24_VA, 0x008204b0);
  assert.equal(FRAME_EFFECT_8204B0_V24_END_VA, 0x0082061e);
  assert.equal(FRAME_EFFECT_8204B0_V24_NEXT_VA, 0x008206e0);
  assert.equal(FRAME_EFFECT_8204B0_V24_RET_BYTES, 4);
  assert.equal(FRAME_EFFECT_8204B0_V24_INSN_COUNT, 150);
  assert.equal(FRAME_EFFECT_8204B0_V24_BYTE_LEN, 557);
  assert.equal(FRAME_EFFECT_8204B0_V24_CALL_INSNS, 11);
  assert.equal(FRAME_EFFECT_8204B0_V24_MAIN_CALLS.length, 4);
  assert.equal(FRAME_EFFECT_8204B0_V24_SPAWN_CALLS.length, 3);
  assert.equal(FRAME_EFFECT_8204B0_V24_CS_CALLS.length, 4);
  assert.deepEqual(FRAME_EFFECT_8204B0_V24_DIRECT_CALLERS, [
    { site: 0x0073ed62, args: [0] },
    { site: 0x00806a60, args: [0] },
  ]);
  assert.deepEqual(FRAME_EFFECT_8204B0_V24_DWORD_HITS, [0x0086c72b]);
  assert.equal(FRAME_EFFECT_8204B0_V24_LUA_NAME_VA, 0x00b73b90); /* TrySpawnTheVoidDoor */
  assert.equal(FRAME_EFFECT_8204B0_V24_LUA_BINDER_VA, 0x0086c72a);
  assert.equal(FRAME_EFFECT_8204B0_V24_SEH_STUB_VA, 0x00b01831);
  assert.equal(FRAME_EFFECT_8204B0_V24_FUNCINFO_VA, 0x00bc248c);
  assert.equal(FRAME_EFFECT_8204B0_V24_UNWIND_HANDLER_VA, 0x00b01820);
  assert.equal(FRAME_EFFECT_8204B0_V24_CS_LOCK_VA, 0x00c8108c);
  assert.equal(FRAME_EFFECT_8204B0_V24_COOKIE_SLOT, 0xffffffdc); /* [ebp-0x24] */
  assert.equal(FRAME_EFFECT_8204B0_V24_SLOT_PTR_OFF, 0x738);
  assert.equal(FRAME_EFFECT_8204B0_V24_SLOT_STATE_OFF, 0x394);
  assert.equal(FRAME_EFFECT_8204B0_V24_SLOT_BUSY_MARK, 0xfffffff7);
  assert.equal(FRAME_EFFECT_8204B0_V24_FLAG_BIT, 0x200000);
  assert.equal(FRAME_EFFECT_8204B0_V24_BASE_OFF, 0x0);
  assert.equal(FRAME_EFFECT_8204B0_V24_MASK_A_VA, 0x006f9400);
  assert.equal(FRAME_EFFECT_8204B0_V24_MASK_B_VA, 0x006f95a0);
  assert.equal(FRAME_EFFECT_8204B0_V24_ROOM_VA, 0x00706940);
  assert.match(SRC, /0x008204db cmp byte \[ebp\+8\],0/);
  assert.match(SRC, /0x00820513 \/ cmove @ 0x00820515/);
  assert.match(SRC, /0x00820572\.\.0x008205ae/);
  assert.match(SRC, /0x008205fc cmp edi,\[eax\+0x40\]/);
});

/* ------------------------------------------------------------------ */
/* v25: FUN_0044bfb0 exact-ZHL PlayerManager::AnyoneHasTrinket — pure
 * decision seams — ABI 24 -> 25 (on F8's 0x8204b0 base)
 *
 * The body (0x0044bfb0..0x0044c06d, two `ret 4` epilogues) is a pure
 * QUERY: plain frame, no SEH/GS, 0 field stores, 2 E8 to the ZHL-empty
 * item query 0x771550 (AL captured). The 11 laws below are the complete
 * captured-value decision surface. Evidence:
 * section-notes/frame-effect-v24-leaves/ (census-v24-leaves.json). */

test("trinket_index / bound_gate / slot_null_gate / has_flag_gate (44bfb0): index + array gates", () => {
  /* 15-bit index mask: bits above 14 drop. */
  assert.equal(W.trinketIndex44bfb0(0x1234 >>> 0), 0x1234);
  assert.equal(W.trinketIndex44bfb0(0x18000 >>> 0), 0); /* M6 mask leak -> 0x8000 */
  assert.equal(W.trinketIndex44bfb0(0xffffffff >>> 0), 0x7fff);
  assert.equal(W.trinketIndex44bfb0(0x8000 >>> 0), 0);
  /* SIGNED bound: (0x80000000, 1) passes signed and fails unsigned;
     (1, 0x80000000) is the reverse — the discriminator. */
  assert.equal(W.boundGate44bfb0(1, 2), 1);
  assert.equal(W.boundGate44bfb0(2, 2), 0);
  assert.equal(W.boundGate44bfb0(0, 1), 1);
  assert.equal(W.boundGate44bfb0(0x80000000 >>> 0, 1), 1); /* -2^31 < 1 */
  assert.equal(W.boundGate44bfb0(1, 0x80000000 >>> 0), 0); /* 1 < -2^31 false */
  assert.equal(W.boundGate44bfb0(0xffffffff >>> 0, 0), 1); /* -1 < 0 */
  assert.equal(W.boundGate44bfb0(0xffffffff >>> 0, 0xffffffff >>> 0), 0);
  /* FULL dword slot null. */
  assert.equal(W.slotNullGate44bfb0(0), 0);
  for (const v of [1, 0x80000000, 0xffffffff]) {
    assert.equal(W.slotNullGate44bfb0(v >>> 0), 1);
  }
  /* bit-31 has flag: low-byte leaks must not trip. */
  assert.equal(W.hasFlagGate44bfb0(0), 0);
  assert.equal(W.hasFlagGate44bfb0(0x80000000 >>> 0), 1);
  assert.equal(W.hasFlagGate44bfb0(0x80000001 >>> 0), 1);
  assert.equal(W.hasFlagGate44bfb0(0x100), 0); /* M4 low-byte leak -> 1 */
  assert.equal(W.hasFlagGate44bfb0(0xffffffff >>> 0), 1);
});

test("walk_enter / active_gate / match_gate / second_probe_gate / alt_null_gate / walk_continue (44bfb0): list walk", () => {
  /* head != tail — FULL dword pointer compare. */
  assert.equal(W.walkEnter44bfb0(0, 0), 0);
  assert.equal(W.walkEnter44bfb0(0x1000 >>> 0, 0), 1);
  assert.equal(W.walkEnter44bfb0(0, 0x1000 >>> 0), 1);
  assert.equal(W.walkEnter44bfb0(0x80000000 >>> 0, 0x80000000 >>> 0), 0);
  /* active: [elem+0x2c] == 0 proceeds. */
  assert.equal(W.activeGate44bfb0(0), 1);
  for (const v of [1, 0x80000000, 0xffffffff]) {
    assert.equal(W.activeGate44bfb0(v >>> 0), 0);
  }
  /* match: 0x771550 AL — LOW BYTE. */
  assert.equal(W.matchGate44bfb0(0), 0);
  assert.equal(W.matchGate44bfb0(1), 1);
  assert.equal(W.matchGate44bfb0(0xff), 1);
  assert.equal(W.matchGate44bfb0(0x100), 0); /* M2 byte-leak -> 1 */
  assert.equal(W.matchGate44bfb0(0x1ff), 1);
  /* second probe runs iff found != 0 && al == 0 — LOW BYTE pair. */
  assert.equal(W.secondProbeGate44bfb0(0, 0), 0);
  assert.equal(W.secondProbeGate44bfb0(1, 0), 1);
  assert.equal(W.secondProbeGate44bfb0(1, 1), 0);
  assert.equal(W.secondProbeGate44bfb0(0, 1), 0);
  assert.equal(W.secondProbeGate44bfb0(0x100 >>> 0, 0), 0); /* M3 found-leak -> 1 */
  assert.equal(W.secondProbeGate44bfb0(0x101 >>> 0, 0), 1);
  /* alt pointer FULL dword. */
  assert.equal(W.altNullGate44bfb0(0), 0);
  for (const v of [1, 0x80000000, 0xffffffff]) {
    assert.equal(W.altNullGate44bfb0(v >>> 0), 1);
  }
  /* walk_continue: node_ptr != tail. */
  assert.equal(W.walkContinue44bfb0(0, 0), 0);
  assert.equal(W.walkContinue44bfb0(1, 0), 1); /* M8 inverted -> 0 */
  assert.equal(W.walkContinue44bfb0(0, 1), 1);
  assert.equal(W.walkContinue44bfb0(0xffffffff >>> 0, 0), 1);
});

test("result_gate (44bfb0): found-node result", () => {
  /* FULL dword zero test — both the main arm (0x44c04e) and the
     second-match arm (0x44c062, flags pre-pop) return setne al. */
  assert.equal(W.resultGate44bfb0(0), 0); /* M7 inverted -> 1 */
  for (const v of [1, 0x100, 0x80000000, 0xffffffff]) {
    assert.equal(W.resultGate44bfb0(v >>> 0), 1);
  }
});

