test("v25 mutants: discriminators + ABI + census + source pins", () => {
  /* M2 match_gate byte leak: 0x100 must NOT trip a low-byte gate. */
  assert.equal(W.matchGate44bfb0(0x100 >>> 0), 0);
  assert.equal(W.matchGate44bfb0(0xff), 1);
  /* M3 second_probe found-byte leak. */
  assert.equal(W.secondProbeGate44bfb0(0x100 >>> 0, 0), 0);
  assert.equal(W.secondProbeGate44bfb0(1, 0), 1);
  assert.equal(W.secondProbeGate44bfb0(1, 1), 0);
  /* M4 has_flag bit-31 -> low-byte leak. */
  assert.equal(W.hasFlagGate44bfb0(0x100), 0);
  assert.equal(W.hasFlagGate44bfb0(0x80000000 >>> 0), 1);
  assert.equal(W.hasFlagGate44bfb0(0x80000001 >>> 0), 1);
  /* M1 bound SIGNED edges (unsigned mutants flip). */
  assert.equal(W.boundGate44bfb0(0x80000000 >>> 0, 1), 1);
  assert.equal(W.boundGate44bfb0(1, 0x80000000 >>> 0), 0);
  assert.equal(W.boundGate44bfb0(0xffffffff >>> 0, 0), 1);
  /* M6 trinket mask 0x7fff. */
  assert.equal(W.trinketIndex44bfb0(0x18000 >>> 0), 0);
  assert.equal(W.trinketIndex44bfb0(0x8000 >>> 0), 0);
  assert.equal(W.trinketIndex44bfb0(0xffffffff >>> 0), 0x7fff);
  /* M5 alt_null inverted. */
  assert.equal(W.altNullGate44bfb0(1), 1);
  assert.equal(W.altNullGate44bfb0(0), 0);
  /* M7 result inverted / M8 walk_continue inverted. */
  assert.equal(W.resultGate44bfb0(1), 1);
  assert.equal(W.resultGate44bfb0(0), 0);
  assert.equal(W.walkContinue44bfb0(1, 0), 1);
  /* M9 ABI pin + v25 census + source pins. */
  assert.equal(W.abi(), 51);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_PURE_HELPERS_ABI_VERSION = 51/);
  assert.equal(FRAME_EFFECT_PURE_ABI_VERSION, 51);
  assert.equal(FRAME_EFFECT_44BFB0_V25_VA, 0x0044bfb0);
  assert.equal(FRAME_EFFECT_44BFB0_V25_END_VA, 0x0044c06d);
  assert.equal(FRAME_EFFECT_44BFB0_V25_NEXT_VA, 0x0044c070);
  assert.equal(FRAME_EFFECT_44BFB0_V25_RET_BYTES, 4);
  assert.equal(FRAME_EFFECT_44BFB0_V25_INSN_COUNT, 75);
  assert.equal(FRAME_EFFECT_44BFB0_V25_BYTE_LEN, 192);
  assert.equal(FRAME_EFFECT_44BFB0_V25_CALL_INSNS, 2);
  assert.equal(FRAME_EFFECT_44BFB0_V25_DIRECT_CALLERS, 106);
  assert.deepEqual(FRAME_EFFECT_44BFB0_V25_DWORD_HITS, []);
  assert.equal(FRAME_EFFECT_44BFB0_V25_CALLEE_VA, 0x00771550);
  assert.equal(FRAME_EFFECT_44BFB0_V25_LEVEL_GLOBAL_VA, 0x00c7169c); /* g_Level */
  assert.equal(FRAME_EFFECT_44BFB0_V25_ARRAY_LO_OFF, 0x2a410);
  assert.equal(FRAME_EFFECT_44BFB0_V25_ARRAY_HI_OFF, 0x2a414);
  assert.equal(FRAME_EFFECT_44BFB0_V25_TRINKET_MASK, 0x7fff);
  assert.equal(FRAME_EFFECT_44BFB0_V25_FLAG_OFF, 0xb8);
  assert.equal(FRAME_EFFECT_44BFB0_V25_HAS_BIT, 0x80000000);
  assert.equal(FRAME_EFFECT_44BFB0_V25_LIST_HEAD_OFF, 0x0);
  assert.equal(FRAME_EFFECT_44BFB0_V25_LIST_TAIL_OFF, 0x4);
  assert.equal(FRAME_EFFECT_44BFB0_V25_ACTIVE_OFF, 0x2c);
  assert.equal(FRAME_EFFECT_44BFB0_V25_ALT_OFF, 0x1e6c);
  assert.match(HDR, /ABI v25\. Pure decision seams of FUN_0044bfb0/);
  assert.match(SRC, /0x0044bfd6 and ecx,0x7fff/);
  assert.match(SRC, /0x0044bfdf cmp ecx,eax/);
  assert.match(SRC, /0x0044bff0 and eax,0x80000000/);
  assert.match(SRC, /0x0044c022 test al,al/);
  assert.match(SRC, /0x0044c026 cmp byte \[ebp\+0xb\],al/);
  assert.match(SRC, /0x0044c04e test edi,edi/);
});

