test("v26 laws: grid_index arithmetic (wrap) + gate edges", () => {
  /* M9 grid_index imul+lea 32-bit wrap. */
  assert.equal(W.gridIndex7ee7e0(0, 0, 13) >>> 0, 0);
  assert.equal(W.gridIndex7ee7e0(2, 3, 13) >>> 0, 41);
  assert.equal(W.gridIndex7ee7e0(0x100, 0x100, 0x100) >>> 0, 0x10100);
  assert.equal(W.gridIndex7ee7e0(0xffffffff, 1, 1) >>> 0, 0);
  assert.equal(
    W.gridIndex7ee7e0(0x12345678, 3, 0x55667788) >>> 0,
    frameEffect7ee7e0GridIndex(0x12345678, 3, 0x55667788),
  );
  /* index_oob_log SIGNED vs signed width*height; product wraps. */
  assert.equal(W.indexOobLog7ee7e0(0, 13, 13), 0);
  assert.equal(W.indexOobLog7ee7e0(168, 13, 13), 0);
  assert.equal(W.indexOobLog7ee7e0(169, 13, 13), 1);
  assert.equal(W.indexOobLog7ee7e0(0xffffffff, 1, 1), 1); /* -1 signed */
  assert.equal(W.indexOobLog7ee7e0(0x80000000, 1, 1), 1); /* negative */
  /* 0x10000*0x10000 wraps the product to 0: 0 >= 0 signed -> log. */
  assert.equal(W.indexOobLog7ee7e0(0, 0x10000, 0x10000), 1);
  /* cell_occupied FULL dword. */
  assert.equal(W.cellOccupied7ee7e0(0), 0);
  assert.equal(W.cellOccupied7ee7e0(1), 1);
  assert.equal(W.cellOccupied7ee7e0(0x100), 1);
  assert.equal(W.cellOccupied7ee7e0(0xffffffff), 1);
  /* mode_open FULL dword 0x10 — no low-byte leak. */
  assert.equal(W.modeOpen7ee7e0(0x10), 1);
  assert.equal(W.modeOpen7ee7e0(0x110), 0);
  assert.equal(W.modeOpen7ee7e0(0xf), 0);
  /* type_default_arm {2,3}. */
  assert.equal(W.typeDefaultArm7ee7e0(2), 1);
  assert.equal(W.typeDefaultArm7ee7e0(3), 1);
  assert.equal(W.typeDefaultArm7ee7e0(4), 0);
  assert.equal(W.typeDefaultArm7ee7e0(0x102), 0);
  assert.equal(W.typeDefaultArm7ee7e0(0xffffffff), 0);
  /* arm_a_selected: y==0 && x==2 exact. */
  assert.equal(W.armASelected7ee7e0(2, 0), 1);
  assert.equal(W.armASelected7ee7e0(2, 1), 0);
  assert.equal(W.armASelected7ee7e0(3, 0), 0);
  assert.equal(W.armASelected7ee7e0(0x80000002, 0), 0);
  assert.equal(W.armASelected7ee7e0(2, 0x80000000), 0);
  /* arm_b_selected: y in {3,4} && x==0xe && type_c==1 exact. */
  assert.equal(W.armBSelected7ee7e0(0xe, 3, 1), 1);
  assert.equal(W.armBSelected7ee7e0(0xe, 4, 1), 1);
  assert.equal(W.armBSelected7ee7e0(0xe, 2, 1), 0);
  assert.equal(W.armBSelected7ee7e0(0xe, 5, 1), 0);
  assert.equal(W.armBSelected7ee7e0(0xd, 3, 1), 0);
  assert.equal(W.armBSelected7ee7e0(0x10e, 3, 1), 0);
  assert.equal(W.armBSelected7ee7e0(0xe, 3, 0), 0);
  assert.equal(W.armBSelected7ee7e0(0xe, 3, 2), 0);
  assert.equal(W.armBSelected7ee7e0(0xe, 0x80000003, 1), 0);
});

test("v26 laws: bounds logs, arm skips and crash seams", () => {
  /* arm_ab_bounds_log SIGNED vs 0x1c0. */
  assert.equal(W.armAbBoundsLog7ee7e0(0), 0);
  assert.equal(W.armAbBoundsLog7ee7e0(0x1bf), 0);
  assert.equal(W.armAbBoundsLog7ee7e0(0x1c0), 1);
  assert.equal(W.armAbBoundsLog7ee7e0(0x7fffffff), 1);
  assert.equal(W.armAbBoundsLog7ee7e0(0x80000000), 1);
  assert.equal(W.armAbBoundsLog7ee7e0(0xffffffff), 1);
  /* arm_a_skip: UNSIGNED idx > 0x1bf OR SIGNED marker > 0x384. */
  assert.equal(W.armASkip7ee7e0(0x1bf, 0), 0);
  assert.equal(W.armASkip7ee7e0(0x1c0, 0), 1);
  assert.equal(W.armASkip7ee7e0(0xffffffff, 0), 1); /* unsigned cap, not signed */
  assert.equal(W.armASkip7ee7e0(0, 0x384), 0);
  assert.equal(W.armASkip7ee7e0(0, 0x385), 1);
  assert.equal(W.armASkip7ee7e0(0, -1), 0);
  assert.equal(W.armASkip7ee7e0(0, 0x80000000), 0); /* marker SIGNED: negative */
  /* arm_b_crash_oob — the SIGNED re-check (extensionally equal to arm
     A's unsigned cap; the signed/unsigned instruction choice is the
     machine difference, pinned in notes). */
  assert.equal(W.armBCrashOob7ee7e0(0x1bf), 0);
  assert.equal(W.armBCrashOob7ee7e0(0x1c0), 1);
  assert.equal(W.armBCrashOob7ee7e0(0x80000000), 1);
  assert.equal(W.armBCrashOob7ee7e0(0xffffffff), 1);
  /* arm_b_crash_marker — SIGNED marker > 0x384. */
  assert.equal(W.armBCrashMarker7ee7e0(0x384), 0);
  assert.equal(W.armBCrashMarker7ee7e0(0x385), 1);
  assert.equal(W.armBCrashMarker7ee7e0(0x80000000), 0);
  assert.equal(W.armBCrashMarker7ee7e0(-1), 0);
});

test("v26 laws: randomized differential wasm === JS oracle (200 draws)", () => {
  const rnd = lcg32(0x7ee7e0);
  for (let i = 0; i < 200; i += 1) {
    const a = rnd(), b = rnd(), c = rnd(), d = rnd();
    assert.equal(
      W.gridIndex7ee7e0(a >>> 0, b >>> 0, c >>> 0) >>> 0,
      frameEffect7ee7e0GridIndex(a >>> 0, b >>> 0, c >>> 0),
      `grid_index ${i}`,
    );
    assert.equal(
      W.indexOobLog7ee7e0(a >>> 0, b >>> 0, c >>> 0),
      frameEffect7ee7e0IndexOobLog(a >>> 0, b >>> 0, c >>> 0),
      `index_oob_log ${i}`,
    );
    assert.equal(W.cellOccupied7ee7e0(d >>> 0), frameEffect7ee7e0CellOccupied(d >>> 0), `cell_occupied ${i}`);
    assert.equal(W.modeOpen7ee7e0(d >>> 0), frameEffect7ee7e0ModeOpen(d >>> 0), `mode_open ${i}`);
    assert.equal(W.typeDefaultArm7ee7e0(d >>> 0), frameEffect7ee7e0TypeDefaultArm(d >>> 0), `type_default_arm ${i}`);
    assert.equal(W.armASelected7ee7e0(a >>> 0, b >>> 0), frameEffect7ee7e0ArmASelected(a >>> 0, b >>> 0), `arm_a ${i}`);
    assert.equal(W.armBSelected7ee7e0(a >>> 0, b >>> 0, c >>> 0), frameEffect7ee7e0ArmBSelected(a >>> 0, b >>> 0, c >>> 0), `arm_b ${i}`);
    assert.equal(W.armAbBoundsLog7ee7e0(a >>> 0), frameEffect7ee7e0ArmABBoundsLog(a >>> 0), `bounds_log ${i}`);
    assert.equal(W.armASkip7ee7e0(a >>> 0, b | 0), frameEffect7ee7e0ArmASkip(a >>> 0, b | 0), `arm_a_skip ${i}`);
    assert.equal(W.armBCrashOob7ee7e0(a >>> 0), frameEffect7ee7e0ArmBCrashOob(a >>> 0), `crash_oob ${i}`);
    assert.equal(W.armBCrashMarker7ee7e0(b | 0), frameEffect7ee7e0ArmBCrashMarker(b | 0), `crash_marker ${i}`);
  }
});

