test("v26 mutants: discriminators + ABI + census + source pins", () => {
  /* M1 index_oob_log signed product wrap: 0 >= (0x10000*0x10000 = 0). */
  assert.equal(W.indexOobLog7ee7e0(0, 0x10000, 0x10000), 1);
  /* M2 arm_a_skip unsigned cap: 0xffffffff trips (a signed mutant -> 0). */
  assert.equal(W.armASkip7ee7e0(0xffffffff, 0), 1);
  /* M3 marker signed: 0x80000000 is negative, not above 0x384. */
  assert.equal(W.armASkip7ee7e0(0, 0x80000000), 0);
  assert.equal(W.armBCrashMarker7ee7e0(0x80000000), 0);
  /* M4 mode_open/type/cell FULL dword — no low-byte leak. */
  assert.equal(W.modeOpen7ee7e0(0x110), 0);
  assert.equal(W.typeDefaultArm7ee7e0(0x102), 0);
  assert.equal(W.cellOccupied7ee7e0(0x100), 1);
  /* M5 arm selectors exact equality, no &/low-byte confusion. */
  assert.equal(W.armASelected7ee7e0(0x80000002, 0), 0);
  assert.equal(W.armBSelected7ee7e0(0x10e, 3, 1), 0);
  /* M6 grid_index wrap. */
  assert.equal(W.gridIndex7ee7e0(0xffffffff, 1, 1) >>> 0, 0);
  /* M7 ABI pin: 27 (the v26 bump was superseded — v27 laws landed). */
  assert.equal(W.abi(), 51);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_PURE_HELPERS_ABI_VERSION = 51/);
  assert.equal(FRAME_EFFECT_PURE_ABI_VERSION, 51);
  /* M8 v26 census pins. */
  assert.equal(FRAME_EFFECT_7EE7E0_V26_VA, 0x007ee7e0);
  assert.equal(FRAME_EFFECT_7EE7E0_V26_END_VA, 0x007eea8f);
  assert.equal(FRAME_EFFECT_7EE7E0_V26_NEXT_VA, 0x007eea90);
  assert.equal(FRAME_EFFECT_7EE7E0_V26_RET_BYTES, 8);
  assert.equal(FRAME_EFFECT_7EE7E0_V26_INSN_COUNT, 197);
  assert.equal(FRAME_EFFECT_7EE7E0_V26_BYTE_LEN, 687);
  assert.equal(FRAME_EFFECT_7EE7E0_V26_CALL_INSNS, 19);
  assert.equal(FRAME_EFFECT_7EE7E0_V26_DIRECT_CALLS, 15);
  assert.equal(FRAME_EFFECT_7EE7E0_V26_INDIRECT_CALLS, 4);
  assert.equal(FRAME_EFFECT_7EE7E0_V26_DATA_STORES, 30);
  assert.equal(FRAME_EFFECT_7EE7E0_V26_DIRECT_CALLERS.length, 24);
  assert.deepEqual(FRAME_EFFECT_7EE7E0_V26_DWORD_HITS, []);
  assert.equal(FRAME_EFFECT_7EE7E0_V26_TYPE_OFF, 0x10); /* [cfg+0x10], not +0x48 */
  assert.equal(FRAME_EFFECT_7EE7E0_V26_CELL_OFF, 0x24);
  assert.equal(FRAME_EFFECT_7EE7E0_V26_MARKER_OFF, 0x76c);
  assert.equal(FRAME_EFFECT_7EE7E0_V26_CAP_A_UNSIGNED, 0x1bf);
  assert.equal(FRAME_EFFECT_7EE7E0_V26_CAP, 0x1c0);
  assert.equal(FRAME_EFFECT_7EE7E0_V26_MARKER_MAX, 0x384);
  assert.equal(FRAME_EFFECT_7EE7E0_V26_VTABLE_A, 0x00b686c0);
  assert.equal(FRAME_EFFECT_7EE7E0_V26_VTABLE_B, 0x00b7d99c);
  assert.equal(FRAME_EFFECT_7EE7E0_V26_VTABLE_DEFAULT, 0x00b68670);
  assert.equal(FRAME_EFFECT_7EE7E0_V26_KIND_A, 1);
  assert.equal(FRAME_EFFECT_7EE7E0_V26_KIND_B, 0x13);
  assert.equal(FRAME_EFFECT_7EE7E0_V26_KIND_DEFAULT, 0xf);
  assert.equal(FRAME_EFFECT_7EE7E0_V26_ORDER_A, 0xa);
  assert.equal(FRAME_EFFECT_7EE7E0_V26_ALLOC_SIZE, 0x154);
  assert.equal(FRAME_EFFECT_7EE7E0_V26_LOG_STR_BOUNDS_VA, 0x00b6c190);
  assert.equal(FRAME_EFFECT_7EE7E0_V26_LOG_STR_ARM_VA, 0x00b6c138);
  /* M9 source pins — the v26 cpp block cites the machine. */
  assert.match(HDR, /ABI v26\. Pure decision seams of FUN_007ee7e0/);
  assert.match(HDR, /frame-effect-v26-7ee7e0/);
  assert.match(HDR, /0x81fb20\/81ecc0 \[cfg\+0x48\] family TYPE_OFF/);
  assert.match(HDR, /reproduced, not repaired/);
  assert.match(SRC, /0x007ee813 imul eax,esi/);
  assert.match(SRC, /0x007ee819 test edi,edi; js LOG/);
  assert.match(SRC, /0x007ee839 cmp \[ebx\+edi\*4\+0x24\],0/);
  assert.match(SRC, /0x007ee844 cmp \[ebx\+8\],0x10/);
  assert.match(SRC, /0x007ee84e mov eax,\[ebx\+4\]/);
  assert.match(SRC, /0x007ee869 test esi,esi/);
  assert.match(SRC, /0x007ee935 cmp esi,3/);
  assert.match(SRC, /0x007ee882 \(arm A\)/);
  assert.match(SRC, /0x007ee89d cmp edi,0x1bf; ja/);
  assert.match(SRC, /0x007ee979 test edi,edi; js 0x7eea15/);
  assert.match(SRC, /0x007ee98d cmp \[ebx\+edi\*4\+0x76c\],0x384/);
  /* M10 the body has ZERO byte gates — no `cmp byte ptr` instruction
     anywhere in the v26 cpp block (the family low-byte rule therefore has
     no new surface; the decl scan above already enforces no uint8_t). */
  const v26SrcBlock = SRC.slice(SRC.indexOf("ABI v26 — FUN_007ee7e0"),
                                SRC.indexOf("ABI v27 — FUN_007eece0"));
  assert.doesNotMatch(v26SrcBlock, /cmp\s+byte\s+ptr/);
});

