/* ABI v27: FUN_007eece0 Room::GetRoomConfigStage + FUN_007eed10       */
/* captured-value filter (siblings resumed after the v26 0x7ee7e0      */
/* landing); 0x7eeeb0 SEH effect-copy body stays HOST (evidence only)  */
