/* ------------------------------------------------------------------ */
/* ABI v28: FUN_008206e0 stage-id selector — PURE-OPEN (the v24-recorded
 * next VA after the 0x8204b0 VoidDoor landing, unassessed through v27;
 * 16 insns / 49 B / 0 resyncs / 0 calls / 2 plain rets / 0 stores /
 * 1 caller 0x7eb4ce / 0 raw hits / ZHL EMPTY / thiscall, ZERO stack
 * args). Evidence: section-notes/frame-effect-v28-8206e0/
 * (census-8206e0-body.json). */

/* v28 scratch sits above V19 (0x1b0000). 0x1c0000+ is fresh. */
const V28_SCRATCH = {
  plan: 0x1c0000, /* 36 B — IsaacFrameEffect8206e0Plan (9 fields) */
};

function readPlan8206e0(memory, base) {
  return {
    derefGame: i32At(memory, base + 0),
    derefChapter: i32At(memory, base + 4),
    chapter41: i32At(memory, base + 8),
    descDeref: i32At(memory, base + 12),
    flagDeref: i32At(memory, base + 16),
    descBit6: i32At(memory, base + 20),
    result: u32At(memory, base + 24),
    hostCalls: i32At(memory, base + 28),
    pureComplete: i32At(memory, base + 32),
  };
}

test("v28 constants agree between header and model", () => {
  const pairs = [
    [FRAME_EFFECT_8206E0_VA, 0x008206e0],
    [FRAME_EFFECT_8206E0_END_VA, 0x00820711],
    [FRAME_EFFECT_8206E0_NEXT_VA, 0x00820720],
    [FRAME_EFFECT_8206E0_RET_BYTES, 0],
    [FRAME_EFFECT_8206E0_INSN_COUNT, 16],
    [FRAME_EFFECT_8206E0_BYTE_LEN, 49],
    [FRAME_EFFECT_8206E0_CALL_INSNS, 0],
    [FRAME_EFFECT_8206E0_DIRECT_CALLERS, 1],
    [FRAME_EFFECT_8206E0_RAW_DWORD_HITS, 0],
    [FRAME_EFFECT_8206E0_CALLSITE_VA, 0x007eb4ce],
    [FRAME_EFFECT_8206E0_GAME_GLOBAL_VA, 0x00c71678],
    [FRAME_EFFECT_8206E0_CHAPTER_OFF, 0x4],
    [FRAME_EFFECT_8206E0_DESC_OFF, 0x4],
    [FRAME_EFFECT_8206E0_DESC_FLAG_OFF, 0x44],
    [FRAME_EFFECT_8206E0_FLAG_BIT, 6],
    [FRAME_EFFECT_8206E0_RESULT_CHAPTER, 0x29],
    [FRAME_EFFECT_8206E0_RESULT_BIT6, 0x1a],
    [FRAME_EFFECT_8206E0_RESULT_CLEAR, 9],
    [FRAME_EFFECT_8206E0_RET_A_VA, 0x0082070a],
    [FRAME_EFFECT_8206E0_RET_B_VA, 0x00820710],
  ];
  for (const [model, expected] of pairs) {
    assert.equal(model, expected);
  }
  /* header enum pins */
  assert.match(HDR, /ISAAC_FRAME_EFFECT_8206E0_VA = 0x008206e0u/);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_8206E0_END_VA = 0x00820711u/);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_8206E0_RESULT_CHAPTER = 0x29/);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_8206E0_FLAG_BIT = 6/);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_8206E0_RET_B_VA = 0x00820710u/);
});

