test("v28 laws: chapter_41_gate — FULL-dword chapter 4||5", () => {
  const cases = [
    [0, 0], [3, 0], [4, 1], [5, 1], [6, 0],
    [0x100, 0], [0xffffffff, 0], [0x80000000, 0],
    [0x7fffffff, 0], [-1, 0],
  ];
  for (const [c, exp] of cases) {
    assert.equal(W.chapter41Gate8206e0(c >>> 0), exp, `chapter ${c}`);
    assert.equal(W.chapter41Gate8206e0(c >>> 0),
                 frameEffect8206e0Chapter41Gate(c >>> 0), `js chapter ${c}`);
  }
  /* FULL-dword discriminators: 0x100 / 0x80000000 are NOT 4 or 5 (a
     low-byte mutant would misfire). Equality — signedness cannot matter. */
  assert.equal(W.chapter41Gate8206e0(0x100 >>> 0), 0);
  assert.equal(W.chapter41Gate8206e0(0x80000000 >>> 0), 0);
  assert.equal(W.chapter41Gate8206e0(0), 0);
  assert.equal(W.chapter41Gate8206e0(4), 1);
  assert.equal(W.chapter41Gate8206e0(5), 1);
});

test("v28 laws: desc_bit6 — LOGICAL shr 6 + test al,1", () => {
  const cases = [
    [0x00000000, 0], [0x00000040, 1], /* exactly bit 6 */
    [0x00000020, 0], [0x00000080, 0], /* bits 5 / 7 are not bit 6 */
    [0x0000003f, 0], [0xffffffc0, 1], [0xffffffff, 1],
    [0x80000040, 1], [0x80000000, 0], /* LOGICAL: bit 31 must NOT fold */
    [0x10000040, 1], [0x10000000, 0],
    [0x00000140, 1],
  ];
  for (const [f, exp] of cases) {
    assert.equal(W.descBit68206e0(f >>> 0), exp, `flags ${f}`);
    assert.equal(W.descBit68206e0(f >>> 0),
                 frameEffect8206e0DescBit6(f >>> 0), `js flags ${f}`);
  }
  /* LOGICAL-shift discriminator: 0x80000000 keeps bit 31 out of bit 0
     (an arithmetic-shift mutant folds it in -> 1). */
  assert.equal(W.descBit68206e0(0x80000000 >>> 0), 0);
});

test("v28 laws: result — chapter arm vs bit-6 arm vs clear", () => {
  /* chapter 4/5 -> 0x29 regardless of the flags dword */
  assert.equal(W.result8206e0(4, 0), 0x29);
  assert.equal(W.result8206e0(5, 0xffffffff), 0x29);
  assert.equal(W.result8206e0(4, 0x40), 0x29);
  /* else bit6 -> 0x1a : 9 */
  assert.equal(W.result8206e0(0, 0), 9);
  assert.equal(W.result8206e0(1, 0x40), 0x1a);
  assert.equal(W.result8206e0(0x100, 0xffffffc0) >>> 0, 0x1a);
  assert.equal(W.result8206e0(0x100, 0x80000000) >>> 0, 9);
  assert.equal(W.result8206e0(0xffffffff, 0) >>> 0, 9);
  assert.equal(W.result8206e0(0x80000000, 0x40) >>> 0, 0x1a);
  /* always matches the JS oracle */
  for (const [c, f] of [[0, 0], [4, 0], [5, 0x40], [0x100, 0x80], [0, 0x40]]) {
    assert.equal(W.result8206e0(c >>> 0, f >>> 0) >>> 0,
                 frameEffect8206e0Result(c >>> 0, f >>> 0) >>> 0,
                 `result ${c},${f}`);
  }
});

test("v28 laws: entry_plan — machine-truth deref gating", () => {
  function call(chapter, flags) {
    W.entryPlan8206e0(V28_SCRATCH.plan, chapter >>> 0, flags >>> 0);
    return readPlan8206e0(W.memory, V28_SCRATCH.plan);
  }
  /* chapter arm: derefs of game+chapter unconditional, desc/flags gated
     OFF (the machine jumps to 0x82070b before reading [ecx+4]). */
  let p = call(4, 0x12345678);
  assert.equal(p.derefGame, 1);
  assert.equal(p.derefChapter, 1);
  assert.equal(p.chapter41, 1);
  assert.equal(p.descDeref, 0);
  assert.equal(p.flagDeref, 0);
  assert.equal(p.descBit6, 1); /* pure bit law, still computed */
  assert.equal(p.result, 0x29);
  assert.equal(p.hostCalls, 0);
  assert.equal(p.pureComplete, 1);
  /* miss arm: desc + flags deref, bit select, cmovne value. */
  p = call(0, 0x40);
  assert.equal(p.chapter41, 0);
  assert.equal(p.descDeref, 1);
  assert.equal(p.flagDeref, 1);
  assert.equal(p.descBit6, 1);
  assert.equal(p.result, 0x1a);
  p = call(0, 0);
  assert.equal(p.descBit6, 0);
  assert.equal(p.result, 9);
  p = call(0x100, 0x80000000);
  assert.equal(p.chapter41, 0);
  assert.equal(p.descBit6, 0);
  assert.equal(p.result, 9);
  /* null-out skip. */
  W.entryPlan8206e0(0, 0, 0);
  /* static asserts in the cpp cover the 36-B layout (9 x i32). */
  assert.match(SRC, /sizeof\(IsaacFrameEffect8206e0Plan\) == 36/);
});

test("v28 laws: randomized differential wasm === JS oracle (96 draws)", () => {
  const rnd = lcg32(0x8206e0);
  for (let i = 0; i < 96; i += 1) {
    const c = rnd(), f = rnd();
    assert.equal(W.chapter41Gate8206e0(c >>> 0),
                 frameEffect8206e0Chapter41Gate(c >>> 0), `gate ${i}`);
    assert.equal(W.descBit68206e0(f >>> 0),
                 frameEffect8206e0DescBit6(f >>> 0), `bit6 ${i}`);
    assert.equal(W.result8206e0(c >>> 0, f >>> 0) >>> 0,
                 frameEffect8206e0Result(c >>> 0, f >>> 0) >>> 0,
                 `result ${i}`);
  }
});

test("v28 mutants: discriminators + ABI + census + source pins", () => {
  /* M1 chapter gate: 5 must trip (a `== 4`-only mutant dies on 5), 0x100
     must NOT (a low-byte `& 0xff == 4` mutant dies). */
  assert.equal(W.chapter41Gate8206e0(5), 1);
  assert.equal(W.chapter41Gate8206e0(0x100 >>> 0), 0);
  assert.equal(W.chapter41Gate8206e0(4), 1);
  assert.notEqual(W.chapter41Gate8206e0(5), 0);
  assert.notEqual(W.chapter41Gate8206e0(0x100 >>> 0), 1);
  /* M2 desc_bit6: bit 6 exactly — 0x20 / 0x80 / 0x80000000 must stay 0
     (mask / shift-mount mutants die); 0x40 and 0xffffffc0 trip. */
  assert.equal(W.descBit68206e0(0x20 >>> 0), 0);
  assert.equal(W.descBit68206e0(0x80 >>> 0), 0);
  assert.equal(W.descBit68206e0(0x80000000 >>> 0), 0);
  assert.equal(W.descBit68206e0(0x40 >>> 0), 1);
  assert.equal(W.descBit68206e0(0xffffffc0 >>> 0), 1);
  assert.notEqual(W.descBit68206e0(0x20 >>> 0), 1);
  /* M3 LOGICAL shift: 0x80000000 is 0, not 1 (an `sar` mutant folds the
     sign bit into bit 0). */
  assert.equal(W.descBit68206e0(0x80000000 >>> 0), 0);
  assert.notEqual(W.descBit68206e0(0x80000000 >>> 0), 1);
  /* M4 result cmovne arm: bit-6 set is 0x1a, clear is 9 (an inverted
     cmovne mutants swaps; a clear->0x29 mutant dies on chapter-0). */
  assert.equal(W.result8206e0(0, 0x40), 0x1a);
  assert.equal(W.result8206e0(0, 0), 9);
  assert.equal(W.result8206e0(4, 0), 0x29);
  assert.notEqual(W.result8206e0(0, 0x40), 9);
  assert.notEqual(W.result8206e0(0, 0), 0x1a);
  assert.notEqual(W.result8206e0(4, 0), 9);
  /* M5 entry_plan deref gating: chapter arm must NOT deref desc/flags
     (an unconditional-deref mutant writes 1 into desc_deref). */
  W.entryPlan8206e0(V28_SCRATCH.plan, 5, 0x40);
  assert.equal(readPlan8206e0(W.memory, V28_SCRATCH.plan).descDeref, 0);
  assert.notEqual(readPlan8206e0(W.memory, V28_SCRATCH.plan).descDeref, 1);
  assert.equal(readPlan8206e0(W.memory, V28_SCRATCH.plan).result, 0x29);
  /* M6 nullable out: entry_plan with out == 0 must not trap. */
  W.entryPlan8206e0(0, 0, 0);
  /* M7 ABI pin: 28 (atomic bump fired — v28 laws landed). */
  assert.equal(W.abi(), 51);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_PURE_HELPERS_ABI_VERSION = 51/);
  assert.equal(FRAME_EFFECT_PURE_ABI_VERSION, 51);
  /* M8 v28 census pins. */
  assert.equal(FRAME_EFFECT_8206E0_VA, 0x008206e0);
  assert.equal(FRAME_EFFECT_8206E0_END_VA, 0x00820711);
  assert.equal(FRAME_EFFECT_8206E0_NEXT_VA, 0x00820720);
  assert.equal(FRAME_EFFECT_8206E0_RET_BYTES, 0);
  assert.equal(FRAME_EFFECT_8206E0_INSN_COUNT, 16);
  assert.equal(FRAME_EFFECT_8206E0_BYTE_LEN, 49);
  assert.equal(FRAME_EFFECT_8206E0_CALL_INSNS, 0);
  assert.equal(FRAME_EFFECT_8206E0_DIRECT_CALLERS, 1);
  assert.equal(FRAME_EFFECT_8206E0_RAW_DWORD_HITS, 0);
  assert.equal(FRAME_EFFECT_8206E0_CALLSITE_VA, 0x007eb4ce);
  assert.equal(FRAME_EFFECT_8206E0_GAME_GLOBAL_VA, 0x00c71678);
  assert.equal(FRAME_EFFECT_8206E0_CHAPTER_OFF, 0x4);
  assert.equal(FRAME_EFFECT_8206E0_DESC_OFF, 0x4);
  assert.equal(FRAME_EFFECT_8206E0_DESC_FLAG_OFF, 0x44);
  assert.equal(FRAME_EFFECT_8206E0_FLAG_BIT, 6);
  assert.equal(FRAME_EFFECT_8206E0_RESULT_CHAPTER, 0x29);
  assert.equal(FRAME_EFFECT_8206E0_RESULT_BIT6, 0x1a);
  assert.equal(FRAME_EFFECT_8206E0_RESULT_CLEAR, 9);
  assert.equal(FRAME_EFFECT_8206E0_RET_A_VA, 0x0082070a);
  assert.equal(FRAME_EFFECT_8206E0_RET_B_VA, 0x00820710);
  /* M9 source pins — the v28 cpp block cites the machine. */
  assert.match(HDR, /ABI v28\. Pure laws of FUN_008206e0/);
  assert.match(HDR, /frame-effect-v28-8206e0/);
  assert.match(HDR, /the stage-id selector recorded at v24/);
  assert.match(HDR, /isaac_frame_effect_8206e0_chapter_41_gate/);
  assert.match(SRC, /0x008206e8 cmp eax,4 ; je 0x82070b/);
  assert.match(SRC, /0x008206ed cmp eax,5 ; je 0x82070b/);
  assert.match(SRC, /0x008206fd shr eax,6 \(LOGICAL\)/);
  assert.match(SRC, /0x00820700 test al,1/);
  assert.match(SRC, /0x00820707 cmovne eax,ecx/);
  assert.match(SRC, /0x0082070b mov eax,0x29/);
  assert.match(HDR, /mov ecx,ebx` \(thiscall\) then/);
  /* M10 the v28 cpp block carries the explicit bit mask (uint32_t +
     `& 1u`) and no uint8_t declarator anywhere in the block. */
  const v28SrcBlock = SRC.slice(SRC.indexOf("ABI v28 — FUN_008206e0"));
  const v28SrcEnd = v28SrcBlock.indexOf("ABI v29 — FUN_00820720");
  const srcBlock = v28SrcBlock.slice(0, v28SrcEnd);
  assert.match(srcBlock, /&\s*1u/);
  assert.doesNotMatch(srcBlock, /uint8_t/);
  /* no `cmp byte` anywhere in the v28 cpp block (the body's only
     byte-width op is `test al,1` on a register). */
  assert.doesNotMatch(srcBlock, /cmp\s+byte\s+ptr/);
});
/* ------------------------------------------------------------------ */
/* ABI v29: FUN_00820720 Room::GetBossVictoryJingle — PURE-OPEN (the
 * v28-recorded sibling NEXT_VA; int3 pad 0x82079c..0x82079f, next fn
 * 0x8207a0; 46 insns / 124 B / 0 resyncs / 1 call (0x74bae0, HOST) /
 * 0 indirect / 4 plain rets / 0 stores / 2 callers 0x7fee72 +
 * 0x7ff7fe / 0 raw hits / thiscall, ecx = Room, ZERO stack args).
 * ZHL PROMOTED (comments only, family v7 rule): exact 13-byte
 * `56 8b 35 ?? ?? ?? ?? 57 8b f9 83 3e 0d` =
 * __thiscall uint32_t Room::GetBossVictoryJingle() (Room.zhl); both
 * callers pass a Room-shaped ecx with ZERO pushed args and consume the
 * uint32_t result (caller-1 full-dword music-id, caller-2 bool).
 * Evidence: section-notes/frame-effect-v29-820720/
 * (census-820720-body.json). */

/* v29 scratch sits above v28 (0x1c0000). 0x1d0000+ is fresh. */
const V29_SCRATCH = {
  plan: 0x1d0000, /* 60 B — IsaacFrameEffect820720Plan (15 fields) */
};

function readPlan820720(memory, base) {
  return {
    derefGame: i32At(memory, base + 0),
    derefChapter: i32At(memory, base + 4),
    zeroGate: i32At(memory, base + 8),
    host74bae0Fires: i32At(memory, base + 12),
    deref18304: i32At(memory, base + 16),
    hostZero: i32At(memory, base + 20),
    derefRoom: i32At(memory, base + 24),
    room5c: i32At(memory, base + 28),
    chapter42: i32At(memory, base + 32),
    descDeref: i32At(memory, base + 36),
    flagDeref: i32At(memory, base + 40),
    descBit6: i32At(memory, base + 44),
    result: u32At(memory, base + 48),
    hostCalls: i32At(memory, base + 52),
    pureComplete: i32At(memory, base + 56),
  };
}

