test("no uint8_t scalar parameters in the v29 declaration block", () => {
  const v29Block = HDR.slice(HDR.indexOf("/* ABI v29. Pure laws"));
  const v29End = v29Block.indexOf("/* ABI v30.");
  const block = v29Block.slice(0, v29End);
  const declLines = block
    .split("\n")
    .filter((ln) =>
      /^(void|uint32_t|int32_t)\s+isaac_frame_effect_820720_/.test(ln.trim()),
    );
  assert.ok(declLines.length >= 7, `expected 7 v29 declarations, got ${declLines.length}`);
  assert.doesNotMatch(block, /uint8_t/);
  /* the byte-gate law carries the explicit mask, never a uint8_t param */
  assert.match(block, /room_byte_7228/);
  /* every declared export is wired into EXPORTS and the W object */
  for (const ln of declLines) {
    const shortName = ln.match(/isaac_frame_effect_820720_([a-z0-9_]+)/)[1];
    const name = `isaac_frame_effect_820720_${shortName}`;
    assert.ok(EXPORTS.includes(name), `EXPORTS missing ${name}`);
    const wKey = shortName.replace(/_([a-z0-9])/g, (_, ch) => ch.toUpperCase());
    const key = `${wKey}820720`;
    assert.equal(typeof W[key], "function", `W missing ${name}`);
  }
});

test("v29 laws: zero_gate & host_zero_gate — the two ret-0 arms", () => {
  /* zero_gate: [g_Game+0] == 0xd && chapter == 1, FULL dword equality. */
  const g0cases = [
    [0, 1, 0], [13, 0, 0], [13, 1, 1], [12, 1, 0], [14, 1, 0],
    [0x100, 1, 0], [0x80000000, 1, 0], /* FULL dword: not 0xd */
    [0x10d, 1, 0], [13, 0x101, 0], /* low-byte lookalikes must NOT trip */
    [0xffffffff, 1, 0], [13, 0xffffffff, 0], [13, 0x80000000, 0],
  ];
  for (const [g0, ch, exp] of g0cases) {
    assert.equal(W.zeroGate820720(g0 >>> 0, ch >>> 0), exp, `zero ${g0},${ch}`);
    assert.equal(W.zeroGate820720(g0 >>> 0, ch >>> 0),
                 frameEffect820720ZeroGate(g0 >>> 0, ch >>> 0), `js zero ${g0},${ch}`);
  }
  /* host_zero_gate: host 0x74bae0 result == 4 && [g_Game+0x18304] == -10. */
  const hzCases = [
    [4, -10, 1], [4, 10, 0], [3, -10, 0], [0, 0, 0],
    [4, (0xfffffff6 | 0), 1], /* 0xfffffff6 == -10 by value */
    [0x104, -10, 0], /* FULL dword: low-byte 4 lookalike */
    [4, 0x10000000, 0], [0x80000000, -10, 0],
    [4, -11, 0], [4, -9, 0], [4, 0xfffffff7, 0],
  ];
  for (const [h, g, exp] of hzCases) {
    assert.equal(W.hostZeroGate820720(h | 0, g | 0), exp, `hostZero ${h},${g}`);
    assert.equal(W.hostZeroGate820720(h | 0, g | 0),
                 frameEffect820720HostZeroGate(h | 0, g | 0), `js hostZero ${h},${g}`);
  }
});

test("v29 laws: room_5c gate — FULL-dword type + byte 0x7228 mask", () => {
  /* type == 6 is FULL dword; the byte flag is masked & 0xff. */
  const cases = [
    [6, 0, 1], [0, 1, 1], [0, 0, 0], [6, 0xff, 1], [-1, 0, 0],
    [0x106, 0, 0], /* FULL dword: low-byte 6 lookalike */
    [0x100, 1, 1], /* high type bits don't matter; the byte flag trips */
    [6, 0x100, 1], /* type trips regardless of the byte */
    [0, 0x100, 0], /* byte mask: 0x100 & 0xff == 0 must NOT trip */
    [0, 0xff00ff, 1], /* (0xff00ff & 0xff) == 0xff != 0 */
    [0, 0x81, 1], [0, 0x80, 1], [0, 0xff, 1],
  ];
  for (const [t, b, exp] of cases) {
    assert.equal(W.room5cGate820720(t | 0, b >>> 0), exp, `room5c ${t},${b}`);
    assert.equal(W.room5cGate820720(t | 0, b >>> 0),
                 frameEffect820720Room5cGate(t | 0, b >>> 0), `js room5c ${t},${b}`);
  }
  /* 0x100 as the byte argument: masked to 0, so the gate stays closed. */
  assert.equal(W.room5cGate820720(0, 0x100 >>> 0), 0);
  assert.notEqual(W.room5cGate820720(0, 0x100 >>> 0), 1);
});

test("v29 laws: chapter_42 gate & desc_bit6 — FULL dword + LOGICAL shift", () => {
  const cCases = [
    [0, 0], [4, 1], [5, 1], [3, 0], [6, 0], [-1, 0],
    [0x100, 0], [0x104, 0], [0x105, 0], /* FULL dword, not 4/5 */
    [0x80000000, 0], [0x7fffffff, 0],
  ];
  for (const [c, exp] of cCases) {
    assert.equal(W.chapter42Gate820720(c >>> 0), exp, `chapter42 ${c}`);
    assert.equal(W.chapter42Gate820720(c >>> 0),
                 frameEffect820720Chapter42Gate(c >>> 0), `js chapter42 ${c}`);
  }
  const fCases = [
    [0x00000000, 0], [0x00000040, 1], /* exactly bit 6 */
    [0x00000020, 0], [0x00000080, 0], /* bits 5 / 7 are not bit 6 */
    [0x0000003f, 0], [0xffffffc0, 1], [0xffffffff, 1],
    [0x80000040, 1], [0x80000000, 0], /* LOGICAL: bit 31 must NOT fold */
    [0x10000040, 1], [0x10000000, 0], [0x00000140, 1],
  ];
  for (const [f, exp] of fCases) {
    assert.equal(W.descBit6820720(f >>> 0), exp, `bit6 ${f}`);
    assert.equal(W.descBit6820720(f >>> 0),
                 frameEffect820720DescBit6(f >>> 0), `js bit6 ${f}`);
  }
  assert.equal(W.descBit6820720(0x80000000 >>> 0), 0);
});

test("v29 laws: result — five arms in machine order", () => {
  /* arm 1 beats everything: game_0==0xd && chapter==1 -> 0 */
  assert.equal(W.result820720(13, 1, 4, -10, 6, 0xff, 0x40), 0);
  /* arm 2: host==4 && 18304==-10 -> 0 (after arm 1 misses) */
  assert.equal(W.result820720(0, 0, 4, -10, 6, 0xff, 0x40), 0);
  assert.equal(W.result820720(0, 1, 4, -10, 6, 0xff, 0), 0);
  /* arm 3: room type==6 or byte 0x7228 -> 0x5c (after both ret-0 miss) */
  assert.equal(W.result820720(0, 0, 0, 0, 6, 0, 0), 0x5c);
  assert.equal(W.result820720(0, 0, 0, 0, 0, 0xff, 0), 0x5c);
  assert.equal(W.result820720(0, 0, 0, 0, 6, 1, 0x40), 0x5c);
  /* arm 4: chapter 4/5 -> 0x2a (after the room gate misses) */
  assert.equal(W.result820720(0, 4, 0, 0, 0, 0, 0), 0x2a);
  assert.equal(W.result820720(0, 5, 0, 0, 0, 0, 0x40), 0x2a);
  /* arm 5: desc bit 6 -> 0x61 : 0x53 */
  assert.equal(W.result820720(0, 0, 0, 0, 0, 0, 0x40), 0x61);
  assert.equal(W.result820720(0, 0, 0, 0, 0, 0, 0), 0x53);
  assert.equal(W.result820720(0, 0, 0, 0, 0, 0, 0x80000000) >>> 0, 0x53);
  assert.equal(W.result820720(0, 0, 0, 0, 0, 0, 0xffffffc0) >>> 0, 0x61);
  assert.equal(W.result820720(0, 0, 0, 0, 0, 0, 0x80000040) >>> 0, 0x61);
  /* wide / signed discriminators across arms */
  assert.equal(W.result820720(0x100, 1, 0, 0, 0, 0, 0x40), 0x61);
  assert.equal(W.result820720(13, 0x101, 0, 0, 0, 0, 0x40), 0x61);
  assert.equal(W.result820720(0, 0, 0x104, -10, 0, 0, 0x40), 0x61);
  assert.equal(W.result820720(0, 0, 4, 0x10000000, 0, 0, 0x40), 0x61);
  assert.equal(W.result820720(0, 0, 0, 0, 0x106, 0, 0x40), 0x61);
  assert.equal(W.result820720(0, 0, 0, 0, 0, 0x100, 0x40), 0x61);
  /* always matches the JS oracle */
  const oracleRows = [
    [13, 1, 4, -10, 6, 255, 64], [0, 0, 4, -10, 0, 0, 0],
    [0, 0, 0, 0, 6, 0, 0], [0, 0, 0, 0, 0, 255, 0],
    [0, 4, 0, 0, 0, 0, 0], [0, 5, 0, 0, 0, 0, 64],
    [0, 0, 0, 0, 0, 0, 64], [0, 0, 0, 0, 0, 0, 0],
    [0x100, 1, 0, 0, 0, 0, 64], [13, 0x101, 0, 0, 0, 0, 64],
    [256, 0, 0, 0, 0x100, 0x100, 0x80000000],
  ];
  for (const [g0, ch, h, g, t, b, f] of oracleRows) {
    assert.equal(
      W.result820720(g0 >>> 0, ch >>> 0, h | 0, g | 0, t | 0, b >>> 0, f >>> 0) >>> 0,
      frameEffect820720Result(g0 >>> 0, ch >>> 0, h | 0, g | 0, t | 0, b >>> 0, f >>> 0) >>> 0,
      `result ${g0},${ch},${h},${g},${t},${b},${f}`,
    );
  }
});

test("v29 laws: entry_plan — machine-truth deref gating", () => {
  function call(g0, ch, h, g, t, b, f) {
    W.entryPlan820720(V29_SCRATCH.plan, g0 >>> 0, ch >>> 0, h | 0, g | 0,
                      t | 0, b >>> 0, f >>> 0);
    return readPlan820720(W.memory, V29_SCRATCH.plan);
  }
  /* arm 1 (game0==0xd && chapter==1): the host call never fires and no
     later deref runs — result 0. The pure gate values (host_zero,_
     room_5c, desc_bit6) are still computed from the arguments, exactly
     like v28's desc_bit6 on the chapter arm — only the deref flags are
     gated. */
  let p = call(13, 1, 4, -10, 6, 0xff, 0x40);
  assert.equal(p.derefGame, 1);
  assert.equal(p.derefChapter, 1);
  assert.equal(p.zeroGate, 1);
  assert.equal(p.host74bae0Fires, 0);
  assert.equal(p.deref18304, 0);
  assert.equal(p.hostZero, 1); /* pure gate, computed from the args */
  assert.equal(p.derefRoom, 0);
  assert.equal(p.room5c, 1); /* pure gate, computed from the args */
  assert.equal(p.chapter42, 0);
  assert.equal(p.descDeref, 0);
  assert.equal(p.flagDeref, 0);
  assert.equal(p.descBit6, 1); /* pure bit law, still computed */
  assert.equal(p.result, 0);
  assert.equal(p.hostCalls, 1);
  assert.equal(p.pureComplete, 0);
  /* arm 2: the call fires, 0x18304 is deref'd only when host==4; the
     room/desc derefs stay off. */
  p = call(0, 0, 4, -10, 6, 0xff, 0x40);
  assert.equal(p.zeroGate, 0);
  assert.equal(p.host74bae0Fires, 1);
  assert.equal(p.deref18304, 1);
  assert.equal(p.hostZero, 1);
  assert.equal(p.derefRoom, 0);
  assert.equal(p.descDeref, 0);
  assert.equal(p.result, 0);
  p = call(0, 0, 0, -10, 6, 0xff, 0x40);
  assert.equal(p.deref18304, 0); /* host result != 4: no 0x18304 read */
  assert.equal(p.hostZero, 0);
  assert.equal(p.derefRoom, 1); /* both ret-0 arms miss -> room deref */
  assert.equal(p.result, 0x5c);
  /* arm 3 (room): room deref + gates on, desc stays off. */
  p = call(0, 0, 0, 0, 6, 0, 0x40);
  assert.equal(p.derefRoom, 1);
  assert.equal(p.room5c, 1);
  assert.equal(p.descDeref, 0);
  assert.equal(p.result, 0x5c);
  /* arm 4 (chapter): desc/flags gated OFF. */
  p = call(0, 5, 0, 0, 0, 0, 0x40);
  assert.equal(p.chapter42, 1);
  assert.equal(p.descDeref, 0);
  assert.equal(p.flagDeref, 0);
  assert.equal(p.result, 0x2a);
  /* final arm: desc + flags deref, bit select, cmovne value. */
  p = call(0, 0, 0, 0, 0, 0, 0x40);
  assert.equal(p.room5c, 0);
  assert.equal(p.chapter42, 0);
  assert.equal(p.descDeref, 1);
  assert.equal(p.flagDeref, 1);
  assert.equal(p.descBit6, 1);
  assert.equal(p.result, 0x61);
  p = call(0, 0, 0, 0, 0, 0, 0);
  assert.equal(p.descBit6, 0);
  assert.equal(p.result, 0x53);
  p = call(0, 0, 0, 0, 0, 0, 0x80000000);
  assert.equal(p.descBit6, 0);
  assert.equal(p.result, 0x53);
  /* null-out skip. */
  W.entryPlan820720(0, 0, 0, 0, 0, 0, 0, 0);
  /* static asserts in the cpp cover the 60-B layout (15 x i32). */
  assert.match(SRC, /sizeof\(IsaacFrameEffect820720Plan\) == 60/);
});

test("v29 laws: deterministic edge sweep wasm === JS oracle (0 lcg draws)", () => {
  /* Draw budget: the suite carries 496 lcg draws (v28 differential 96 on
     top of the 400 base) and the cap is 500 — this unit adds ZERO
     randomized draws and sweeps a deterministic edge matrix instead
     (every value is hand-picked, so the sweep also covers corners the
     RNG would rarely hit). */
  const game0s = [0, 13, 0x100, 0x80000000, 0xffffffff];
  const chapters = [0, 1, 4, 5, 0x100];
  const hostResults = [0, 4, 0x100, -1];
  const game18304s = [0, -10, 0x10000000, 0xfffffff6];
  const roomTypes = [0, 6, 0x100, -1];
  const roomBytes = [0, 1, 0x100, 0xff00ff];
  const flagss = [0, 0x40, 0x80000000, 0xffffffc0, 0x20, 0x80000040];
  let rows = 0;
  const sweep = (g0, ch, h, g, t, b, f) => {
    rows += 1;
    /* each row: all six exports must agree with their JS oracles */
    assert.equal(W.zeroGate820720(g0 >>> 0, ch >>> 0),
                 frameEffect820720ZeroGate(g0 >>> 0, ch >>> 0), `zero ${rows}`);
    assert.equal(W.hostZeroGate820720(h | 0, g | 0),
                 frameEffect820720HostZeroGate(h | 0, g | 0), `hostZero ${rows}`);
    assert.equal(W.room5cGate820720(t | 0, b >>> 0),
                 frameEffect820720Room5cGate(t | 0, b >>> 0), `room5c ${rows}`);
    assert.equal(W.chapter42Gate820720(ch >>> 0),
                 frameEffect820720Chapter42Gate(ch >>> 0), `chapter42 ${rows}`);
    assert.equal(W.descBit6820720(f >>> 0),
                 frameEffect820720DescBit6(f >>> 0), `bit6 ${rows}`);
    assert.equal(
      W.result820720(g0 >>> 0, ch >>> 0, h | 0, g | 0, t | 0, b >>> 0, f >>> 0) >>> 0,
      frameEffect820720Result(g0 >>> 0, ch >>> 0, h | 0, g | 0, t | 0, b >>> 0, f >>> 0) >>> 0,
      `result ${rows}`,
    );
    const p = frameEffect820720EntryPlan(
      g0 >>> 0, ch >>> 0, h | 0, g | 0, t | 0, b >>> 0, f >>> 0);
    assert.equal(p.derefGame, 1, `derefGame ${rows}`);
    assert.equal(p.derefChapter, 1, `derefChapter ${rows}`);
    assert.equal(p.zeroGate === 1 ? 1 : 0,
                 W.zeroGate820720(g0 >>> 0, ch >>> 0), `plan zero ${rows}`);
  };
  /* zero-gate focus (g0 x ch), everything else neutered. */
  for (const g0 of game0s) {
    for (const ch of chapters) {
      sweep(g0, ch, 0, 0, 0, 0, 0);
    }
  }
  /* host-zero focus (h x g). */
  for (const h of hostResults) {
    for (const g of game18304s) {
      sweep(0, 0, h, g, 0, 0, 0);
    }
  }
  /* room focus (t x b), chapter/desc neutered. */
  for (const t of roomTypes) {
    for (const b of roomBytes) {
      sweep(0, 0, 0, 0, t, b, 0);
    }
  }
  /* chapter x desc focus (the two final arms), room neutered. */
  for (const ch of [0, 1, 4, 5, 0x100]) {
    for (const f of flagss) {
      sweep(0, ch, 0, 0, 0, 0, f);
    }
  }
  /* game0 x flag focus: the first zero arm vs the desc arm. */
  for (const g0 of [0, 13, 0x10d]) {
    for (const f of flagss) {
      sweep(g0, 0, 0, 0, 0, 0, f);
    }
  }
  assert.ok(rows >= 100, `expected a dense sweep, got ${rows} rows`);
  assert.equal(rows, 5 * 5 + 4 * 4 + 4 * 4 + 5 * 6 + 3 * 6); /* 105 */
});

test("v29 mutants: discriminators + ABI + census + source pins", () => {
  /* M1 zero_gate: 13&&1 must trip; the low-byte lookalikes (0x10d / 0x101)
     must NOT (a `(game0 & 0xff) == 0xd` mutant dies on them). */
  assert.equal(W.zeroGate820720(13, 1), 1);
  assert.equal(W.zeroGate820720(0x10d >>> 0, 1), 0);
  assert.equal(W.zeroGate820720(13, 0x101 >>> 0), 0);
  assert.notEqual(W.zeroGate820720(0x10d >>> 0, 1), 1);
  assert.notEqual(W.zeroGate820720(13, 0x101 >>> 0), 1);
  /* M2 host_zero_gate: 4 && -10 trip; 0x104 (low-byte 4) and 0x10000000
     must NOT. 0xfffffff6 == -10 by value. */
  assert.equal(W.hostZeroGate820720(4, -10), 1);
  assert.equal(W.hostZeroGate820720(0x104, -10), 0);
  assert.equal(W.hostZeroGate820720(4, 0x10000000), 0);
  assert.equal(W.hostZeroGate820720(4, (0xfffffff6 | 0)), 1);
  assert.notEqual(W.hostZeroGate820720(0x104, -10), 1);
  /* M3 room_5c byte mask: 0x100 as the byte must NOT trip (a mask-less
     mutant does); 0xff00ff must; type 0x106 (low-byte 6) must NOT. */
  assert.equal(W.room5cGate820720(0, 0x100 >>> 0), 0);
  assert.equal(W.room5cGate820720(0, 0xff00ff >>> 0), 1);
  assert.equal(W.room5cGate820720(0x106, 0), 0);
  assert.equal(W.room5cGate820720(6, 0), 1);
  assert.notEqual(W.room5cGate820720(0, 0x100 >>> 0), 1);
  /* M4 chapter_42 FULL dword: 4/5 trip; 0x104 / 0x105 must NOT. */
  assert.equal(W.chapter42Gate820720(4), 1);
  assert.equal(W.chapter42Gate820720(5), 1);
  assert.equal(W.chapter42Gate820720(0x104 >>> 0), 0);
  assert.equal(W.chapter42Gate820720(0x105 >>> 0), 0);
  assert.notEqual(W.chapter42Gate820720(0x104 >>> 0), 1);
  /* M5 desc_bit6 LOGICAL shift: 0x80000000 is 0, not 1 (an `sar` mutant
     folds the sign bit into bit 0); 0x40 and 0xffffffc0 trip. */
  assert.equal(W.descBit6820720(0x80000000 >>> 0), 0);
  assert.equal(W.descBit6820720(0x40 >>> 0), 1);
  assert.equal(W.descBit6820720(0xffffffc0 >>> 0), 1);
  assert.notEqual(W.descBit6820720(0x80000000 >>> 0), 1);
  /* M6 result arm order: the first matching arm wins, later arms never
     reachable — an arm-swap mutant dies on the precedence rows. */
  assert.equal(W.result820720(13, 1, 4, -10, 6, 0xff, 0x40), 0);
  assert.equal(W.result820720(0, 0, 4, -10, 6, 0xff, 0x40), 0);
  assert.equal(W.result820720(0, 0, 0, 0, 6, 0xff, 0x40), 0x5c);
  assert.equal(W.result820720(0, 4, 0, 0, 0, 0, 0), 0x2a);
  assert.equal(W.result820720(0, 0, 0, 0, 0, 0, 0x40), 0x61);
  assert.equal(W.result820720(0, 0, 0, 0, 0, 0, 0), 0x53);
  assert.notEqual(W.result820720(0, 0, 4, -10, 6, 0xff, 0x40), 0x5c);
  assert.notEqual(W.result820720(0, 0, 0, 0, 6, 0xff, 0x40), 0x2a);
  /* M7 entry_plan deref gating: chapter arm must NOT deref desc/flags;
     the host call fires only off the first zero arm; the 0x18304 read
     only when the host result == 4. */
  W.entryPlan820720(V29_SCRATCH.plan, 0, 5, 0, 0, 0, 0, 0x40);
  assert.equal(readPlan820720(W.memory, V29_SCRATCH.plan).descDeref, 0);
  assert.notEqual(readPlan820720(W.memory, V29_SCRATCH.plan).descDeref, 1);
  assert.equal(readPlan820720(W.memory, V29_SCRATCH.plan).result, 0x2a);
  W.entryPlan820720(V29_SCRATCH.plan, 13, 1, 4, -10, 6, 0xff, 0x40);
  assert.equal(readPlan820720(W.memory, V29_SCRATCH.plan).host74bae0Fires, 0);
  assert.equal(readPlan820720(W.memory, V29_SCRATCH.plan).derefRoom, 0);
  W.entryPlan820720(V29_SCRATCH.plan, 0, 0, 0, -10, 6, 0xff, 0x40);
  assert.equal(readPlan820720(W.memory, V29_SCRATCH.plan).deref18304, 0);
  assert.equal(readPlan820720(W.memory, V29_SCRATCH.plan).derefRoom, 1);
  /* M8 nullable out: entry_plan with out == 0 must not trap. */
  W.entryPlan820720(0, 0, 0, 0, 0, 0, 0, 0);
  /* M9 ABI pin: 29 (atomic bump fired — v29 laws landed). */
  assert.equal(W.abi(), 51);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_PURE_HELPERS_ABI_VERSION = 51/);
  assert.equal(FRAME_EFFECT_PURE_ABI_VERSION, 51);
  /* M10 v29 census + ZHL pins. */
  assert.equal(FRAME_EFFECT_820720_VA, 0x00820720);
  assert.equal(FRAME_EFFECT_820720_END_VA, 0x0082079c);
  assert.equal(FRAME_EFFECT_820720_NEXT_VA, 0x008207a0);
  assert.equal(FRAME_EFFECT_820720_INSN_COUNT, 46);
  assert.equal(FRAME_EFFECT_820720_BYTE_LEN, 124);
  assert.equal(FRAME_EFFECT_820720_CALL_INSNS, 1);
  assert.equal(FRAME_EFFECT_820720_DIRECT_CALLERS, 2);
  assert.equal(FRAME_EFFECT_820720_CALLSITE_A_VA, 0x007fee72);
  assert.equal(FRAME_EFFECT_820720_CALLSITE_B_VA, 0x007ff7fe);
  assert.equal(FRAME_EFFECT_820720_HOST_74BAE0_VA, 0x0074bae0);
  assert.equal(FRAME_EFFECT_820720_GAME_18304_EXPECT, -10);
  assert.equal(FRAME_EFFECT_820720_ROOM_7228_OFF, 0x7228);
  assert.equal(FRAME_EFFECT_820720_RESULT_BIT6, 0x61);
  assert.equal(FRAME_EFFECT_820720_RESULT_CLEAR, 0x53);
  assert.equal(FRAME_EFFECT_820720_RET_5C_VA, 0x0082079b);
  /* M11 source pins — the ZHL promotion + the v29 cpp block cites the
     machine, carries the byte-gate mask and no byte-width declarator. */
  assert.match(HDR, /ABI v29\. Pure laws of FUN_00820720/);
  assert.match(HDR, /Room::GetBossVictoryJingle/);
  assert.match(HDR, /56 8b 35/);
  assert.match(HDR, /frame-effect-v29-820720/);
  assert.match(HDR, /the sibling recorded at v28 as/);
  assert.match(HDR, /0x0082072a  cmp dword \[esi\],0xd/);
  assert.match(SRC, /ABI v29 — FUN_00820720 Room::GetBossVictoryJingle/);
  assert.match(SRC, /0x0082073c cmp eax,4 ; jne 0x82074f/);
  assert.match(SRC, /0x00820741 cmp\s*\[esi\+0x18304\],-0xa/);
  assert.match(SRC, /0x00820755 cmp \[eax\+8\],6/);
  assert.match(SRC, /cmp byte \[eax\+0x7228\],0/);
  assert.match(SRC, /0x0082077e shr eax,6 \(LOGICAL\)/);
  assert.match(SRC, /0x00820781 test al,1/);
  assert.match(SRC, /0x00820788 cmovne eax,ecx/);
  assert.match(SRC, /arm order as compiled/);
  /* the ret arms' text lives in the v29 header stream */
  assert.match(HDR, /0x0082078c\s+pop edi; mov eax,0x2a/);
  assert.match(HDR, /0x00820794\s+pop edi; mov eax,0x5c/);
  /* M12 the v29 cpp block carries the explicit byte mask + bit mask,
     includes the byte gate (cmp byte ptr — unlike v28's register-only
     block), and has no byte-width declarator anywhere. */
  const v29SrcBlock = SRC.slice(SRC.indexOf("ABI v29 — FUN_00820720"));
  const v29SrcEnd = v29SrcBlock.indexOf("ABI v30 — FUN_008207a0");
  const srcBlock = v29SrcBlock.slice(0, v29SrcEnd);
  assert.match(srcBlock, /& 0xffu/);
  assert.match(srcBlock, /&\s*1u/);
  assert.match(srcBlock, /cmp byte \[eax\+0x7228\],0/);
  assert.doesNotMatch(srcBlock, /uint8_t/);
});

/* ------------------------------------------------------------------ */
/* ABI v30: FUN_008207a0 — the SEH intro-action body, decision-seams
 * class (NOT PURE-OPEN: 5 host calls + 2 stateful store sites; the
 * translated surface is the four-gate entry conjunction, the desc-value
 * arg formation for the family's own 0x6fe410 dispatcher call, the
 * post-loop byte gate that selects the 0xa648b0 allocator call, and the
 * constant result; exception path stays host) — and FUN_008208c0, the
 * next pure sibling after its int3 pad (0x8208b3..0x8208bf), PURE-OPEN:
 * comiss xmm0,[0xba9fe4] (+0.0f — CORRECTED v31: measured bits
 * 0x00000000; the v30 "-18.0f/0xc1900000" text mis-mapped the .rdata
 * read) + seta al.
 * Evidence: section-notes/frame-effect-v30-8207a0/
 * (census-8207a0-body.json, caller-census.py). */

/* v30 scratch sits above v29 (0x1d0000). 0x1e0000+ is fresh. */
const V30_SCRATCH = {
  plan7a0: 0x1e0000, /* 52 B — IsaacFrameEffect8207a0Plan (13 fields) */
  plan8c0: 0x1e1000, /* 16 B — IsaacFrameEffect8208c0Plan (4 fields) */
};

function readPlan8207a0(memory, base) {
  return {
    derefGame: i32At(memory, base + 0),
    derefModeFlags: i32At(memory, base + 4),
    derefTransition: i32At(memory, base + 8),
    derefFlagObj: i32At(memory, base + 12),
    derefFlagByte: i32At(memory, base + 16),
    entryGate: i32At(memory, base + 20),
    descDeref: i32At(memory, base + 24),
    desc5cDeref: i32At(memory, base + 28),
    descValue: i32At(memory, base + 32) >>> 0,
    postLoopGate: i32At(memory, base + 36),
    result: i32At(memory, base + 40) >>> 0,
    hostCalls: i32At(memory, base + 44),
    pureComplete: i32At(memory, base + 48),
  };
}

function readPlan8208c0(memory, base) {
  return {
    derefField: i32At(memory, base + 0),
    above: i32At(memory, base + 4),
    hostCalls: i32At(memory, base + 8),
    pureComplete: i32At(memory, base + 12),
  };
}

