test("no uint8_t scalar parameters in the v31 declaration blocks", () => {
  const v31Block = HDR.slice(HDR.indexOf("/* ABI v31."));
  const v31End = v31Block.indexOf("/* ABI v32.");
  const block = v31Block.slice(0, v31End);
  const declLines = block
    .split("\n")
    .filter((ln) =>
      /^(void|uint32_t|int32_t|float)\s+isaac_frame_effect_8208e0_/.test(ln.trim()) ||
      /^(void|uint32_t|int32_t|float)\s+isaac_frame_effect_820910_/.test(ln.trim()),
    );
  assert.ok(declLines.length >= 8, `expected 8 v31 declarations, got ${declLines.length}`);
  assert.doesNotMatch(block, /uint8_t/);
  assert.match(block, /game_18314/);
  assert.match(block, /sentinel_match/);
  assert.match(block, /dist_scale/);
  for (const ln of declLines) {
    const m = ln.match(/isaac_frame_effect_(8208e0|820910)_([a-z0-9_]+)/);
    const vaL = m[1];
    const shortName = m[2];
    const name = `isaac_frame_effect_${vaL}_${shortName}`;
    assert.ok(EXPORTS.includes(name), `EXPORTS missing ${name}`);
    const wKey = shortName.replace(/_([a-z0-9])/g, (_, ch) => ch.toUpperCase());
    const key = `${wKey}${vaL}`;
    assert.equal(typeof W[key], "function", `W missing ${name}`);
  }
});

test("v31 laws: sync_gate — FULL dword equality (v23-shape precedent)", () => {
  /* the 8208e0 body is the same value shape as 820170 probe_bit2_gate:
     [0x740bc0 ret + 8] == [g_Game+0x18314] (0x8208fb cmp / 0x820901
     sete al). ret8 and game_18314 are caller-resolved. */
  const cases = [
    [5, 5, 1],
    [5, 6, 0],
    [0xffffffff, -1, 1],
    [-1, 0xffffffff, 1],
    [-1, -2, 0],
    [0x100, 0x100, 1],
    [0x100, 0x101, 0],
    [0x00000000, 0, 1],
  ];
  for (const [a, b, exp] of cases) {
    assert.equal(W.syncGate8208e0(a >>> 0, b >>> 0), exp, `sync ${a},${b}`);
    assert.equal(W.syncGate8208e0(a >>> 0, b >>> 0),
                 frameEffect8208e0SyncGate(a >>> 0, b >>> 0), `js sync ${a},${b}`);
  }
  /* the host args stay host-side: the law never sees the 0x740bc0 call,
     its idx/-1 pack or [g+0x18304] — only the compared values. */
  assert.equal(FRAME_EFFECT_8208E0_HOST_ARG2, 0xffffffff);
  assert.equal(FRAME_EFFECT_8208E0_GAME_18304_OFF, 0x18304);
  assert.equal(FRAME_EFFECT_8208E0_RET8_OFF, 0x8);
  assert.equal(FRAME_EFFECT_8208E0_HOST_740BC0_VA, 0x00740bc0);
});

test("v31 laws: desc_flags_rewrite / getplayer_gate / pack_arg", () => {
  /* desc_flags: flags | 0x4000 — pure rewrite of the unconditional
     desc-flag store (the store itself stays host). */
  const dCases = [
    [0, 0x4000],
    [0x4000, 0x4000],
    [0x1, 0x4001],
    [0x8000, 0xc000],
    [0xffffffff, 0xffffffff],
    [0x80000000, 0x80004000],
  ];
  for (const [f, exp] of dCases) {
    assert.equal(W.descFlagsRewrite820910(f >>> 0) >>> 0, exp >>> 0, `rewrite ${f}`);
    assert.equal(W.descFlagsRewrite820910(f >>> 0) >>> 0,
                 frameEffect820910DescFlagsRewrite(f >>> 0) >>> 0, `js rewrite ${f}`);
  }
  /* getplayer_gate: the first Game::GetPlayer (0x417870) fires iff
     arg2 == 0 — FULL dword zero-test (0x82092f/0x820934). */
  const gCases = [
    [0, 1], [1, 0], [0xffffffff, 0], [0x100, 0], [0x80000000, 0],
  ];
  for (const [a, exp] of gCases) {
    assert.equal(W.getplayerGate820910(a >>> 0), exp, `gate ${a}`);
    assert.equal(W.getplayerGate820910(a >>> 0),
                 frameEffect820910GetPlayerGate(a >>> 0), `js gate ${a}`);
  }
  /* pack_arg: arg2 when nonzero, else the caller-resolved GetPlayer
     result — the 0x6fe410 pack arg4 formation (0x82093c/0x820950). */
  const pCases = [
    [0, 0xdeadbeef, 0xdeadbeef],
    [1, 0xdeadbeef, 1],
    [0xffffffff, 7, 0xffffffff],
    [0x80000000, 7, 0x80000000],
    [0, 0, 0],
  ];
  for (const [a, h, exp] of pCases) {
    assert.equal(W.packArg820910(a >>> 0, h >>> 0) >>> 0, exp >>> 0, `pack ${a},${h}`);
    assert.equal(W.packArg820910(a >>> 0, h >>> 0) >>> 0,
                 frameEffect820910PackArg(a >>> 0, h >>> 0) >>> 0, `js pack ${a},${h}`);
  }
});

test("v31 laws: sentinel_match — f32 IEEE equality (lahf/jp algebra)", () => {
  /* the lahf/test-ah/jp parity algebra: the normalize path runs iff BOTH
     probes are ORDERED-EQUAL; for these positive-normal constants the
     law equals (x0_bits == c0) && (x1_bits == c1) — NaN and +-0.0
     disagree with the constants under both semantics. */
  const c0 = FRAME_EFFECT_820910_SENTINEL_X0_BITS;
  const c1 = FRAME_EFFECT_820910_SENTINEL_X1_BITS;
  const cases = [
    [c0, c1, 1],
    [c0, 0x00000000, 0], /* x1 zero */
    [0x00000000, c1, 0], /* x0 zero */
    [c0, 0x80000000, 0], /* x1 -0.0 */
    [0x7fc00000, c1, 0], /* x0 NaN */
    [c0, 0x7fc00000, 0], /* x1 NaN */
    [0x7fffffff, 0xffffffff, 0], /* NaN + random */
    [c0, 0x37873771, 0], /* x1 one ulp off */
    [0x3760371d, c1, 0], /* x0 one ulp off */
    [0x3760371c, 0x37873770, 1], /* exact pair again */
    [0x3760371d, 0x37873770, 0],
    [0x00000001, 0x00000001, 0], /* denormals */
    [0x7f800000, 0x7f800000, 0], /* +Inf */
  ];
  for (const [a, b, exp] of cases) {
    assert.equal(W.sentinelMatch820910(a >>> 0, b >>> 0), exp,
                 `match ${a.toString(16)},${b.toString(16)}`);
    assert.equal(W.sentinelMatch820910(a >>> 0, b >>> 0),
                 frameEffect820910SentinelMatch(a >>> 0, b >>> 0),
                 `js match ${a.toString(16)},${b.toString(16)}`);
  }
});

test("v31 laws: dist_scale — comiss/jbe f32 boundary + exact f32 division", () => {
  /* comiss xmm0,[0xba9fe4] (+0.0f) ; jbe skip — the scale is
     200.0f/res only for ORDERED res > 0 (NaN / -0.0 / negatives keep
     1.0f); 200.0f @ 0xbaaa94. The division is exact f32: the wasm emits
     f32.div and the oracle single-rounds via Math.fround (f64 has
     53 >= 2*24+2 bits, so double rounding is innocuous for division in
     round-to-nearest). */
  const cases = [
    [0x3f800000, 0x43480000, 1], /* res 1.0 -> 200.0 */
    [0x40000000, 0x42c80000, 1], /* res 2.0 -> 100.0 */
    [0x40800000, 0x42480000, 1], /* res 4.0 -> 50.0 */
    [0x40c00000, 0x42055555, 1], /* res 6.0 -> 33.333332f */
    [0x3fc00000, 0x43055555, 1], /* res 1.5 -> 133.33333f */
    [0x43480000, 0x3f800000, 1], /* res 200.0 -> 1.0 (scale == 1.0 but
                                    the GATE is 1 — res > 0) */
    [0x00000000, 0x3f800000, 0], /* res +0.0 -> 1.0, gate 0 */
    [0x80000000, 0x3f800000, 0], /* res -0.0 -> 1.0, gate 0 */
    [0x7fc00000, 0x3f800000, 0], /* res NaN -> 1.0, gate 0 */
    [0x7f800000, 0x00000000, 1], /* res +Inf -> 200.0/Inf = 0.0, gate 1 */
    [0x00000001, 0x7f800000, 1], /* min denormal -> 200/min -> +Inf */
    [0x80000001, 0x3f800000, 0], /* -min denormal -> 1.0, gate 0 */
    [0xc0000000, 0x3f800000, 0], /* res -2.0 -> 1.0, gate 0 */
    [0x40400000, 0x42855555, 1], /* res 3.0 -> 66.666664f */
    [0x40a00000, 0x42200000, 1], /* res 5.0 -> 40.0 */
  ];
  for (const [bits, expBits, gate] of cases) {
    const got = W.distScale820910(bits >>> 0);
    assert.equal(f32ToBits(got), expBits >>> 0, `scale ${bits.toString(16)}`);
    const js = frameEffect820910DistScale(bits >>> 0);
    assert.equal(f32ToBits(js), expBits >>> 0, `js scale ${bits.toString(16)}`);
    assert.equal(got, js, `scale value ${bits.toString(16)}`);
    /* the gate, mirrored in the plan: res > 0.0f */
    assert.equal(resGtZero(bits >>> 0), gate, `gate ${bits.toString(16)}`);
  }
});

function resGtZero(bits) {
  /* the plan's dist gate is the comiss+jbe test itself (res > 0.0f),
     NOT the scale — the scale is exactly 1.0 also when res == 200.0f. */
  return bitsToF32(bits) > 0 ? 1 : 0;
}

test("v31 laws: entry_plans — deref census + layout", () => {
  function call8e0(r8, g14) {
    W.entryPlan8208e0(V31_SCRATCH.plan8e0, r8 >>> 0, g14 >>> 0);
    return readPlan8208e0(W.memory, V31_SCRATCH.plan8e0);
  }
  /* all derefs unconditional; the gate is the only varying field. */
  let p = call8e0(5, 5);
  assert.equal(p.derefGame, 1);
  assert.equal(p.deref18304, 1);
  assert.equal(p.host740bc0, 1);
  assert.equal(p.derefRet8, 1);
  assert.equal(p.deref18314, 1);
  assert.equal(p.syncGate, 1);
  assert.equal(p.hostCalls, 1);
  assert.equal(p.pureComplete, 1);
  p = call8e0(5, 6);
  assert.equal(p.syncGate, 0);
  p = call8e0(0, 0);
  assert.equal(p.syncGate, 1);
  /* JS oracle matching */
  assert.deepEqual(frameEffect8208e0EntryPlan(5, 5), p);
  W.entryPlan8208e0(0, 0, 0); /* null-out skips */

  function call910(a2, x0, x1, sr) {
    W.entryPlan820910(V31_SCRATCH.plan910, a2 >>> 0, x0 >>> 0, x1 >>> 0,
                      sr >>> 0);
    return readPlan820910(W.memory, V31_SCRATCH.plan910);
  }
  /* normal path: arg2 != 0, sentinel match, sqrt > 0. */
  let q = call910(3, 0x3760371c, 0x37873770, 0x3f800000);
  assert.equal(q.derefDesc, 1);
  assert.equal(q.storeFlags, 1);
  assert.equal(q.getPlayerGate, 0);
  assert.equal(q.draw, 1);
  assert.equal(q.derefParam1, 1);
  assert.equal(q.sentinelMatch, 1);
  assert.equal(q.derefPlayer, 1);
  assert.equal(q.distGate, 1);
  assert.equal(q.hostCalls, 6);
  assert.equal(q.pureComplete, 0);
  /* arg2 == 0: the first GetPlayer fires (gate 1). */
  q = call910(0, 0x3760371c, 0x37873770, 0x3f800000);
  assert.equal(q.getPlayerGate, 1);
  /* sentinel miss: raw-copy path — no second GetPlayer deref. */
  q = call910(3, 0x3760371c, 0, 0x3f800000);
  assert.equal(q.sentinelMatch, 0);
  assert.equal(q.derefPlayer, 0);
  assert.equal(q.distGate, 1); /* the sqrt gate is independent of the path */
  /* sqrt <= 0: the 200/sqrt scale does not run. */
  q = call910(3, 0x3760371c, 0x37873770, 0x80000000);
  assert.equal(q.distGate, 0);
  q = call910(3, 0x3760371c, 0x37873770, 0x7fc00000);
  assert.equal(q.distGate, 0);
  /* JS oracle equality on a few rows — the wasm plan is re-called
     with the SAME inputs the oracle sees (q above is the NaN row). */
  W.entryPlan820910(V31_SCRATCH.plan910, 3, 0x3760371c, 0x37873770,
                    0x3f800000);
  assert.deepEqual(
    readPlan820910(W.memory, V31_SCRATCH.plan910),
    frameEffect820910EntryPlan(3, 0x3760371c, 0x37873770, 0x3f800000));
  /* static asserts in the cpp cover the 32-B / 40-B layouts. */
  assert.match(SRC, /sizeof\(IsaacFrameEffect8208e0Plan\) == 32/);
  assert.match(SRC, /sizeof\(IsaacFrameEffect820910Plan\) == 40/);
  W.entryPlan820910(0, 0, 0, 0, 0); /* null-out skips */
});

test("v31 laws: deterministic edge sweep wasm === JS oracle (0 lcg draws)", () => {
  /* Draw budget: the suite carries 496 lcg draws and the cap is 500 —
     this unit adds ZERO randomized draws and sweeps a deterministic edge
     matrix instead. */
  const arg2s = [0, 1, 0xffffffff, 0x100, 0x80000000];
  const sentX0 = [0x3760371c, 0x3760371d, 0x00000000, 0x7fc00000, 0x80000000];
  const sentX1 = [0x37873770, 0x37873771, 0x00000000, 0x7fc00000, 0x80000000];
  const sqrts = [0x3f800000, 0x00000000, 0x80000000, 0x7fc00000,
                 0x7f800000, 0x00000001, 0xc0000000, 0x43480000,
                 0x40a00000];
  let rows = 0;
  const sweep = (a2, x0, x1, sr) => {
    rows += 1;
    assert.equal(W.syncGate8208e0(a2 >>> 0, a2 >>> 0), 1, `sync ${rows}`);
    assert.equal(
      W.syncGate8208e0(x0 >>> 0, x1 >>> 0),
      frameEffect8208e0SyncGate(x0 >>> 0, x1 >>> 0), `sync2 ${rows}`);
    assert.equal(
      W.descFlagsRewrite820910(x0 >>> 0) >>> 0,
      frameEffect820910DescFlagsRewrite(x0 >>> 0) >>> 0, `rewrite ${rows}`);
    assert.equal(W.getplayerGate820910(a2 >>> 0),
                 frameEffect820910GetPlayerGate(a2 >>> 0), `gate ${rows}`);
    assert.equal(
      W.packArg820910(a2 >>> 0, x1 >>> 0) >>> 0,
      frameEffect820910PackArg(a2 >>> 0, x1 >>> 0) >>> 0, `pack ${rows}`);
    assert.equal(
      W.sentinelMatch820910(x0 >>> 0, x1 >>> 0),
      frameEffect820910SentinelMatch(x0 >>> 0, x1 >>> 0), `match ${rows}`);
    assert.equal(
      f32ToBits(W.distScale820910(sr >>> 0)),
      f32ToBits(frameEffect820910DistScale(sr >>> 0)), `dist ${rows}`);
    const p = frameEffect820910EntryPlan(a2 >>> 0, x0 >>> 0, x1 >>> 0,
                                         sr >>> 0);
    assert.equal(p.hostCalls, 6, `hosts ${rows}`);
    assert.equal(p.pureComplete, 0, `pure ${rows}`);
    assert.equal(p.derefPlayer, p.sentinelMatch, `derefPlayer ${rows}`);
    assert.equal(p.draw, 1, `draw ${rows}`);
  };
  for (const a2 of arg2s) {
    for (const sr of sqrts) {
      sweep(a2, 0x3760371c, 0x37873770, sr);
    }
  }
  for (const x0 of sentX0) {
    for (const x1 of sentX1) {
      sweep(3, x0, x1, 0x3f800000);
    }
  }
  for (const sr of sqrts) {
    sweep(0, 0x3760371c, 0x37873770, sr);
  }
  for (const x0 of sentX0) {
    for (const sr of sqrts) {
      sweep(3, x0, 0x37873770, sr);
    }
  }
  for (const x1 of sentX1) {
    for (const sr of sqrts) {
      sweep(5, 0x3760371c, x1, sr);
    }
  }
  assert.ok(rows >= 100, `expected a dense sweep, got ${rows} rows`);
  assert.equal(rows, 5 * 9 + 5 * 5 + 9 + 5 * 9 + 5 * 9); /* 45+25+9+45+45 */
});

test("v31 mutants: discriminators + ABI + census + source pins", () => {
  /* M1 sync_gate equality: XOR would flip 5,5 -> 0 and 5,6 -> 1. */
  assert.equal(W.syncGate8208e0(5, 5), 1);
  assert.equal(W.syncGate8208e0(5, 6), 0);
  assert.notEqual(W.syncGate8208e0(5, 5), 0);
  assert.notEqual(W.syncGate8208e0(5, 6), 1);
  /* M2 sentinel_match single-probe: dropping the x1 probe would mark
     (c0, 0) as a match. */
  assert.equal(W.sentinelMatch820910(0x3760371c, 0), 0);
  assert.equal(W.sentinelMatch820910(0, 0x37873770), 0);
  assert.equal(W.sentinelMatch820910(0x3760371c, 0x37873770), 1);
  assert.notEqual(W.sentinelMatch820910(0x3760371c, 0), 1);
  /* M3 getplayer_gate == -> != : arg2 1 would fire the call. */
  assert.equal(W.getplayerGate820910(0), 1);
  assert.equal(W.getplayerGate820910(1), 0);
  assert.notEqual(W.getplayerGate820910(1), 1);
  /* M4 dist_scale boundary >= : -0.0 or NaN would get the 200/res
     branch (and res 1.0 would still be 200 — dies on -0.0 / NaN). */
  assert.equal(f32ToBits(W.distScale820910(0x80000000)), 0x3f800000);
  assert.equal(f32ToBits(W.distScale820910(0x7fc00000)), 0x3f800000);
  assert.equal(f32ToBits(W.distScale820910(0x00000001)), 0x7f800000);
  assert.notEqual(f32ToBits(W.distScale820910(0x80000000)), 0x43480000);
  /* M5 pack_arg select inverted: (0, host) and (1, host) swap. */
  assert.equal(W.packArg820910(0, 0xdeadbeef) >>> 0, 0xdeadbeef >>> 0);
  assert.equal(W.packArg820910(1, 0xdeadbeef) >>> 0, 1);
  assert.notEqual(W.packArg820910(0, 0xdeadbeef) >>> 0, 1);
  assert.notEqual(W.packArg820910(1, 0xdeadbeef) >>> 0, 0xdeadbeef >>> 0);
  /* M6 ABI pin: 31 (atomic bump fired — v31 laws landed). */
  assert.equal(W.abi(), 51);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_PURE_HELPERS_ABI_VERSION = 51/);
  assert.equal(FRAME_EFFECT_PURE_ABI_VERSION, 51);
  /* M7 v31 census pins (spot). */
  assert.equal(FRAME_EFFECT_8208E0_VA, 0x008208e0);
  assert.equal(FRAME_EFFECT_8208E0_END_VA, 0x00820905);
  assert.equal(FRAME_EFFECT_8208E0_INSN_COUNT, 8);
  assert.equal(FRAME_EFFECT_8208E0_BYTE_LEN, 37);
  assert.equal(FRAME_EFFECT_8208E0_CALL_INSNS, 1);
  assert.equal(FRAME_EFFECT_8208E0_DIRECT_CALLERS, 2);
  assert.equal(FRAME_EFFECT_8208E0_CALLSITE_A_VA, 0x007fbd1f);
  assert.equal(FRAME_EFFECT_8208E0_CALLSITE_B_VA, 0x0080df46);
  assert.equal(FRAME_EFFECT_8208E0_HIT_VA, 0x0086c8e5);
  assert.equal(FRAME_EFFECT_8208E0_HOST_740BC0_VA, 0x00740bc0);
  assert.equal(FRAME_EFFECT_820910_VA, 0x00820910);
  assert.equal(FRAME_EFFECT_820910_END_VA, 0x00820a99);
  assert.equal(FRAME_EFFECT_820910_INSN_COUNT, 64);
  assert.equal(FRAME_EFFECT_820910_BYTE_LEN, 393);
  assert.equal(FRAME_EFFECT_820910_CALL_INSNS, 5);
  assert.equal(FRAME_EFFECT_820910_INDIRECT_CALLS, 1);
  assert.equal(FRAME_EFFECT_820910_DIRECT_CALLERS, 2);
  assert.equal(FRAME_EFFECT_820910_CALLSITE_A_VA, 0x0074baa7);
  assert.equal(FRAME_EFFECT_820910_CALLSITE_B_VA, 0x008053be);
  assert.equal(FRAME_EFFECT_820910_RAW_DWORD_HITS, 2);
  assert.equal(FRAME_EFFECT_820910_SENTINEL_X0_BITS, 0x3760371c);
  assert.equal(FRAME_EFFECT_820910_SENTINEL_X1_BITS, 0x37873770);
  assert.equal(FRAME_EFFECT_820910_SCALE_200_BITS, 0x43480000);
  assert.equal(FRAME_EFFECT_820910_LUA_NAME_VA, 0x00b73d18);
  assert.equal(FRAME_EFFECT_8208C0_CONST_BITS, 0x00000000);
  /* M8 source pins — the v31 header block cites both streams, the
     lahf/jp algebra, the registrations and the corrected constant; the
     v31 cpp block carries the laws with PE anchors and no byte-width
     declarator. */
  assert.match(HDR, /ABI v31\. \(A\) Pure laws of FUN_008208e0/);
  assert.match(HDR, /0x008208e0\s+mov ecx,\[0xc71678\]/);
  assert.match(HDR, /0x008208ee\s+call 0x740bc0/);
  assert.match(HDR, /0x00820901\s+sete al/);
  assert.match(HDR, /"IsCurrentRoomLastBoss"/);
  assert.match(HDR, /\(B\) Decision seams of FUN_00820910/);
  assert.match(HDR, /"MamaMegaExplosion"/);
  assert.match(HDR, /LAHF\/JP gate algebra/);
  assert.match(HDR, /0x00820921\s+or dword \[eax\+0x44\],0x4000/);
  assert.match(HDR, /0x00820969\s+ucomiss xmm0,\[0xc7b640\]/);
  assert.match(HDR, /0x00820a12\s+comiss xmm0,\[0xba9fe4\]/);
  assert.match(HDR, /0x00820a66\s+call dword \[eax\+0xc\]/);
  assert.match(HDR, /\+0\.0f \(bits 0x00000000/);
  assert.match(SRC, /ABI v31 — FUN_008208e0/);
  assert.match(SRC, /0x008208fb cmp ecx,\[eax\+0x18314\]/);
  assert.match(SRC, /0x00820921\s+or dword \[eax\+0x44\],0x4000/);
  assert.match(SRC, /0x820a29/);
  assert.match(SRC, /f32.*div.*divss/);
  /* the v31 cpp block has no byte-width declarator anywhere. */
  const v31SrcBlock = SRC.slice(SRC.indexOf("ABI v31 — FUN_008208e0"));
  const v31SrcEnd = v31SrcBlock.indexOf("ABI v32 — FUN_00820aa0");
  const srcBlock = v31SrcBlock.slice(0, v31SrcEnd);
  assert.doesNotMatch(srcBlock, /uint8_t/);
  /* the v31 header decl block stays free of the byte-width declarator
     token and the block boundary is the v31 markers. */
  const v31HdrBlock = HDR.slice(HDR.indexOf("/* ABI v31."));
  const v31HdrEnd = v31HdrBlock.indexOf("/* ABI v32.");
  const hdrBlock = v31HdrBlock.slice(0, v31HdrEnd);
  assert.doesNotMatch(hdrBlock, /uint8_t/);
});

/* ------------------------------------------------------------------ */
/* ABI v32: FUN_00820aa0 — Lua Room::GetDungeonRockIdx (PURE-OPEN: 0
 * calls / 0 stores, the two-branch getter translated whole) — and
 * FUN_00820ac0 — Lua Room::TurnGold (decision seams: alias gates, init/
 * rewrite block values, loop bounds, per-entry gates, host-call pack;
 * 1 host call 0x7ebd50 EXACT ZHL Room::SpawnGridEntityDesc). Evidence:
 * section-notes/frame-effect-v32-820aa0/ (census-820aa0.py,
 * identify-zhl.json). ALSO records the measured SEH correction: the
 * v31 frontier's "SEH-heavy" label for 0x820ac0 is WRONG — plain
 * frame, no fs:[0], no GS cookie. */

/* v32 scratch sits above v31 (0x1f0000). 0x1f2000+ is fresh. */
const V32_SCRATCH = {
  planAa0: 0x1f2000, /* 24 B — IsaacFrameEffect820aa0Plan (6 fields) */
  planAc0: 0x1f3000, /* 40 B — IsaacFrameEffect820ac0Plan (10 fields) */
  block: 0x1f4000,   /* 11 dwords — the init-block outputs */
  packOut: 0x1f5000, /* 8 dwords — the grid_desc_pack output */
  packIn: 0x1f6000,  /* 4 dwords — the pack tail input */
};

function readPlan820aa0(memory, base) {
  return {
    derefGame: i32At(memory, base + 0),
    deref1839c: i32At(memory, base + 4),
    bitGate: i32At(memory, base + 8),
    deref768: i32At(memory, base + 12),
    hostCalls: i32At(memory, base + 16),
    pureComplete: i32At(memory, base + 20),
  };
}

function readPlan820ac0(memory, base) {
  return {
    initA: i32At(memory, base + 0),
    initB: i32At(memory, base + 4),
    copyGateA: i32At(memory, base + 8),
    copyGateB: i32At(memory, base + 12),
    entryNonzero: i32At(memory, base + 16),
    kindGate: i32At(memory, base + 20),
    animSkip: i32At(memory, base + 24),
    rewriteArm: i32At(memory, base + 28),
    hostCalls: i32At(memory, base + 32),
    pureComplete: i32At(memory, base + 36),
  };
}

function u32sAt(memory, base, n) {
  const out = [];
  for (let i = 0; i < n; i += 1) out.push(u32At(memory, base + i * 4));
  return out;
}

