test("v43 0x825730 CanPickupGridEntity census + wasm-vs-oracle", () => {
  assert.equal(W.abi(), 51);
  assert.equal(FRAME_EFFECT_PURE_ABI_VERSION, 51);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_PURE_HELPERS_ABI_VERSION = 51/);
  assert.equal(FRAME_EFFECT_825730_VA, 0x00825730);
  assert.equal(FRAME_EFFECT_825730_RET_VA, 0x00825796);
  assert.equal(FRAME_EFFECT_825730_END_VA, 0x00825799);
  assert.equal(FRAME_EFFECT_825730_INSN_COUNT, 40);
  assert.equal(FRAME_EFFECT_825730_BYTE_LEN, 105);
  assert.equal(FRAME_EFFECT_825730_CALL_INSNS, 0);
  assert.equal(FRAME_EFFECT_825730_DIRECT_CALLERS, 5);
  assert.equal(FRAME_EFFECT_825730_CALLER_A, 0x0055d121);
  assert.equal(FRAME_EFFECT_825730_CALLER_E, 0x005b1b0e);
  assert.equal(FRAME_EFFECT_825730_IDX_MAX, 0x1bf);
  assert.equal(FRAME_EFFECT_825730_LIST_OFF, 0x24);
  assert.equal(FRAME_EFFECT_825730_ENTITY_TYPE_OFF, 0x4);
  assert.equal(FRAME_EFFECT_825730_ENTITY_FLAG_OFF, 0x3c);
  assert.equal(FRAME_EFFECT_825730_ENTITY_SUB_OFF, 0xc);
  assert.equal(FRAME_EFFECT_825730_SUB_MIN, 4);
  assert.equal(FRAME_EFFECT_825730_PAUSE_FIELD, 0x3e8);
  assert.equal(FRAME_EFFECT_825730_RET_ARGS, 4);
  assert.match(HDR, /isaac_frame_effect_825730_gate/);
  assert.doesNotMatch(HDR, /uint8_t isaac_frame_effect_825730/);

  /* type_ok: [type, sub_field, want] */
  const typeCases = [
    [2, 0, 1],
    [4, 7, 1],
    [5, 0, 1],
    [6, 0, 1],
    [0x1a, 9, 1],
    [0x16, 0, 1],
    [0x1b, 0xffff, 1],
    [0xc, 0, 1], /* <u 4 -> yes */
    [0xc, 3, 1],
    [0xc, 4, 0], /* == 4 -> no (jb not taken) */
    [0xc, 0x80000000, 0], /* INT_MIN: unsigned jb NOT taken -> no */
    [0xe, 0x3e8, 0], /* pause field value blocks */
    [0xe, 0x3e7, 1],
    [0xe, 0xffffffff, 1],
    [3, 0, 0], /* not in set */
    [7, 0, 0],
    [0xd, 0, 0],
    [0x1b0, 0, 0],
  ];
  for (const [t, sf, want] of typeCases) {
    const js = frameEffect825730TypeOk(t, sf);
    assert.equal(js, want, `js type ${t.toString(16)}/${sf}`);
    const wasm = W.typeOk825730(t >>> 0, sf >>> 0) >>> 0;
    assert.equal(wasm, want, `wasm type ${t.toString(16)}/${sf}`);
  }

  /* full gate: [idx, has_entity, flag, type, sub, want] */
  const gateCases = [
    [0, 1, 1, 2, 0, 1],
    [0x1bf, 1, 1, 6, 0, 1], /* idx == max -> ok */
    [0x1c0, 1, 1, 6, 0, 0], /* idx > max (UNSIGNED ja) */
    [0x50, 0, 1, 2, 0, 0], /* null entity */
    [0x50, 1, 0, 2, 0, 0], /* flag zero */
    [0x50, 1, 1, 0xc, 4, 0], /* 0xc with sub==4 */
    [0x50, 1, 1, 0xc, 0x80000000, 0], /* INT_MIN >=u 4 -> no pickup */
    [0x50, 1, 1, 0xe, 0x3e8, 0], /* pause value */
    [0x50, 1, 1, 0xe, 5, 1],
    [0x80000000, 1, 1, 2, 0, 0], /* huge idx unsigned */
  ];
  for (const [ix, he, fl, t, sf, want] of gateCases) {
    const js = frameEffect825730Gate(ix, he, fl, t, sf);
    assert.equal(js, want, `js gate ${ix}/${t}`);
    const wasm =
      W.gate825730(ix >>> 0, he >>> 0, fl >>> 0, t >>> 0, sf >>> 0) >>> 0;
    assert.equal(wasm, want, `wasm gate ${ix}/${t}`);
  }
});

test("v43 mutants: break translation, fail, sha256-restore", () => {
  const original = readFileSync(source);
  const origHash = createHash("sha256").update(original).digest("hex");
  const text = original.toString("utf8");
  const crlf = text.includes("\r\n");
  const base = text.replaceAll("\r\n", "\n");
  const toFile = (s) => (crlf ? s.replaceAll("\n", "\r\n") : s);
  const shaOf = (buf) => createHash("sha256").update(buf).digest("hex");
  const writeRetry = (p, b) => {
    const t0 = Date.now();
    for (;;) {
      try {
        writeFileSync(p, b);
        return;
      } catch (e) {
        if (Date.now() - t0 > 8000) throw e;
      }
    }
  };
  const withMutant = (label, mutate, check) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeRetry(source, toFile(bad));
    let threw = false;
    try {
      const w = loadExports();
      check(w);
    } catch {
      threw = true;
    }
    writeRetry(source, original);
    assert.equal(shaOf(readFileSync(source)), origHash, `${label}: restore`);
    assert.ok(threw, `${label}: mutant survived`);
  };
  try {
    withMutant("v43 idx bound 0x1bf -> 0x1af",
      (s) => s.replace(
        "  if (idx > (uint32_t)ISAAC_FRAME_EFFECT_825730_IDX_MAX) {",
        "  if (idx > 0x1afu) {"),
      (w) => {
        assert.equal(w.gate825730(0x1bf, 1, 1, 2, 0) >>> 0, 1,
          "idx == 0x1bf accepted");
      });
    withMutant("v43 type set drops 0x1b",
      (s) => s.replace(
        "  if (t == 2u || t == 4u || t == 5u || t == 6u || t == 0x1au ||\n" +
        "      t == 0x16u || t == 0x1bu) {",
        "  if (t == 2u || t == 4u || t == 5u || t == 6u || t == 0x1au ||\n" +
        "      t == 0x16u || t == 0x1cu) {"),
      (w) => {
        assert.equal(w.typeOk825730(0x1b, 0) >>> 0, 1, "0x1b in set");
      });
    withMutant("v43 0xc sub compare SIGNED folded",
      (s) => s.replace(
        "    return (sub_field < (uint32_t)ISAAC_FRAME_EFFECT_825730_SUB_MIN) ? 1\n" +
        "                                                                     : 0;",
        "    return ((int32_t)sub_field <\n" +
        "            (int32_t)ISAAC_FRAME_EFFECT_825730_SUB_MIN)\n" +
        "               ? 1\n" +
        "               : 0;"),
      (w) => {
        assert.equal(w.typeOk825730(0xc, 0x80000000) >>> 0, 0,
          "INT_MIN not <u 4 -> no pickup (signed fold breaks this)");
      });
    withMutant("v43 0xe pause compare inverted",
      (s) => s.replace(
        "    return (sub_field ==\n" +
        "            (uint32_t)ISAAC_FRAME_EFFECT_825730_PAUSE_FIELD)\n" +
        "               ? 0\n" +
        "               : 1;",
        "    return (sub_field !=\n" +
        "            (uint32_t)ISAAC_FRAME_EFFECT_825730_PAUSE_FIELD)\n" +
        "               ? 0\n" +
        "               : 1;"),
      (w) => {
        assert.equal(w.typeOk825730(0xe, 0x3e7) >>> 0, 1,
          "non-pause value picks up");
      });
    withMutant("v43 gate drops flag check",
      (s) => s.replace(
        "  if (flag_nonzero == 0u) {\n" +
        "    return 0;\n" +
        "  }",
        "  if (false) {\n" +
        "    return 0;\n" +
        "  }"),
      (w) => {
        assert.equal(w.gate825730(0x50, 1, 0, 2, 0) >>> 0, 0,
          "flag zero -> no pickup");
      });
  } finally {
    writeRetry(source, original);
    assert.equal(shaOf(readFileSync(source)), origHash, "final restore");
  }
});

/* ------------------------------------------------------------------ */
/* ABI v44: FUN_00827180 nearest-slot scan                             */
/* ------------------------------------------------------------------ */

/* v48 scratch sits above v32's packOut (0x1f5000). 0x1f6000+ is fresh:
   24 dwords — 8 x {present, px_bits, py_bits}. */
const V48_SLOTS = 0x1f6000;

function normRows48(rows) {
  const out = [];
  for (let i = 0; i < FRAME_EFFECT_827180_SLOT_COUNT; i += 1) {
    const r = rows[i] ?? [0, 0, 0];
    out.push({ present: r[0] ?? 0, px: r[1] ?? 0, py: r[2] ?? 0 });
  }
  return out;
}

function setSlots48(memory, base, norm) {
  for (let i = 0; i < norm.length; i += 1) {
    setU32(memory, base + i * 12 + 0, norm[i].present);
    setU32(memory, base + i * 12 + 4, norm[i].px);
    setU32(memory, base + i * 12 + 8, norm[i].py);
  }
}

