/* ABI v45: FUN_008279c0 field+0x20 getter                             */
/* ------------------------------------------------------------------ */

test("v45 0x008279c0 getter census + wasm-vs-oracle", () => {
  assert.equal(W.abi(), 51);
  assert.equal(FRAME_EFFECT_PURE_ABI_VERSION, 51);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_PURE_HELPERS_ABI_VERSION = 51/);
  assert.equal(FRAME_EFFECT_8279C0_VA, 0x008279c0);
  assert.equal(FRAME_EFFECT_8279C0_RET_VA, 0x008279cd);
  assert.equal(FRAME_EFFECT_8279C0_END_VA, 0x008279ce);
  assert.equal(FRAME_EFFECT_8279C0_NEXT_VA, 0x008279d0);
  assert.equal(FRAME_EFFECT_8279C0_INSN_COUNT, 3);
  assert.equal(FRAME_EFFECT_8279C0_BYTE_LEN, 14);
  assert.equal(FRAME_EFFECT_8279C0_FIELD_OFF, 0x20);
  assert.equal(FRAME_EFFECT_8279C0_CONST_VA, 0x00baa8d0);
  assert.equal(FRAME_EFFECT_8279C0_CONST_BITS, 0x41f00000); /* 30.0f */
  assert.equal(FRAME_EFFECT_8279C0_DIRECT_CALLERS, 6);
  assert.match(HDR, /isaac_frame_effect_8279c0_field20_sub30/);
  /* family low-byte discipline: full-dword raw bits in, no uint8_t. */
  assert.doesNotMatch(HDR, /uint8_t isaac_frame_effect_8279c0/);

  /* Draw budget: ZERO randomized draws (suite carries 496, cap 500) —
     deterministic edge matrix. Results compared via RAW BITS so NaN
     and -0 are exact. */
  const b48 = f32ToBits;
  const cases = [
    [b48(40), b48(10)],        /* exact */
    [b48(30), b48(0)],        /* +0 result */
    [b48(30.5), b48(0.5)],
    [b48(29.5), b48(-0.5)],
    [b48(0), b48(-30)],
    [0x80000000, b48(-30)],    /* -0 base: -0 - 30 = -30 */
    [b48(1e-45 >>> 0), b48(-30)], /* min denormal rounds to -30 */
    [0x00000001, b48(-30)],    /* min denormal BITS */
    [0x7f800000, 0x7f800000],  /* +inf - 30 = +inf */
    [0xff800000, 0xff800000],  /* -inf */
    [0x7fc00000, 0x7fc00000],  /* NaN propagates (quiet) */
    [b48(3.4e38), b48(3.4e38)], /* huge: 30 vanishes */
    [b48(1e-6), f32ToBits(-29.999999)], /* tiny below rounding step */
  ];
  for (const [base, want] of cases) {
    const js = f32ToBits(frameEffect8279c0Field20Sub30(base >>> 0));
    assert.equal(js, want >>> 0, `js getter ${base.toString(16)}`);
    const wasm =
      f32ToBits(W.field20Sub308279c0(base >>> 0)) >>> 0;
    assert.equal(wasm, want >>> 0, `wasm getter ${base.toString(16)}`);
  }
});

