test("v46 0x00827b70 window-gate census + wasm-vs-oracle", () => {
  assert.equal(W.abi(), 51);
  assert.equal(FRAME_EFFECT_PURE_ABI_VERSION, 51);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_PURE_HELPERS_ABI_VERSION = 51/);
  assert.equal(FRAME_EFFECT_827B70_VA, 0x00827b70);
  assert.equal(FRAME_EFFECT_827B70_RET_VA, 0x00827ba3);
  assert.equal(FRAME_EFFECT_827B70_END_VA, 0x00827ba7);
  assert.equal(FRAME_EFFECT_827B70_INSN_COUNT, 20);
  assert.equal(FRAME_EFFECT_827B70_BYTE_LEN, 55);
  assert.equal(FRAME_EFFECT_827B70_GAME_GLOBAL_VA, 0x00c71678);
  assert.equal(FRAME_EFFECT_827B70_TRANSITION_MODE_OFF, 0x1830c);
  assert.equal(FRAME_EFFECT_827B70_TRANSITION_MODE_VALUE, 1);
  assert.equal(FRAME_EFFECT_827B70_MODE_OFF, 0x4);
  assert.equal(FRAME_EFFECT_827B70_STAGE_OFF, 0x0);
  assert.equal(FRAME_EFFECT_827B70_HOST_VA, 0x00748490);
  assert.equal(FRAME_EFFECT_827B70_HOST_BIT_MASK, 0x2);
  assert.equal(FRAME_EFFECT_827B70_DIRECT_CALLERS, 6);
  assert.match(HDR, /isaac_frame_effect_827b70_gate/);
  /* family low-byte discipline: full-dword args, no uint8_t law. */
  assert.doesNotMatch(HDR, /uint8_t isaac_frame_effect_827b70/);

  /* Draw budget: ZERO randomized draws (suite carries 496, cap 500) —
     deterministic edge matrix. FULL-dword discipline pins included. */
  const gateCases = [
    [1, 4, 2, 0, 1],          // stage 2 shortcut (host bit ignored)
    [1, 5, 2, 0, 1],          // mode window edge 5
    [1, 4, 1, 1, 1],          // stage 1 + host bit set
    [1, 4, 1, 0, 0],          // stage 1 without host bit
    [1, 5, 1, 1, 1],
    [0, 4, 2, 0, 0],          // transition_mode != 1 -> fail FIRST
    [0, 4, 1, 1, 0],
    [2, 4, 2, 0, 0],          // FULL dword transition compare
    [1, 3, 2, 0, 0],          // below mode window
    [1, 6, 1, 1, 0],          // above mode window
    [1, 0x80000004, 2, 0, 0], // FULL dword mode compare
    [1, 4, 3, 1, 0],          // stage above window
    [1, 4, 0, 1, 0],          // stage 0
    [1, 4, 0x80000001, 1, 0], // FULL dword stage compare
  ];
  for (const [tm, m, st, hb, want] of gateCases) {
    const js = frameEffect827b70Gate(tm >>> 0, m >>> 0, st >>> 0, hb | 0);
    assert.equal(js, want, `js gate ${tm}/${m}/${st}/${hb}`);
    const wasm =
      W.gate827b70(tm >>> 0, m >>> 0, st >>> 0, hb | 0) >>> 0;
    assert.equal(wasm, want, `wasm gate ${tm}/${m}/${st}/${hb}`);
  }
});

