test("v47 0x00827bb0 HasCurseMist census + wasm-vs-oracle", () => {
  assert.equal(W.abi(), 51);
  assert.equal(FRAME_EFFECT_PURE_ABI_VERSION, 51);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_PURE_HELPERS_ABI_VERSION = 51/);
  assert.equal(FRAME_EFFECT_827BB0_VA, 0x00827bb0);
  assert.equal(FRAME_EFFECT_827BB0_RET_VA, 0x00827bbb);
  assert.equal(FRAME_EFFECT_827BB0_END_VA, 0x00827bbc);
  assert.equal(FRAME_EFFECT_827BB0_NEXT_VA, 0x00827bc0);
  assert.equal(FRAME_EFFECT_827BB0_INSN_COUNT, 5);
  assert.equal(FRAME_EFFECT_827BB0_BYTE_LEN, 12);
  assert.equal(FRAME_EFFECT_827BB0_DESC_PTR_OFF, 0x4);
  assert.equal(FRAME_EFFECT_827BB0_FLAGS_OFF, 0x44);
  assert.equal(FRAME_EFFECT_827BB0_BIT_INDEX, 13);
  assert.equal(FRAME_EFFECT_827BB0_DIRECT_CALLERS, 1);
  assert.equal(FRAME_EFFECT_827BB0_DISPATCH_REF_VA, 0x0086ca2b);
  assert.match(HDR, /isaac_frame_effect_827bb0_flag_bit13/);
  /* family low-byte discipline: full-dword flags, no uint8_t law. */
  assert.doesNotMatch(HDR, /uint8_t isaac_frame_effect_827bb0/);

  /* Draw budget: ZERO randomized draws (suite carries 496, cap 500) —
     deterministic edge matrix. Distinguishing pins vs landed bit 9
     (v39) and bit 5 (v41) included. */
  const bitCases = [
    [0x00000000, 0],          // clear
    [0x00002000, 1],          // bit 13 exactly (Curse of Mist)
    [0xffffffff, 1],          // all bits set
    [0x80000000, 0],          // bit 31 only -> >>13 has bit18, &1=0
    [0xffffdfff, 0],          // every bit EXCEPT 13
    [0x00000200, 0],          // bit 9 ONLY (landed v39 flag) -> 0
    [0x00000020, 0],          // bit 5 ONLY (landed v41 gate) -> 0
    [0x00002200, 1],          // bits 9|13 -> still 1
    [0x00001000, 0],          // bit 12 neighbor
    [0x00004000, 0],          // bit 14 neighbor
    [0x00001001, 0],          // bit12|bit0
  ];
  for (const [flags, want] of bitCases) {
    const js = frameEffect827bb0FlagBit13(flags >>> 0);
    assert.equal(js, want, `js bit ${flags.toString(16)}`);
    const wasm = W.flagBit13827bb0(flags >>> 0) >>> 0;
    assert.equal(wasm, want, `wasm bit ${flags.toString(16)}`);
  }
});

