test("v48 0x00827bc0 window-gate census + wasm-vs-oracle", () => {
  assert.equal(W.abi(), 51);
  assert.equal(FRAME_EFFECT_PURE_ABI_VERSION, 51);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_PURE_HELPERS_ABI_VERSION = 51/);
  assert.equal(FRAME_EFFECT_827BC0_VA, 0x00827bc0);
  assert.equal(FRAME_EFFECT_827BC0_RET_VA, 0x00827be3);
  assert.equal(FRAME_EFFECT_827BC0_END_VA, 0x00827be7);
  assert.equal(FRAME_EFFECT_827BC0_INSN_COUNT, 14);
  assert.equal(FRAME_EFFECT_827BC0_BYTE_LEN, 39);
  assert.equal(FRAME_EFFECT_827BC0_FIELD8_OFF, 0x8);
  assert.equal(FRAME_EFFECT_827BC0_FIELD8_VALUE, 5);
  assert.equal(FRAME_EFFECT_827BC0_DESC_PTR_OFF, 0x4);
  assert.equal(FRAME_EFFECT_827BC0_LIST_OFF, 0x10);
  assert.equal(FRAME_EFFECT_827BC0_TYPE_OFF, 0x10);
  assert.equal(FRAME_EFFECT_827BC0_TYPE_VALUE, 0x59);
  assert.equal(FRAME_EFFECT_827BC0_HOST_VA, 0x0074ea50);
  assert.equal(FRAME_EFFECT_827BC0_DIRECT_CALLERS, 3);
  assert.match(HDR, /isaac_frame_effect_827bc0_gate/);
  /* family low-byte discipline: full-dword args, no uint8_t law. */
  assert.doesNotMatch(HDR, /uint8_t isaac_frame_effect_827bc0/);

  /* Draw budget: ZERO randomized draws (suite carries 496, cap 500) —
     deterministic edge matrix. FULL-dword discipline pins included. */
  const gateCases = [
    [5, 0x59, 1, 1],          // all three gates pass
    [5, 0x59, 0, 0],          // host rejects
    [4, 0x59, 1, 0],          // field8 below window
    [6, 0x59, 1, 0],          // field8 above window
    [5, 0x58, 1, 0],          // type neighbor below
    [5, 0x5a, 1, 0],          // type neighbor above
    [5, 0, 1, 0],
    [0, 0x59, 1, 0],          // field8 zero
    [0x80000005, 0x59, 1, 0], // FULL dword field8 compare
    [5, 0x80000059, 1, 0],    // FULL dword type compare
  ];
  for (const [f8, dt, hp, want] of gateCases) {
    const js = frameEffect827bc0Gate(f8 >>> 0, dt >>> 0, hp | 0);
    assert.equal(js, want, `js gate ${f8}/${dt}/${hp}`);
    const wasm = W.gate827bc0(f8 >>> 0, dt >>> 0, hp | 0) >>> 0;
    assert.equal(wasm, want, `wasm gate ${f8}/${dt}/${hp}`);
  }
});

