/* ------------------------------------------------------------------ */
/* ABI v49: FUN_00829920 record move-copy                              */
/* ------------------------------------------------------------------ */

/* v49 scratch sits above v39's planBuf (0x1f7054). 0x1f8000+ is fresh;
   the whole 0x500-byte window is pattern-seeded per case. */
const V49_WIN = 0x1f8000;
const V49_SCRATCH = {
  dst: 0x1f8000,     /* 0x5c B — destination record */
  src: 0x1f8100,     /* 0x5c B — source record */
  overlap: 0x1f80f0, /* dst for the dst = src - 0x10 overlap case */
};
const V49_REC_BYTES = 0x5c;

/* Deterministic record image (23 dwords). `kind` picks the SSO string
 * state; every other dword gets byte-diverse pattern bits so the
 * word/byte-split tail stores are observable. */
function v49Image(kind) {
  const d = new Uint32Array(23);
  for (let i = 0; i < 23; i += 1) {
    d[i] = ((i * 0x2f) ^ 0x5a5aa5a5) >>> 0;
  }
  if (kind === "sso15") {
    d[5] = 0;
    d[6] = 0;
    d[7] = 0;
    d[8] = 0;
    for (let i = 0; i < 16; i += 1) {
      d[5 + (i >> 2)] |= (0x61 + i) << (8 * (i & 3));
    }
    d[9] = 15; /* size: SSO boundary; the law never terminates */
    d[10] = 0xf;
  } else if (kind === "heap") {
    d[5] = 0xdeadbeef; /* pointer-looking bits: law must NOT deref */
    d[6] = 0x13579bdf;
    d[7] = 0x2468ace0;
    d[8] = 0xfedcba98;
    d[9] = 0x20;
    d[10] = 0x3f;
  } else if (kind === "empty") {
    d[5] = 0;
    d[6] = 0x11111111;
    d[9] = 0;
    d[10] = 0xf;
  } else {
    throw new Error(`v49Image kind ${kind}`);
  }
  return d;
}

/* Seed both sides identically: full-window byte pattern + record
 * image written at `base` (the source slot of the case). */
function v49Seed(dv, winBase, imgBase, kind) {
  for (let i = 0; i < 0x500; i += 1) {
    dv.setUint8(winBase + i, (i * 0x37 + 0x0d) & 0xff);
  }
  const words = v49Image(kind);
  for (let i = 0; i < 23; i += 1) {
    dv.setUint32(imgBase + 4 * i, words[i] >>> 0, true);
  }
}

test("v49 0x00829920 record-move census + wasm-vs-oracle", () => {
  assert.equal(W.abi(), 51);
  assert.equal(FRAME_EFFECT_PURE_ABI_VERSION, 51);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_PURE_HELPERS_ABI_VERSION = 51/);
  assert.equal(FRAME_EFFECT_829920_VA, 0x00829920);
  assert.equal(FRAME_EFFECT_829920_RET_VA, 0x008299da);
  assert.equal(FRAME_EFFECT_829920_END_VA, 0x008299dd);
  assert.equal(FRAME_EFFECT_829920_NEXT_VA, 0x008299e0);
  assert.equal(FRAME_EFFECT_829920_INSN_COUNT, 57);
  assert.equal(FRAME_EFFECT_829920_BYTE_LEN, 189);
  assert.equal(FRAME_EFFECT_829920_REC_SIZE, 0x5c);
  assert.equal(FRAME_EFFECT_829920_STRING_OFF, 0x14);
  assert.equal(FRAME_EFFECT_829920_SIZE_OFF, 0x24);
  assert.equal(FRAME_EFFECT_829920_CAP_OFF, 0x28);
  assert.equal(FRAME_EFFECT_829920_SSO_CAP_RESET, 0xf);
  assert.equal(FRAME_EFFECT_829920_DIRECT_CALLERS, 2);
  assert.match(HDR, /isaac_frame_effect_829920_record_move/);

  /* Differential harness: wasm runs in scratch; the JS oracle runs on
     its OWN buffer seeded with the same pre-state at the same offsets.
     Byte-exact compare over both records after the call. ZERO lcg
     draws (suite carries 496, cap 500). */
  const v49Run = (dst, src, kind) => {
    v49Seed(new DataView(W.memory.buffer), V49_WIN, src, kind);
    const ret = W.recordMove829920(dst, src) >>> 0;
    /* JS oracle on its OWN window, same relative layout. */
    const jsBuf = new Uint8Array(0x500);
    v49Seed(new DataView(jsBuf.buffer), 0, src - V49_WIN, kind);
    const jsRet = frameEffect829920RecordMove(
      jsBuf, dst - V49_WIN, src - V49_WIN);
    const slice = (mem, base, len) =>
      new Uint8Array(mem.buffer.slice(base, base + len));
    return {
      ret,
      jsRet,
      wD: slice(W.memory, dst, V49_REC_BYTES),
      wS: slice(W.memory, src, V49_REC_BYTES),
      jD: jsBuf.slice(dst - V49_WIN, dst - V49_WIN + V49_REC_BYTES),
      jS: jsBuf.slice(src - V49_WIN, src - V49_WIN + V49_REC_BYTES),
      mem: W.memory,
      src,
    };
  };

  const cases = [
    ["distinct sso15", V49_SCRATCH.dst, V49_SCRATCH.src, "sso15"],
    ["distinct heap", V49_SCRATCH.dst, V49_SCRATCH.src, "heap"],
    ["distinct empty", V49_SCRATCH.dst, V49_SCRATCH.src, "empty"],
    ["self-move", V49_SCRATCH.src, V49_SCRATCH.src, "sso15"],
    ["overlap dst=src-0x10", V49_SCRATCH.overlap, V49_SCRATCH.src,
      "heap"],
  ];
  for (const [label, dst, src, kind] of cases) {
    const r = v49Run(dst, src, kind);
    assert.equal(r.ret, dst >>> 0, `${label}: wasm ret`);
    assert.equal(r.jsRet, (dst - V49_WIN) >>> 0,
      `${label}: js ret`);
    assert.deepEqual(Buffer.from(r.wD), Buffer.from(r.jD),
      `${label}: dst bytes`);
    assert.deepEqual(Buffer.from(r.wS), Buffer.from(r.jS),
      `${label}: src bytes`);
  }

  /* Semantic pins straight off the machine semantics (oracle-free): */
  let p = v49Run(V49_SCRATCH.dst, V49_SCRATCH.src, "sso15");
  let dv = new DataView(p.mem.buffer);
  assert.equal(dv.getUint32(V49_SCRATCH.dst + 0x24, true), 15,
    "dst inherits SSO size 15");
  assert.equal(dv.getUint32(V49_SCRATCH.dst + 0x28, true), 0xf,
    "dst inherits cap");
  assert.equal(dv.getUint32(V49_SCRATCH.src + 0x24, true), 0,
    "src size reset");
  assert.equal(dv.getUint32(V49_SCRATCH.src + 0x28, true), 0xf,
    "src cap reset to SSO 0xf");
  assert.equal(dv.getUint8(V49_SCRATCH.src + 0x14), 0,
    "src buf[0] reset");
  assert.equal(
    dv.getUint8(V49_SCRATCH.src + 0x15), 0x62,
    "src buf[1] preserved (only buf[0] reset)");
  assert.equal(dv.getUint32(V49_SCRATCH.dst + 0x58, true),
    ((22 * 0x2f) ^ 0x5a5aa5a5) >>> 0,
    "tail dword +0x58 copied");

  /* self-move: zero-stores precede the reloads -> buf[0..3] read back
     as zero; everything else except the string reset survives. */
  p = v49Run(V49_SCRATCH.src, V49_SCRATCH.src, "sso15");
  dv = new DataView(p.mem.buffer);
  assert.equal(dv.getUint32(V49_SCRATCH.src + 0x10, true),
    ((4 * 0x2f) ^ 0x5a5aa5a5) >>> 0,
    "self-move keeps dst[+0x10] (head copy no-op)");
  assert.equal(dv.getUint32(V49_SCRATCH.src + 0x14, true), 0,
    "self-move zeroes buf[0..3]");
  assert.equal(
    dv.getUint8(V49_SCRATCH.src + 0x18), 0x65,
    "self-move preserves buf[4..15]");
  assert.equal(dv.getUint32(V49_SCRATCH.src + 0x40, true),
    ((16 * 0x2f) ^ 0x5a5aa5a5) >>> 0,
    "self-move preserves +0x40");

  /* null guards: no writes, PE-shaped identity returns */
  assert.equal(W.recordMove829920(0, V49_SCRATCH.src) >>> 0, 0,
    "null dst returns 0");
  assert.equal(
    W.recordMove829920(V49_SCRATCH.dst, 0) >>> 0,
    V49_SCRATCH.dst, "null src returns dst");
});

test("v49 mutants: break translation, fail, sha256-restore", () => {
  const original = readFileSync(source);
  const origHash = createHash("sha256").update(original).digest("hex");
  const text = original.toString("utf8");
  const crlf = text.includes("\r\n");
  const base = text.replaceAll("\r\n", "\n");
  const toFile = (s) => (crlf ? s.replaceAll("\n", "\r\n") : s);
  const shaOf = (buf) => createHash("sha256").update(buf).digest("hex");
  const writeRetry = (p, buf) => {
    const t0 = Date.now();
    for (;;) {
      try {
        writeFileSync(p, buf);
        return;
      } catch (e) {
        if (Date.now() - t0 > 8000) throw e;
      }
    }
  };
  const withMutant = (label, mutate, check) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeRetry(source, toFile(bad));
    let threw = false;
    try {
      const w = loadExports();
      check(w);
    } catch {
      threw = true;
    }
    writeRetry(source, original);
    assert.equal(shaOf(readFileSync(source)), origHash, `${label}: restore`);
    assert.ok(threw, `${label}: mutant survived`);
  };
  try {
    withMutant("v49 SSO cap reset bumped to 0x10",
      (s) => s.replace(
        "  ((int32_t *)src)[10] =\n" +
        "      (int32_t)ISAAC_FRAME_EFFECT_829920_SSO_CAP_RESET;",
        "  ((int32_t *)src)[10] =\n" +
        "      (int32_t)ISAAC_FRAME_EFFECT_829920_SSO_CAP_RESET + 1;"),
      (w) => {
        const dv = new DataView(w.memory.buffer);
        w.recordMove829920(V49_SCRATCH.dst, V49_SCRATCH.src);
        assert.equal(dv.getUint32(V49_SCRATCH.src + 0x28, true), 0xf,
          "src cap must reset to 0xf");
      });
    withMutant("v49 src buf[0] reset writes 0x41",
      (s) => s.replace(
        "((unsigned char *)src)[ISAAC_FRAME_EFFECT_829920_STRING_OFF]" +
        " = 0;",
        "((unsigned char *)src)[ISAAC_FRAME_EFFECT_829920_STRING_OFF]" +
        " = 0x41;"),
      (w) => {
        const dv = new DataView(w.memory.buffer);
        w.recordMove829920(V49_SCRATCH.dst, V49_SCRATCH.src);
        assert.equal(dv.getUint8(V49_SCRATCH.src + 0x14), 0,
          "src buf[0] must be 0");
      });
    withMutant("v49 self-move zero-store dropped",
      (s) => s.replace(
        "  dst[5] = 0;  /* +0x14 dword zeroed before the reload below */",
        "  /* dst[5] = 0; dropped */"),
      (w) => {
        const jBuf = new Uint8Array(0x500);
        v49Seed(new DataView(w.memory.buffer), V49_WIN,
          V49_SCRATCH.src, "sso15");
        v49Seed(new DataView(jBuf.buffer), 0,
          V49_SCRATCH.src - V49_WIN, "sso15");
        w.recordMove829920(V49_SCRATCH.src, V49_SCRATCH.src);
        frameEffect829920RecordMove(
          jBuf, V49_SCRATCH.src - V49_WIN, V49_SCRATCH.src - V49_WIN);
        const wWin = new Uint8Array(w.memory.buffer.slice(
          V49_WIN, V49_WIN + 0x500));
        assert.deepEqual(
          Buffer.from(wWin.slice(
            V49_SCRATCH.src - V49_WIN,
            V49_SCRATCH.src - V49_WIN + V49_REC_BYTES)),
          Buffer.from(jBuf.slice(
            V49_SCRATCH.src - V49_WIN,
            V49_SCRATCH.src - V49_WIN + V49_REC_BYTES)),
          "self-move byte-exact vs oracle");
      });
    withMutant("v49 word tail reads +0x46 instead of +0x44",
      (s) => s.replace(
        "  ((uint16_t *)&dst[17])[0] = ((const uint16_t *)&src[17])[0];",
        "  ((uint16_t *)&dst[17])[0] = ((const uint16_t *)&src[17])[1];"),
      (w) => {
        const dv = new DataView(w.memory.buffer);
        for (let i = 0; i < 0x200; i++) {
          dv.setUint8(V49_SCRATCH.src + i, (i * 0x37 + 0x0d) & 0xff);
        }
        const words = v49Image("empty");
        for (let i = 0; i < 23; i++) {
          dv.setUint32(V49_SCRATCH.src + 4 * i, words[i] >>> 0, true);
        }
        w.recordMove829920(V49_SCRATCH.dst, V49_SCRATCH.src);
        assert.equal(dv.getUint16(V49_SCRATCH.dst + 0x44, true),
          dv.getUint16(V49_SCRATCH.src + 0x44, true),
          "word +0x44 must come from src +0x44");
      });
    withMutant("v49 final return yields 0",
      (s) => s.replace(
        "  dst[22] = src[22];\n  return (int32_t)(uintptr_t)dst;",
        "  dst[22] = src[22];\n  return 0;"),
      (w) => {
        assert.equal(
          w.recordMove829920(V49_SCRATCH.dst, V49_SCRATCH.src) >>> 0,
          V49_SCRATCH.dst, "must return dst bits");
      });
  } finally {
    writeRetry(source, original);
    assert.equal(shaOf(readFileSync(source)), origHash, "final restore");
  }
});
/* ------------------------------------------------------------------ */
/* ABI v50: FUN_008299e0 signed-word pair strict-less                  */
/* ------------------------------------------------------------------ */

test("v50 0x008299e0 pair-less census + wasm-vs-oracle", () => {
  assert.equal(W.abi(), 51);
  assert.equal(FRAME_EFFECT_PURE_ABI_VERSION, 51);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_PURE_HELPERS_ABI_VERSION = 51/);
  assert.equal(FRAME_EFFECT_8299E0_VA, 0x008299e0);
  assert.equal(FRAME_EFFECT_8299E0_RET_FALSE_VA, 0x00829a05);
  assert.equal(FRAME_EFFECT_8299E0_RET_TRUE_VA, 0x00829a0a);
  assert.equal(FRAME_EFFECT_8299E0_END_VA, 0x00829a0b);
  assert.equal(FRAME_EFFECT_8299E0_NEXT_VA, 0x00829a10);
  assert.equal(FRAME_EFFECT_8299E0_BYTE_LEN, 43);
  assert.equal(FRAME_EFFECT_8299E0_HIGH_OFF, 0x2);
  assert.equal(FRAME_EFFECT_8299E0_DIRECT_CALLERS, 0);
  assert.equal(FRAME_EFFECT_8299E0_RAW_REF_VA, 0x00429c39);
  assert.match(HDR, /isaac_frame_effect_8299e0_pair_less/);

  /* Deterministic edge matrix; ZERO lcg draws (496/500 budget). Both
     compares are SIGNED 16-bit — high half first, low tiebreak. */
  const cases = [
    [0x00010000, 0x00020000, 1],   /* hi 1 < 2 -> jl TRUE */
    [0x00020000, 0x00010000, 0],   /* hi 2 > 1 -> ne early-out false */
    [0x00020001, 0x00020000, 0],   /* hi eq; lo 1 < 0 false */
    [0x00020100, 0x0002ffff, 0],   /* lo 256 < -1 false (SIGNED) */
    [0x0002ffff, 0x00020001, 1],   /* lo -1 < 1 true (SIGNED) */
    [0xffff0000, 0x00010000, 1],   /* hi -1 < 1 SIGNED */
    [0x80000000, 0x7fff0000, 1],   /* hi -32768 < 32767 */
    [0x7fff0000, 0x80000000, 0],   /* hi 32767 < -32768 false */
    [0x12345678, 0x12345678, 0],   /* full equal */
    [0x00008000, 0x00007fff, 1],   /* lo SIGNED -32768 < 32767 */
    [0x00008000, 0x00008000, 0],
    [0xffffffff, 0xfffffffe, 0],   /* hi equal -1; lo -1 < -2 false */
    [0xfffffffe, 0xffffffff, 1],
  ];
  for (const [a, b, want] of cases) {
    const js = frameEffect8299e0PairLess(a >>> 0, b >>> 0);
    assert.equal(js, want, `js ${a.toString(16)} vs ${b.toString(16)}`);
    const wasm =
      W.pairLess8299e0(a >>> 0, b >>> 0) & 1;
    assert.equal(wasm, want,
      `wasm ${(a >>> 0).toString(16)} vs ${(b >>> 0).toString(16)}`);
  }
});

test("v50 mutants: break translation, fail, sha256-restore", () => {
  const original = readFileSync(source);
  const origHash = createHash("sha256").update(original).digest("hex");
  const text = original.toString("utf8");
  const crlf = text.includes("\r\n");
  const base = text.replaceAll("\r\n", "\n");
  const toFile = (s) => (crlf ? s.replaceAll("\n", "\r\n") : s);
  const shaOf = (buf) => createHash("sha256").update(buf).digest("hex");
  const writeRetry = (p, buf) => {
    const t0 = Date.now();
    for (;;) {
      try {
        writeFileSync(p, buf);
        return;
      } catch (e) {
        if (Date.now() - t0 > 8000) throw e;
      }
    }
  };
  const withMutant = (label, mutate, check) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeRetry(source, toFile(bad));
    let threw = false;
    try {
      const w = loadExports();
      check(w);
    } catch {
      threw = true;
    }
    writeRetry(source, original);
    assert.equal(shaOf(readFileSync(source)), origHash, `${label}: restore`);
    assert.ok(threw, `${label}: mutant survived`);
  };
  try {
    withMutant("v50 high compare loses signedness",
      (s) => s.replace(
        "  int16_t a_hi = (int16_t)(a >> 16);\n" +
        "  int16_t b_hi = (int16_t)(b >> 16);",
        "  uint16_t a_hi = (uint16_t)(a >> 16);\n" +
        "  uint16_t b_hi = (uint16_t)(b >> 16);"),
      (w) => {
        assert.equal(w.pairLess8299e0(0xffff0000, 0x00010000) & 1, 1,
          "hi word 0xffff is SIGNED -1");
      });
    withMutant("v50 low tiebreak inverted",
      (s) => s.replace(
        "  return ((int16_t)a < (int16_t)b) ? 1 : 0;",
        "  return ((int16_t)a > (int16_t)b) ? 1 : 0;"),
      (w) => {
        assert.equal(w.pairLess8299e0(0x00020001, 0x00020200) & 1, 1,
          "lo 1 < 512 must be true");
      });
    withMutant("v50 ne early-out flipped",
      (s) => s.replace(
        "  if (a_hi != b_hi) {\n    return 0;\n  }",
        "  if (a_hi == b_hi) {\n    return 0;\n  }"),
      (w) => {
        assert.equal(w.pairLess8299e0(0x0003ffff, 0x00010000) & 1, 0,
          "hi greater must stay false even with lo -1 < 0");
      });
    withMutant("v50 operands swapped on high compare",
      (s) => s.replace(
        "  if (a_hi < b_hi) {",
        "  if (b_hi < a_hi) {"),
      (w) => {
        assert.equal(w.pairLess8299e0(0x00010000, 0x00020000) & 1, 1,
          "a below b must be true");
      });
  } finally {
    writeRetry(source, original);
    assert.equal(shaOf(readFileSync(source)), origHash, "final restore");
  }
});

/* ------------------------------------------------------------------ */
/* ABI v51: FUN_00829a10 stage/mode/variant -> result map              */
/* ------------------------------------------------------------------ */

test("v51 0x00829a10 stage-mode map census + wasm-vs-oracle", () => {
  assert.equal(W.abi(), 51);
  assert.equal(FRAME_EFFECT_PURE_ABI_VERSION, 51);
  assert.match(HDR, /ISAAC_FRAME_EFFECT_PURE_HELPERS_ABI_VERSION = 51/);
  assert.equal(FRAME_EFFECT_829A10_VA, 0x00829a10);
  assert.equal(FRAME_EFFECT_829A10_END_VA, 0x00829ad4);
  assert.equal(FRAME_EFFECT_829A10_NEXT_VA, 0x00829af0);
  assert.equal(FRAME_EFFECT_829A10_INSN_COUNT, 85);
  assert.equal(FRAME_EFFECT_829A10_BYTE_LEN, 196);
  assert.equal(FRAME_EFFECT_829A10_RET_COUNT, 10);
  assert.equal(FRAME_EFFECT_829A10_DIRECT_CALLERS, 4);
  assert.equal(FRAME_EFFECT_829A10_FAIL_RET, -1);
  assert.match(HDR, /isaac_frame_effect_829a10_stage_mode_map/);

  /* Every ret arm + shared default. ZERO lcg draws (496/500). */
  const cases = [
    /* ecx in {-1,12}: */
    [-1, 3, 7, 0], [12, 3, 0, 0], [-1, 10, 5, 4], [12, 10, 9, 4],
    [-1, 5, 1, -1], [12, 0, 99, -1],
    /* ecx == 6: */
    [6, -1, 42, 1], [6, 14, 11, 1], [6, 14, 12, 3], [6, 14, 0, 3],
    [6, 6, 9, 1], [6, 6, 8, -1], [6, 6, 10, -1], [6, 7, 77, 3],
    [6, 2, 11, -1],
    /* ecx == 19: */
    [19, -1, 0, 5], [19, 14, 12, 5], [19, 14, 13, 7], [19, 14, 1, 7],
    [19, 6, 10, 5], [19, 6, 11, -1], [19, 7, 3, 7], [19, 15, 2, -1],
    /* ecx in {13,26}: */
    [13, 3, 4, 2], [26, 3, 4, 2], [13, 10, 8, 6], [26, 10, 8, 6],
    [13, 4, 0, -1], [26, 11, 0, -1], [13, 6, 9, -1],
    /* untouched stages: */
    [0, 3, 0, -1], [5, 10, 9, -1], [7, 6, 9, -1], [25, 3, 1, -1],
    [27, 10, 2, -1], [-2, 3, 0, -1],
  ];
  for (const [st, md, va, want] of cases) {
    const js = frameEffect829a10StageModeMap(st, md, va);
    assert.equal(js, want, `js ${st}/${md}/${va}`);
    const wasm = W.stageMode829a10(st, md, va);
    assert.equal(wasm, want, `wasm ${st}/${md}/${va}`);
  }
});

test("v51 mutants: break translation, fail, sha256-restore", () => {
  const original = readFileSync(source);
  const origHash = createHash("sha256").update(original).digest("hex");
  const text = original.toString("utf8");
  const crlf = text.includes("\r\n");
  const base = text.replaceAll("\r\n", "\n");
  const toFile = (s) => (crlf ? s.replaceAll("\n", "\r\n") : s);
  const shaOf = (buf) => createHash("sha256").update(buf).digest("hex");
  const writeRetry = (p, buf) => {
    const t0 = Date.now();
    for (;;) {
      try {
        writeFileSync(p, buf);
        return;
      } catch (e) {
        if (Date.now() - t0 > 8000) throw e;
      }
    }
  };
  const withMutant = (label, mutate, check) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeRetry(source, toFile(bad));
    let threw = false;
    try {
      const w = loadExports();
      check(w);
    } catch {
      threw = true;
    }
    writeRetry(source, original);
    assert.equal(shaOf(readFileSync(source)), origHash, `${label}: restore`);
    assert.ok(threw, `${label}: mutant survived`);
  };
  try {
    withMutant("v51 stage-6 result shifted 1 -> 2",
      (s) => s.replace(
        "    if (mode == -1) {\n        return 1;\n      }\n      if (variant != 11) {",
        "    if (mode == -1) {\n        return 2;\n      }\n      if (variant != 11) {"),
      (w) => {
        assert.equal(w.stageMode829a10(6, -1, 42), 1,
          "stage 6 mode -1 must yield 1");
      });
    withMutant("v51 variant gate 11 widened to 12",
      (s) => s.replace(
        "      if (variant != 11) {\n        return 3;\n      }\n      return 1;",
        "      if (variant != 12) {\n        return 3;\n      }\n      return 1;"),
      (w) => {
        assert.equal(w.stageMode829a10(6, 14, 11), 1,
          "variant 11 must take the ==11 arm");
      });
    withMutant("v51 mode transform edx-6 becomes edx-5",
      (s) => s.replace(
        "      if (mode == 10) {\n        result = mode - 6;\n      }",
        "      if (mode == 10) {\n        result = mode - 5;\n      }"),
      (w) => {
        assert.equal(w.stageMode829a10(12, 10, 0), 4,
          "{-1,12}x10 transform is mode-6");
      });
    withMutant("v51 stage-19 family collapsed onto stage-6 values",
      (s) => s.replace(
        "    if (mode == -1 || mode == 14) {\n      if (mode == -1) {\n        return 5;\n      }\n      if (variant != 12) {",
        "    if (mode == -1 || mode == 14) {\n      if (mode == -1) {\n        return 1;\n      }\n      if (variant != 12) {"),
      (w) => {
        assert.equal(w.stageMode829a10(19, -1, 0), 5,
          "stage 19 mode -1 must yield 5");
      });
    withMutant("v51 {13,26} arm-10 transform shifted",
      (s) => s.replace(
        "    if (stage == 13 || stage == 26) {\n      if (mode == 10) {\n        return mode - 4;\n      }\n    }",
        "    if (stage == 13 || stage == 26) {\n      if (mode == 10) {\n        return mode - 5;\n      }\n    }"),
      (w) => {
        assert.equal(w.stageMode829a10(26, 10, 8), 6,
          "{13,26}x10 transform is mode-4");
      });
  } finally {
    writeRetry(source, original);
    assert.equal(shaOf(readFileSync(source)), origHash, "final restore");
  }
});
